def list_instances(limit=None, cursor=None, region_id=None, type_id=None, status=None, label=None, tags=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_instances"

    # best-effort request log (schema doesn't define it, but create if absent)
    def _log(status_code, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": "req_" + now.replace(":", "").replace("-", "").replace("Z", "") + "_" + str(len(logs) + 1),
            "ts": now,
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "request": {
                "limit": limit, "cursor": cursor, "region_id": region_id, "type_id": type_id,
                "status": status, "label": label, "tags": tags, "sort_by": sort_by, "sort_order": sort_order
            }
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if limit is not None:
        if not isinstance(limit, int):
            _log("VALIDATION_ERROR", "limit must be integer")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit <= 0:
            _log("VALIDATION_ERROR", "limit must be positive")
            return _err("VALIDATION_ERROR", "limit must be positive")
        if limit > 500:
            _log("VALIDATION_ERROR", "limit too large")
            return _err("VALIDATION_ERROR", "limit exceeds maximum of 500")
    else:
        limit = 100

    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "cursor must be string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    allowed_status = {"provisioning", "running", "offline", "rebooting", "shutting_down", "booting", "resizing",
                      "cloning", "rebuilding", "rescuing", "deleting", "deleted", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("VALIDATION_ERROR", "invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed_status)))

    allowed_sort_by = {"created_at", "updated_at", "label", "status"}
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
            _log("VALIDATION_ERROR", "invalid sort_by")
            return _err("VALIDATION_ERROR", "Invalid sort_by", allowed=list(sorted(allowed_sort_by)))
    else:
        sort_by = "created_at"

    allowed_sort_order = {"asc", "desc"}
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
            _log("VALIDATION_ERROR", "invalid sort_order")
            return _err("VALIDATION_ERROR", "Invalid sort_order", allowed=list(sorted(allowed_sort_order)))
    else:
        sort_order = "desc"

    if region_id is not None and not isinstance(region_id, str):
        _log("VALIDATION_ERROR", "region_id must be string")
        return _err("VALIDATION_ERROR", "region_id must be a string")
    if type_id is not None and not isinstance(type_id, str):
        _log("VALIDATION_ERROR", "type_id must be string")
        return _err("VALIDATION_ERROR", "type_id must be a string")
    if label is not None and not isinstance(label, str):
        _log("VALIDATION_ERROR", "label must be string")
        return _err("VALIDATION_ERROR", "label must be a string")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log("VALIDATION_ERROR", "tags must be array of strings")
            return _err("VALIDATION_ERROR", "tags must be an array of strings")

    # Cursor decode: base64url of "offset:<int>"
    offset = 0
    if cursor:
        try:
            raw = cursor.encode("utf-8")
            # pad
            pad = b"=" * ((4 - len(raw) % 4) % 4)
            decoded = base64.urlsafe_b64decode(raw + pad).decode("utf-8")
            if not decoded.startswith("offset:"):
                _log("VALIDATION_ERROR", "invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = int(decoded.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            _log("VALIDATION_ERROR", "invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    rows = _load("linode_instances.json")
    if not isinstance(rows, list):
        rows = []

    # Exclude soft-deleted
    filtered = [r for r in rows if isinstance(r, dict) and not r.get("deleted_at")]

    def _match(r):
        if region_id is not None and r.get("region_id") != region_id:
            return False
        if type_id is not None and r.get("type_id") != type_id:
            return False
        if status is not None and r.get("status") != status:
            return False
        if label is not None and r.get("label") != label:
            return False
        if tags is not None:
            rt = r.get("tags") or []
            if not isinstance(rt, list):
                return False
            for t in tags:
                if t not in rt:
                    return False
        return True

    filtered = [r for r in filtered if _match(r)]
    total = len(filtered)

    def _dt_key(v):
        if v is None:
            return ""
        if isinstance(v, str):
            return v
        return str(v)

    reverse = (sort_order == "desc")
    if sort_by in ("created_at", "updated_at"):
        filtered.sort(key=lambda r: _dt_key(r.get(sort_by)), reverse=reverse)
    else:
        filtered.sort(key=lambda r: ("" if r.get(sort_by) is None else str(r.get(sort_by)).lower()), reverse=reverse)

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        token = f"offset:{next_offset}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor
        }
    }
    _log("OK")
    return resp

def get_instance(instance_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_instance"

    def _log(status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs.append({
            "id": "req_" + now.replace(":", "").replace("-", "").replace("Z", "") + "_" + str(len(logs) + 1),
            "ts": now,
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "request": {"instance_id": instance_id}
        })
        _save("request_logs.json", logs)

    if not isinstance(instance_id, str):
        _log("VALIDATION_ERROR", "instance_id must be string")
        return _err("VALIDATION_ERROR", "instance_id must be a string")
    if not re.match(r"^lin_01H8[0-9A-Z]{15,}$", instance_id):
        _log("VALIDATION_ERROR", "instance_id format invalid")
        return _err("VALIDATION_ERROR", "instance_id does not match required format")

    rows = _load("linode_instances.json")
    if not isinstance(rows, list):
        rows = []
    inst = next((r for r in rows if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log("NOT_FOUND", "instance not found")
        return _err("NOT_FOUND", "Instance not found")

    # For normal visibility, exclude soft-deleted
    if inst.get("deleted_at"):
        _log("NOT_FOUND", "instance deleted")
        return _err("NOT_FOUND", "Instance not found")

    _log("OK")
    return {"data": inst}

def create_instance(label, region_id, type_id, image_id=None, kernel_id=None, placement_group_id=None, backups_enabled=None, tags=None, configs=None, disks=None, **_extra):
    import json, os, datetime, secrets, time, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_instance"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None, operation_id=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()

        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate types (relax overly-strict regex; accept datastore ids like lin_01J...)
    if not isinstance(label, str) or not label.strip():
        e = _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(region_id, str) or not region_id:
        e = _err("VALIDATION_ERROR", "region_id must be a string", field="region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(type_id, str) or not type_id:
        e = _err("VALIDATION_ERROR", "type_id must be a string", field="type_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if image_id is not None and not isinstance(image_id, str):
        e = _err("VALIDATION_ERROR", "image_id must be a string", field="image_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if kernel_id is not None and not isinstance(kernel_id, str):
        e = _err("VALIDATION_ERROR", "kernel_id must be a string", field="kernel_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if placement_group_id is not None and not isinstance(placement_group_id, str):
        e = _err("VALIDATION_ERROR", "placement_group_id must be a string", field="placement_group_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if backups_enabled is None:
        backups_enabled = False
    if not isinstance(backups_enabled, bool):
        e = _err("VALIDATION_ERROR", "backups_enabled must be a boolean", field="backups_enabled")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if tags is None:
        tags = []
    if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
        e = _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if configs is None:
        configs = []
    if not isinstance(configs, list):
        e = _err("VALIDATION_ERROR", "configs must be an array", field="configs")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if disks is None:
        disks = []
    if not isinstance(disks, list):
        e = _err("VALIDATION_ERROR", "disks must be an array", field="disks")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    infra = _load("infra_catalog.json")
    infra_rows = infra if isinstance(infra, list) else (infra.get("rows") if isinstance(infra, dict) else [])
    if not isinstance(infra_rows, list):
        infra_rows = []
    def _find_catalog(cat_id):
        for r in infra_rows:
            if isinstance(r, dict) and r.get("id") == cat_id:
                return r
        return None

    reg = _find_catalog(region_id)
    if not reg or reg.get("catalog_type") != "region":
        e = _err("VALIDATION_ERROR", "region_id must reference an infra_catalog item with catalog_type='region'", field="region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if reg.get("status") != "active":
        e = _err("VALIDATION_ERROR", "region_id must reference an active region catalog item", field="region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    ty = _find_catalog(type_id)
    if not ty or ty.get("catalog_type") != "linode_type":
        e = _err("VALIDATION_ERROR", "type_id must reference an infra_catalog item with catalog_type='linode_type'", field="type_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if ty.get("status") != "active":
        e = _err("VALIDATION_ERROR", "type_id must reference an active linode_type catalog item", field="type_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if kernel_id is not None:
        k = _find_catalog(kernel_id)
        # Relax: accept either a real kernel catalog id OR a provider/region-like slug; only validate if it is a known catalog id
        if k is not None:
            if k.get("catalog_type") != "kernel":
                e = _err("VALIDATION_ERROR", "kernel_id must reference an infra_catalog item with catalog_type='kernel'", field="kernel_id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            if k.get("status") != "active":
                e = _err("VALIDATION_ERROR", "kernel_id must reference an active kernel catalog item", field="kernel_id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []
    pg_row = None
    if placement_group_id is not None:
        # Accept either actual placement group id, or tolerate caller passing a catalog id (as seen in audit args)
        for r in ns:
            if isinstance(r, dict) and r.get("id") == placement_group_id and r.get("deleted_at") is None:
                pg_row = r
                break
        if pg_row is None:
            # If it's not found as a placement group, don't hard-fail on format; treat as unknown reference.
            e = _err("NOT_FOUND", "placement_group_id not found", field="placement_group_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if pg_row.get("resource_type") != "placement_group":
            e = _err("VALIDATION_ERROR", "placement_group_id must reference a placement_group resource", field="placement_group_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if pg_row.get("status") not in ("active", "updating"):
            e = _err("CONFLICT", "placement group is not in an assignable state", field="placement_group_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if pg_row.get("region_id") and pg_row.get("region_id") != region_id:
            e = _err("CONFLICT", "placement group and instance must be in the same region_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []

    # Enforce unique(label, region_id) where deleted_at is null
    for inst in instances:
        if not isinstance(inst, dict):
            continue
        if inst.get("deleted_at") is None and inst.get("label") == label and inst.get("region_id") == region_id:
            e = _err("CONFLICT", "An instance with this label already exists in the specified region_id", field="label")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    # Validate embedded configs/disks minimally, ensure unique ids within instance and disk size rule
    seen_cfg = set()
    norm_configs = []
    for c in configs:
        if not isinstance(c, dict):
            e = _err("VALIDATION_ERROR", "configs entries must be objects", field="configs")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        cc = copy.deepcopy(c)
        cid = cc.get("config_id")
        if cid is not None:
            if not isinstance(cid, str) or not cid:
                e = _err("VALIDATION_ERROR", "configs[*].config_id must be a non-empty string when provided", field="configs.config_id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            if cid in seen_cfg:
                e = _err("CONFLICT", "configs[*].config_id must be unique within instance", field="configs.config_id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            seen_cfg.add(cid)
        if cc.get("label") is None:
            cc["label"] = ""
        if "created_at" not in cc:
            cc["created_at"] = now
        if "updated_at" not in cc:
            cc["updated_at"] = now
        norm_configs.append(cc)

    seen_disk = set()
    norm_disks = []
    for d in disks:
        if not isinstance(d, dict):
            e = _err("VALIDATION_ERROR", "disks entries must be objects", field="disks")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        dd = copy.deepcopy(d)
        did = dd.get("disk_id")
        if did is not None:
            if not isinstance(did, str) or not did:
                e = _err("VALIDATION_ERROR", "disks[*].disk_id must be a non-empty string when provided", field="disks.disk_id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            if did in seen_disk:
                e = _err("CONFLICT", "disks[*].disk_id must be unique within instance", field="disks.disk_id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            seen_disk.add(did)
        if "size_mb" in dd and dd["size_mb"] is not None:
            try:
                sz = int(dd["size_mb"])
            except Exception:
                e = _err("VALIDATION_ERROR", "disks[*].size_mb must be an integer", field="disks.size_mb")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            if sz < 256:
                e = _err("VALIDATION_ERROR", "disks[*].size_mb must be >= 256", field="disks.size_mb")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            dd["size_mb"] = sz
        if "created_at" not in dd:
            dd["created_at"] = now
        if "updated_at" not in dd:
            dd["updated_at"] = now
        norm_disks.append(dd)

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}".replace("-", "")  # non-guessable; datastore doesn't require strict format

    new_id = _new_id("lin")
    new_inst = {
        "id": new_id,
        "label": label,
        "region_id": region_id,
        "type_id": type_id,
        "kernel_id": kernel_id,
        "image_id": image_id,
        "placement_group_id": placement_group_id,
        "backups_enabled": backups_enabled,
        "tags": tags,
        "status": "provisioning",
        "last_operation_id": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
        "configs": norm_configs,
        "disks": norm_disks,
        "stats_timeseries": [],
    }

    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []
    # ensure only one running op per resource - not relevant for create; create op targets new resource id
    op_id = _new_id("op")
    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": new_id,
        "operation_type": "create",
        "status": "succeeded",
        "request": {
            "label": label,
            "region_id": region_id,
            "type_id": type_id,
            "image_id": image_id,
            "kernel_id": kernel_id,
            "placement_group_id": placement_group_id,
            "backups_enabled": backups_enabled,
            "tags": tags,
            "configs": configs,
            "disks": disks,
        },
        "result": {"id": new_id},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    new_inst["last_operation_id"] = op_id

    instances.append(new_inst)
    operations.append(op)
    _save("linode_instances.json", instances)
    _save("operations.json", operations)

    _log("ok", resource={"collection": "linode_instances", "id": new_id}, operation_id=op_id)
    return {"instance": new_inst, "operation": op}

def update_instance(instance_id, label=None, kernel_id=None, placement_group_id=None, backups_enabled=None, tags=None, configs=None, disks=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_instance"

    def _log(status_code, message=None, op_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs.append({
            "id": "req_" + now.replace(":", "").replace("-", "").replace("Z", "") + "_" + str(len(logs) + 1),
            "ts": now,
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "operation_id": op_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "request": {
                "instance_id": instance_id,
                "label": label,
                "kernel_id": kernel_id,
                "placement_group_id": placement_group_id,
                "backups_enabled": backups_enabled,
                "tags": tags,
                "configs": configs,
                "disks": disks
            }
        })
        _save("request_logs.json", logs)

    if not isinstance(instance_id, str):
        _log("VALIDATION_ERROR", "instance_id must be string")
        return _err("VALIDATION_ERROR", "instance_id must be a string")
    if not re.match(r"^lin_01H8[0-9A-Z]{15,}$", instance_id):
        _log("VALIDATION_ERROR", "instance_id format invalid")
        return _err("VALIDATION_ERROR", "instance_id does not match required format")

    if label is not None and (not isinstance(label, str) or not label.strip()):
        _log("VALIDATION_ERROR", "label invalid")
        return _err("VALIDATION_ERROR", "label must be a non-empty string")
    if kernel_id is not None and not isinstance(kernel_id, str):
        _log("VALIDATION_ERROR", "kernel_id invalid")
        return _err("VALIDATION_ERROR", "kernel_id must be a string")
    if placement_group_id is not None:
        if not isinstance(placement_group_id, str) or not re.match(r"^pg_01H8[0-9A-Z]{15,}$", placement_group_id):
            _log("VALIDATION_ERROR", "placement_group_id invalid")
            return _err("VALIDATION_ERROR", "placement_group_id does not match required format")
    if backups_enabled is not None and not isinstance(backups_enabled, bool):
        _log("VALIDATION_ERROR", "backups_enabled invalid")
        return _err("VALIDATION_ERROR", "backups_enabled must be boolean")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log("VALIDATION_ERROR", "tags invalid")
            return _err("VALIDATION_ERROR", "tags must be an array of strings")
    if configs is not None and not isinstance(configs, list):
        _log("VALIDATION_ERROR", "configs invalid")
        return _err("VALIDATION_ERROR", "configs must be an array")
    if disks is not None and not isinstance(disks, list):
        _log("VALIDATION_ERROR", "disks invalid")
        return _err("VALIDATION_ERROR", "disks must be an array")

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []

    idx = None
    inst = None
    for i, r in enumerate(instances):
        if isinstance(r, dict) and r.get("id") == instance_id:
            idx = i
            inst = r
            break
    if inst is None:
        _log("NOT_FOUND", "instance not found")
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("deleted_at"):
        _log("NOT_FOUND", "instance deleted")
        return _err("NOT_FOUND", "Instance not found")

    # Disallow updates during transient states
    transient = {"provisioning", "rebooting", "shutting_down", "booting", "resizing", "cloning", "rebuilding", "rescuing", "deleting"}
    if inst.get("status") in transient:
        _log("CONFLICT", "instance state does not allow update")
        return _err("CONFLICT", "Update not allowed for instance in current status", status=inst.get("status"))

    infra = _load("infra_catalog.json")
    if not isinstance(infra, list):
        infra = []

    def _active_catalog(cat_type, cid):
        return next((c for c in infra if isinstance(c, dict) and c.get("id") == cid and c.get("catalog_type") == cat_type and c.get("status") == "active"), None)

    if kernel_id is not None and not _active_catalog("kernel", kernel_id):
        _log("VALIDATION_ERROR", "kernel_id unknown or inactive")
        return _err("VALIDATION_ERROR", "kernel_id must reference an active kernel catalog item")

    # label uniqueness per region (where not deleted)
    if label is not None and label != inst.get("label"):
        for r in instances:
            if isinstance(r, dict) and not r.get("deleted_at") and r.get("id") != instance_id and r.get("region_id") == inst.get("region_id") and r.get("label") == label:
                _log("CONFLICT", "label already exists in region")
                return _err("CONFLICT", "Instance label must be unique per region")

    # placement group checks and single membership
    if placement_group_id is not None:
        ns = _load("network_security.json")
        if not isinstance(ns, list):
            ns = []
        pg = next((r for r in ns if isinstance(r, dict) and r.get("id") == placement_group_id and r.get("resource_type") == "placement_group" and not r.get("deleted_at")), None)
        if not pg:
            _log("NOT_FOUND", "placement group not found")
            return _err("NOT_FOUND", "Placement group not found")
        if pg.get("status") != "active":
            _log("CONFLICT", "placement group not active")
            return _err("CONFLICT", "Placement group is not active")
        if pg.get("region_id") != inst.get("region_id"):
            _log("CONFLICT", "region mismatch")
            return _err("CONFLICT", "Placement group region must match instance region")
        # at most one placement group: implied by single field; nothing else needed.
    # If explicitly set to None: allow unassign
    # Note: parameter default is None meaning "not provided"; can't distinguish. So only apply when string provided.
    # Therefore unassign via this tool isn't possible; vendor parameter allows null sometimes, but schema doesn't here.

    now_dt = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_01H8{secrets.token_hex(10).upper()}"

    # Validate/replace embedded configs/disks if provided
    if configs is not None:
        new_configs = []
        seen = set()
        for c in configs:
            if not isinstance(c, dict):
                _log("VALIDATION_ERROR", "config item invalid")
                return _err("VALIDATION_ERROR", "Each config must be an object")
            cid = c.get("config_id") or _new_id("cfg")
            if not isinstance(cid, str) or not cid:
                _log("VALIDATION_ERROR", "config_id invalid")
                return _err("VALIDATION_ERROR", "config_id must be a string")
            if cid in seen:
                _log("VALIDATION_ERROR", "duplicate config_id")
                return _err("VALIDATION_ERROR", "configs[*].config_id must be unique within instance")
            seen.add(cid)
            ck = c.get("kernel_id", inst.get("kernel_id"))
            if ck is not None:
                if not isinstance(ck, str):
                    _log("VALIDATION_ERROR", "config.kernel_id invalid")
                    return _err("VALIDATION_ERROR", "configs[*].kernel_id must be a string")
                if not _active_catalog("kernel", ck):
                    _log("VALIDATION_ERROR", "config.kernel_id inactive")
                    return _err("VALIDATION_ERROR", "configs[*].kernel_id must reference an active kernel catalog item")
            new_configs.append({
                "config_id": cid,
                "label": c.get("label") if isinstance(c.get("label"), str) else (f"{inst.get('label','linode')}-config" if c.get("label") is None else str(c.get("label"))),
                "kernel_id": ck,
                "devices": c.get("devices") if isinstance(c.get("devices"), dict) else {},
                "helpers": c.get("helpers") if isinstance(c.get("helpers"), dict) else {},
                "comments": c.get("comments") if isinstance(c.get("comments"), str) else "",
                "root_device": c.get("root_device") if isinstance(c.get("root_device"), str) else "",
                "status": c.get("status") if isinstance(c.get("status"), str) else "active",
                "created_at": c.get("created_at") if isinstance(c.get("created_at"), str) else now_dt,
                "updated_at": now_dt
            })
        inst["configs"] = new_configs

    if disks is not None:
        new_disks = []
        seen = set()
        for d in disks:
            if not isinstance(d, dict):
                _log("VALIDATION_ERROR", "disk item invalid")
                return _err("VALIDATION_ERROR", "Each disk must be an object")
            did = d.get("disk_id") or _new_id("dsk")
            if not isinstance(did, str) or not did:
                _log("VALIDATION_ERROR", "disk_id invalid")
                return _err("VALIDATION_ERROR", "disk_id must be a string")
            if did in seen:
                _log("VALIDATION_ERROR", "duplicate disk_id")
                return _err("VALIDATION_ERROR", "disks[*].disk_id must be unique within instance")
            seen.add(did)
            size_mb = d.get("size_mb")
            if not isinstance(size_mb, int):
                _log("VALIDATION_ERROR", "disk size_mb invalid")
                return _err("VALIDATION_ERROR", "disks[*].size_mb must be an integer")
            if size_mb < 256:
                _log("VALIDATION_ERROR", "disk size_mb too small")
                return _err("VALIDATION_ERROR", "disks[*].size_mb must be >= 256")
            new_disks.append({
                "disk_id": did,
                "label": d.get("label") if isinstance(d.get("label"), str) else f"{inst.get('label','linode')}-disk",
                "filesystem": d.get("filesystem") if isinstance(d.get("filesystem"), str) else "ext4",
                "size_mb": size_mb,
                "status": d.get("status") if isinstance(d.get("status"), str) else "ready",
                "created_at": d.get("created_at") if isinstance(d.get("created_at"), str) else now_dt,
                "updated_at": now_dt
            })
        inst["disks"] = new_disks

    # Apply scalar fields
    changed = {}
    if label is not None and label != inst.get("label"):
        inst["label"] = label
        changed["label"] = label
    if kernel_id is not None and kernel_id != inst.get("kernel_id"):
        inst["kernel_id"] = kernel_id
        changed["kernel_id"] = kernel_id
    if placement_group_id is not None and placement_group_id != inst.get("placement_group_id"):
        inst["placement_group_id"] = placement_group_id
        changed["placement_group_id"] = placement_group_id
    if backups_enabled is not None and backups_enabled != inst.get("backups_enabled"):
        inst["backups_enabled"] = backups_enabled
        changed["backups_enabled"] = backups_enabled
    if tags is not None:
        inst["tags"] = tags
        changed["tags"] = tags
    if configs is not None:
        changed["configs"] = "replaced"
    if disks is not None:
        changed["disks"] = "replaced"

    if not changed:
        _log("CONFLICT", "no changes supplied")
        return _err("CONFLICT", "No changes to apply")

    # Create operation, ensure no running op on this resource
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []
    for o in ops:
        if isinstance(o, dict) and o.get("resource_collection") == "linode_instances" and o.get("resource_id") == instance_id and o.get("status") == "running":
            _log("CONFLICT", "operation in progress")
            return _err("CONFLICT", "Another operation is currently running for this instance")

    op_id = _new_id("op")
    op_now = now_dt
    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": instance_id,
        "operation_type": "update",
        "status": "succeeded",
        "request": {
            "instance_id": instance_id,
            "changes": changed
        },
        "result": {"updated_fields": list(changed.keys())},
        "error_message": None,
        "created_at": op_now,
        "updated_at": op_now,
        "started_at": op_now,
        "finished_at": op_now
    }
    ops.append(op)

    inst["last_operation_id"] = op_id
    inst["updated_at"] = now_dt
    instances[idx] = inst

    _save("operations.json", ops)
    _save("linode_instances.json", instances)

    _log("OK", op_id=op_id)
    return {"data": inst}

def boot_instance(instance_id, **_extra):
    import json, os, datetime, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "boot_instance"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None, operation_id=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                if sum(1 for r in logs if (_parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= cutoff) >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                if sum(1 for r in logs if (_parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= cutoff) >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(instance_id, str) or not instance_id:
        e = _err("VALIDATION_ERROR", "instance_id must be a string", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id and r.get("deleted_at") is None:
            inst = r
            break
    if not inst:
        e = _err("NOT_FOUND", "Instance not found", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Enforce power action rule: boot only from offline
    if inst.get("status") != "offline":
        e = _err("CONFLICT", "boot is only allowed when instance status is 'offline'")
        _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "linode_instances", "id": instance_id})
        return e

    # operations: only one running per resource
    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []
    for op in operations:
        if isinstance(op, dict) and op.get("resource_collection") == "linode_instances" and op.get("resource_id") == instance_id and op.get("status") == "running":
            e = _err("CONFLICT", "Another operation is currently running for this instance")
            _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "linode_instances", "id": instance_id})
            return e

    transitions = {
        "provisioning": ["running", "offline", "error"],
        "running": ["rebooting", "shutting_down", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "offline": ["booting", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "booting": ["running", "error"],
        "shutting_down": ["offline", "error"],
        "rebooting": ["running", "error"],
        "resizing": ["running", "offline", "error"],
        "cloning": ["running", "offline", "error"],
        "rebuilding": ["running", "offline", "error"],
        "rescuing": ["running", "offline", "error"],
        "deleting": ["deleted", "error"],
        "error": ["offline", "deleting"],
        "deleted": [],
    }
    cur = inst.get("status")
    if "booting" not in transitions.get(cur, []):
        e = _err("INVALID_TRANSITION", f"Cannot transition instance from '{cur}' to 'booting'")
        _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "linode_instances", "id": instance_id})
        return e

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    op_id = _new_id("op")
    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": instance_id,
        "operation_type": "boot",
        "status": "running",
        "request": {"instance_id": instance_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    operations.append(op)

    inst["status"] = "booting"
    inst["last_operation_id"] = op_id
    inst["updated_at"] = now

    _save("operations.json", operations)
    _save("linode_instances.json", instances)

    _log("ok", resource={"collection": "linode_instances", "id": instance_id}, operation_id=op_id)
    return {"operation": op, "instance": inst}

def resize_instance(instance_id, type_id, allow_auto_disk_resize=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Best-effort request logging (schema does not define a request log collection)
    def _log(endpoint, status, detail=None):
        try:
            fn = "request_log.json"
            rows = _load(fn)
            rows.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(fn, rows)
        except Exception:
            pass

    # Validation
    if not isinstance(instance_id, str) or not re.match(r"^lin_01H8[0-9A-Z]{15,}$", instance_id):
        _log("resize_instance", "error", "invalid instance_id")
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")
    if not isinstance(type_id, str) or not type_id.strip():
        _log("resize_instance", "error", "invalid type_id")
        return _err("VALIDATION_ERROR", "type_id is required.", field="type_id")
    if allow_auto_disk_resize is not None and not isinstance(allow_auto_disk_resize, bool):
        _log("resize_instance", "error", "invalid allow_auto_disk_resize")
        return _err("VALIDATION_ERROR", "allow_auto_disk_resize must be boolean.", field="allow_auto_disk_resize")

    instances = _load("linode_instances.json")
    ops = _load("operations.json")
    catalog = _load("infra_catalog.json")

    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst or inst.get("deleted_at") is not None:
        _log("resize_instance", "error", "instance not found")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    # Resolve type_id: accept exact catalog id OR slug in spec.slug for linode_type
    target_type = None
    for c in catalog:
        if c.get("catalog_type") != "linode_type":
            continue
        if c.get("id") == type_id or (isinstance(c.get("spec"), dict) and c["spec"].get("slug") == type_id):
            target_type = c
            break
    if not target_type:
        _log("resize_instance", "error", "type not found")
        return _err("VALIDATION_ERROR", "Unknown type_id.", field="type_id")
    if target_type.get("status") != "active":
        _log("resize_instance", "error", "type not active")
        return _err("VALIDATION_ERROR", "Requested type_id is not active.", field="type_id")

    # Only one running op per resource
    for o in ops:
        if o.get("resource_collection") == "linode_instances" and o.get("resource_id") == instance_id and o.get("status") == "running":
            _log("resize_instance", "error", "operation conflict")
            return _err("CONFLICT", "Another operation is currently running for this instance.", operation_id=o.get("id"))

    # Instance lifecycle transition: must be able to go to resizing
    transitions = {
        "provisioning": ["running", "offline", "error"],
        "running": ["rebooting", "shutting_down", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "offline": ["booting", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "booting": ["running", "error"],
        "shutting_down": ["offline", "error"],
        "rebooting": ["running", "error"],
        "resizing": ["running", "offline", "error"],
        "cloning": ["running", "offline", "error"],
        "rebuilding": ["running", "offline", "error"],
        "rescuing": ["running", "offline", "error"],
        "deleting": ["deleted", "error"],
        "error": ["offline", "deleting"],
        "deleted": []
    }
    cur_status = inst.get("status")
    if cur_status not in transitions or "resizing" not in transitions[cur_status]:
        _log("resize_instance", "error", "invalid transition")
        return _err("INVALID_TRANSITION", f"Cannot resize instance from status '{cur_status}'.", from_status=cur_status, to_status="resizing")

    # Disk capacity rule
    spec = target_type.get("spec") if isinstance(target_type.get("spec"), dict) else {}
    disk_mb = spec.get("disk_mb")
    if not isinstance(disk_mb, int) or disk_mb <= 0:
        _log("resize_instance", "error", "type spec invalid")
        return _err("VALIDATION_ERROR", "Requested type_id has invalid disk specification.", field="type_id")

    disks = inst.get("disks") if isinstance(inst.get("disks"), list) else []
    total_mb = 0
    for d in disks:
        sz = d.get("size_mb")
        if isinstance(sz, int):
            total_mb += sz
    if total_mb > disk_mb:
        _log("resize_instance", "error", "disk exceeds plan")
        return _err("VALIDATION_ERROR", "Current disk allocation exceeds destination plan disk capacity.", current_total_mb=total_mb, destination_disk_mb=disk_mb)

    # Apply auto disk resize (best-effort, simplistic): grow root disk (first disk) to fill remaining capacity.
    changed_disks = []
    if allow_auto_disk_resize:
        remaining = disk_mb - total_mb
        if remaining > 0 and len(disks) > 0:
            # Prefer disk labeled "root" if present
            idx = 0
            for i, d in enumerate(disks):
                if isinstance(d.get("label"), str) and d.get("label").lower() in ("root", "rootfs", "boot"):
                    idx = i
                    break
            if isinstance(disks[idx].get("size_mb"), int):
                disks[idx]["size_mb"] += remaining
                disks[idx]["updated_at"] = now
                changed_disks.append({"disk_id": disks[idx].get("disk_id"), "new_size_mb": disks[idx]["size_mb"]})
                total_mb = disk_mb

    # Create operation
    op_id = "op_" + uuid.uuid4().hex
    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": instance_id,
        "operation_type": "resize",
        "status": "running",
        "request": {
            "instance_id": instance_id,
            "type_id": target_type.get("id"),
            "allow_auto_disk_resize": bool(allow_auto_disk_resize) if allow_auto_disk_resize is not None else False
        },
        "result": {"changed_disks": changed_disks} if changed_disks else None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op)

    # Mutate instance
    inst["status"] = "resizing"
    inst["type_id"] = target_type.get("id")
    inst["disks"] = disks
    inst["last_operation_id"] = op_id
    inst["updated_at"] = now

    _save("operations.json", ops)
    _save("linode_instances.json", instances)

    _log("resize_instance", "ok", None)
    return {
        "operation": op,
        "instance": inst
    }

def clone_instance(instance_id, label, region_id, type_id, copy_backups=None, **_extra):
    import json, os, datetime, secrets, time, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "clone_instance"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None, operation_id=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(instance_id, str) or not instance_id:
        e = _err("VALIDATION_ERROR", "instance_id must be a string", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(label, str) or not label.strip():
        e = _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(region_id, str) or not region_id:
        e = _err("VALIDATION_ERROR", "region_id must be a string", field="region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(type_id, str) or not type_id:
        e = _err("VALIDATION_ERROR", "type_id must be a string", field="type_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if copy_backups is not None and not isinstance(copy_backups, bool):
        e = _err("VALIDATION_ERROR", "copy_backups must be a boolean", field="copy_backups")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    src = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id and r.get("deleted_at") is None:
            src = r
            break
    if not src:
        e = _err("NOT_FOUND", "Source instance not found", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if src.get("status") not in ("running", "offline"):
        e = _err("CONFLICT", "Source instance must be in 'running' or 'offline' to clone")
        _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "linode_instances", "id": instance_id})
        return e

    # validate catalog
    infra = _load("infra_catalog.json")
    infra_rows = infra if isinstance(infra, list) else (infra.get("rows") if isinstance(infra, dict) else [])
    if not isinstance(infra_rows, list):
        infra_rows = []
    def _find_catalog(cid):
        for rr in infra_rows:
            if isinstance(rr, dict) and rr.get("id") == cid:
                return rr
        return None
    reg = _find_catalog(region_id)
    if not reg or reg.get("catalog_type") != "region" or reg.get("status") != "active":
        e = _err("VALIDATION_ERROR", "region_id must reference an active region catalog item", field="region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    ty = _find_catalog(type_id)
    if not ty or ty.get("catalog_type") != "linode_type" or ty.get("status") != "active":
        e = _err("VALIDATION_ERROR", "type_id must reference an active linode_type catalog item", field="type_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # unique(label, region_id) where deleted_at is null
    for inst in instances:
        if isinstance(inst, dict) and inst.get("deleted_at") is None and inst.get("label") == label and inst.get("region_id") == region_id:
            e = _err("CONFLICT", "An instance with this label already exists in the specified region_id", field="label")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []
    # one running operation per source instance prevents clone
    for op in operations:
        if isinstance(op, dict) and op.get("resource_collection") == "linode_instances" and op.get("resource_id") == instance_id and op.get("status") == "running":
            e = _err("CONFLICT", "Another operation is currently running for the source instance")
            _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "linode_instances", "id": instance_id})
            return e

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    new_id = _new_id("lin")
    op_id = _new_id("op")

    # create clone row (initially cloning)
    new_inst = copy.deepcopy(src)
    new_inst["id"] = new_id
    new_inst["label"] = label
    new_inst["region_id"] = region_id
    new_inst["type_id"] = type_id
    new_inst["created_at"] = now
    new_inst["updated_at"] = now
    new_inst["deleted_at"] = None
    new_inst["status"] = "cloning"
    new_inst["last_operation_id"] = op_id
    # keep configs/disks embedded, but ensure embedded ids remain unique within instance (they are copied as-is)
    # stats start empty for a new clone
    new_inst["stats_timeseries"] = []

    # update source status to cloning (legal from running/offline)
    transitions = {
        "provisioning": ["running", "offline", "error"],
        "running": ["rebooting", "shutting_down", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "offline": ["booting", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "booting": ["running", "error"],
        "shutting_down": ["offline", "error"],
        "rebooting": ["running", "error"],
        "resizing": ["running", "offline", "error"],
        "cloning": ["running", "offline", "error"],
        "rebuilding": ["running", "offline", "error"],
        "rescuing": ["running", "offline", "error"],
        "deleting": ["deleted", "error"],
        "error": ["offline", "deleting"],
        "deleted": [],
    }
    cur = src.get("status")
    if "cloning" not in transitions.get(cur, []):
        e = _err("INVALID_TRANSITION", f"Cannot transition instance from '{cur}' to 'cloning'")
        _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "linode_instances", "id": instance_id})
        return e
    src["status"] = "cloning"
    src["last_operation_id"] = op_id
    src["updated_at"] = now

    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": instance_id,
        "operation_type": "clone",
        "status": "running",
        "request": {
            "instance_id": instance_id,
            "label": label,
            "region_id": region_id,
            "type_id": type_id,
            "copy_backups": bool(copy_backups) if copy_backups is not None else False,
        },
        "result": {"new_instance_id": new_id},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    operations.append(op)
    instances.append(new_inst)

    _save("operations.json", operations)
    _save("linode_instances.json", instances)

    _log("ok", resource={"collection": "linode_instances", "id": instance_id}, operation_id=op_id)
    return {"operation": op, "source_instance": src, "cloned_instance": new_inst}

def rebuild_instance(instance_id, image_id, root_pass, preserve_data=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, detail=None):
        try:
            fn = "request_log.json"
            rows = _load(fn)
            rows.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(fn, rows)
        except Exception:
            pass

    # Validation
    if not isinstance(instance_id, str) or not re.match(r"^lin_01H8[0-9A-Z]{15,}$", instance_id):
        _log("rebuild_instance", "error", "invalid instance_id")
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")
    if not isinstance(image_id, str) or not image_id.strip():
        _log("rebuild_instance", "error", "invalid image_id")
        return _err("VALIDATION_ERROR", "image_id is required.", field="image_id")
    if not isinstance(root_pass, str) or not root_pass:
        _log("rebuild_instance", "error", "invalid root_pass")
        return _err("VALIDATION_ERROR", "root_pass is required.", field="root_pass")
    if preserve_data is not None and not isinstance(preserve_data, bool):
        _log("rebuild_instance", "error", "invalid preserve_data")
        return _err("VALIDATION_ERROR", "preserve_data must be boolean.", field="preserve_data")

    # Minimal password policy: 8-128, at least 1 upper, 1 lower, 1 digit
    if len(root_pass) < 8 or len(root_pass) > 128:
        _log("rebuild_instance", "error", "weak password length")
        return _err("VALIDATION_ERROR", "root_pass does not meet password requirements.", field="root_pass")
    if not re.search(r"[A-Z]", root_pass) or not re.search(r"[a-z]", root_pass) or not re.search(r"[0-9]", root_pass):
        _log("rebuild_instance", "error", "weak password composition")
        return _err("VALIDATION_ERROR", "root_pass does not meet password requirements.", field="root_pass")

    instances = _load("linode_instances.json")
    ops = _load("operations.json")
    catalog = _load("infra_catalog.json")

    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst or inst.get("deleted_at") is not None:
        _log("rebuild_instance", "error", "instance not found")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    # Ensure no other running op
    for o in ops:
        if o.get("resource_collection") == "linode_instances" and o.get("resource_id") == instance_id and o.get("status") == "running":
            _log("rebuild_instance", "error", "op conflict")
            return _err("CONFLICT", "Another operation is currently running for this instance.", operation_id=o.get("id"))

    # Validate image exists as catalog item (modeled as catalog item per schema note); accept id or spec.slug match
    img = None
    for c in catalog:
        # No explicit catalog_type for images in schema; treat any item with matching id/slug as allowed "available".
        if c.get("id") == image_id or (isinstance(c.get("spec"), dict) and c["spec"].get("slug") == image_id):
            img = c
            break
    if not img:
        _log("rebuild_instance", "error", "unknown image")
        return _err("VALIDATION_ERROR", "Unknown image_id.", field="image_id")
    if img.get("status") not in ("active", "deprecated"):
        _log("rebuild_instance", "error", "image unavailable")
        return _err("VALIDATION_ERROR", "image_id is unavailable.", field="image_id")

    # Lifecycle transition to rebuilding must be legal
    transitions = {
        "provisioning": ["running", "offline", "error"],
        "running": ["rebooting", "shutting_down", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "offline": ["booting", "resizing", "cloning", "rebuilding", "rescuing", "deleting", "error"],
        "booting": ["running", "error"],
        "shutting_down": ["offline", "error"],
        "rebooting": ["running", "error"],
        "resizing": ["running", "offline", "error"],
        "cloning": ["running", "offline", "error"],
        "rebuilding": ["running", "offline", "error"],
        "rescuing": ["running", "offline", "error"],
        "deleting": ["deleted", "error"],
        "error": ["offline", "deleting"],
        "deleted": []
    }
    cur_status = inst.get("status")
    if cur_status not in transitions or "rebuilding" not in transitions[cur_status]:
        _log("rebuild_instance", "error", "invalid transition")
        return _err("INVALID_TRANSITION", f"Cannot rebuild instance from status '{cur_status}'.", from_status=cur_status, to_status="rebuilding")

    # Mutate disks: if preserve_data true, keep non-root disks; otherwise reset all disks to a single root disk
    disks = inst.get("disks") if isinstance(inst.get("disks"), list) else []
    def _is_root_disk(d):
        if not isinstance(d, dict):
            return False
        lab = d.get("label")
        return isinstance(lab, str) and lab.lower() in ("root", "rootfs", "boot")

    if preserve_data:
        # Ensure at least one root disk exists; if not, create one
        root = next((d for d in disks if _is_root_disk(d)), None)
        if not root:
            disks = [{
                "disk_id": "dsk_" + uuid.uuid4().hex,
                "label": "root",
                "filesystem": "ext4",
                "size_mb": 25600,
                "status": "ready",
                "created_at": now,
                "updated_at": now
            }] + [d for d in disks if isinstance(d, dict)]
        else:
            root["updated_at"] = now
    else:
        disks = [{
            "disk_id": "dsk_" + uuid.uuid4().hex,
            "label": "root",
            "filesystem": "ext4",
            "size_mb": max(25600, int(disks[0].get("size_mb")) if disks and isinstance(disks[0], dict) and isinstance(disks[0].get("size_mb"), int) else 25600),
            "status": "ready",
            "created_at": now,
            "updated_at": now
        }]

    # Create operation
    op_id = "op_" + uuid.uuid4().hex
    # store root_pass in request normalized but not plaintext; base64 as "encrypted" stand-in
    enc = base64.b64encode(root_pass.encode("utf-8")).decode("ascii")
    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": instance_id,
        "operation_type": "rebuild",
        "status": "running",
        "request": {
            "instance_id": instance_id,
            "image_id": img.get("id"),
            "root_pass_encrypted": enc,
            "preserve_data": bool(preserve_data) if preserve_data is not None else False
        },
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op)

    # Mutate instance
    inst["status"] = "rebuilding"
    inst["image_id"] = img.get("id")
    inst["disks"] = disks
    inst["last_operation_id"] = op_id
    inst["updated_at"] = now

    _save("operations.json", ops)
    _save("linode_instances.json", instances)

    _log("rebuild_instance", "ok", None)
    return {
        "operation": op,
        "instance": inst
    }

def rescue_instance(instance_id, devices=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
