        try:
            fn = "request_log.json"
            rows = _load(fn)
            rows.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
