    if devices is not None and not isinstance(devices, dict):
        _log("rescue_instance", "error", "invalid devices")
        return _err("VALIDATION_ERROR", "devices must be an object.", field="devices")

    instances = _load("linode_instances.json")
    ops = _load("operations.json")

    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst or inst.get("deleted_at") is not None:
        _log("rescue_instance", "error", "instance not found")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    # Enforce state: rescue allowed only offline/running
    if inst.get("status") not in ("offline", "running"):
        _log("rescue_instance", "error", "invalid transition")
        return _err("INVALID_TRANSITION", "Rescue is only allowed when instance is offline or running.", status=inst.get("status"))

    # Only one running operation per resource
    for o in ops:
        if o.get("resource_collection") == "linode_instances" and o.get("resource_id") == instance_id and o.get("status") == "running":
            _log("rescue_instance", "error", "op conflict")
            return _err("CONFLICT", "Another operation is currently running for this instance.", operation_id=o.get("id"))

    # Validate devices mapping
    rescue_devices = {}
    if devices:
        valid_slots = {f"sd{c}": True for c in "abcdefghijklmnopqrstuvwxyz"}
        disks = inst.get("disks") if isinstance(inst.get("disks"), list) else []
        disk_ids = {d.get("disk_id") for d in disks if isinstance(d, dict) and d.get("disk_id")}
        used = set()
        for slot, ref in devices.items():
            if not isinstance(slot, str) or slot not in valid_slots:
                _log("rescue_instance", "error", "invalid device slot")
                return _err("VALIDATION_ERROR", "Invalid device slot for rescue mode.", field="devices", slot=slot)
            if slot in used:
                _log("rescue_instance", "error", "duplicate slot")
                return _err("VALIDATION_ERROR", "Duplicate device slot.", field="devices", slot=slot)
            used.add(slot)
            # Accept disk references by disk_id only (no separate volume schema available here)
            if not isinstance(ref, str) or ref not in disk_ids:
                _log("rescue_instance", "error", "unknown disk reference")
                return _err("VALIDATION_ERROR", "Device mapping must reference an existing disk_id on the instance.", field="devices", slot=slot)
            rescue_devices[slot] = {"disk_id": ref}

    # Create operation with required rescue spec/kernel in request
    op_id = "op_" + uuid.uuid4().hex
    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": instance_id,
        "operation_type": "rescue",
        "status": "running",
        "request": {
            "instance_id": instance_id,
            "rescue": {
                "kernel": inst.get("kernel_id") or "rescue-default",
                "devices": rescue_devices
            }
        },
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op)

    # Transition instance to rescuing
    inst["status"] = "rescuing"
    inst["last_operation_id"] = op_id
    inst["updated_at"] = now

    _save("operations.json", ops)
    _save("linode_instances.json", instances)

    _log("rescue_instance", "ok", None)
    return {
        "operation": op,
        "instance": inst
    }

def list_instance_configs(instance_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_instance_configs"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(instance_id, str) or not re.match(r"^lin_01H8[0-9A-Z]{15,}$", instance_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")

    if limit is None:
        limit_i = 100
    else:
        if not isinstance(limit, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        if limit < 1 or limit > 500:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit")
        limit_i = limit

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        if not cursor.startswith("cfgcur:"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor format.", field="cursor")
        try:
            start = int(cursor.split(":", 1)[1])
            if start < 0:
                raise ValueError()
        except ValueError:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor value.", field="cursor")

    instances = _load("linode_instances.json")
    inst = next((x for x in instances if x.get("id") == instance_id), None)
    if inst is None or inst.get("deleted_at") is not None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    configs = inst.get("configs") or []
    if not isinstance(configs, list):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Instance configs are malformed.", instance_id=instance_id)

    # Stable order: created_at then config_id
    def _key(c):
        ca = c.get("created_at") or ""
        cid = c.get("config_id") or ""
        return (ca, cid)
    configs_sorted = sorted(configs, key=_key)

    total = len(configs_sorted)
    if start > total:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Cursor out of range.", field="cursor")

    page = configs_sorted[start:start + limit_i]
    next_start = start + len(page)
    has_more = next_start < total
    next_cursor = f"cfgcur:{next_start}" if has_more else None

    _log("ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_i,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

