def create_instance_config(instance_id, label, kernel_id=None, devices=None, helpers=None, comments=None, **_extra):
    import json, os, datetime, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_instance_config"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(instance_id, str) or not instance_id:
        e = _err("VALIDATION_ERROR", "instance_id must be a string", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(label, str) or not label.strip():
        e = _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if kernel_id is not None and not isinstance(kernel_id, str):
        e = _err("VALIDATION_ERROR", "kernel_id must be a string", field="kernel_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if devices is not None and not isinstance(devices, dict):
        e = _err("VALIDATION_ERROR", "devices must be an object", field="devices")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if helpers is not None and not isinstance(helpers, dict):
        e = _err("VALIDATION_ERROR", "helpers must be an object", field="helpers")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if comments is not None and not isinstance(comments, str):
        e = _err("VALIDATION_ERROR", "comments must be a string", field="comments")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id and r.get("deleted_at") is None:
            inst = r
            break
    if not inst:
        e = _err("NOT_FOUND", "Instance not found", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # validate kernel_id if it is a catalog id we can find
    if kernel_id is not None:
        infra = _load("infra_catalog.json")
        infra_rows = infra if isinstance(infra, list) else (infra.get("rows") if isinstance(infra, dict) else [])
        if not isinstance(infra_rows, list):
            infra_rows = []
        krow = None
        for rr in infra_rows:
            if isinstance(rr, dict) and rr.get("id") == kernel_id:
                krow = rr
                break
        if krow is not None:
            if krow.get("catalog_type") != "kernel" or krow.get("status") != "active":
                e = _err("VALIDATION_ERROR", "kernel_id must reference an active kernel catalog item", field="kernel_id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    configs = inst.get("configs")
    if not isinstance(configs, list):
        configs = []
        inst["configs"] = configs

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    cfg_id = _new_id("cfg")
    existing_ids = set()
    for c in configs:
        if isinstance(c, dict) and isinstance(c.get("config_id"), str):
            existing_ids.add(c["config_id"])
    while cfg_id in existing_ids:
        cfg_id = _new_id("cfg")

    new_cfg = {
        "config_id": cfg_id,
        "label": label,
        "kernel_id": kernel_id,
        "devices": devices if devices is not None else {},
        "helpers": helpers if helpers is not None else {},
        "comments": comments if comments is not None else "",
        "root_device": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    configs.append(new_cfg)
    inst["updated_at"] = now

    _save("linode_instances.json", instances)
    _log("ok", resource={"collection": "linode_instances", "id": instance_id})
    return {"config": new_cfg, "instance_id": instance_id}

def update_instance_config(instance_id, config_id, label=None, kernel_id=None, devices=None, helpers=None, comments=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_instance_config"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(instance_id, str) or not re.match(r"^lin_01H8[0-9A-Z]{15,}$", instance_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")
    if not isinstance(config_id, str) or config_id.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed config_id.", field="config_id")

    if label is not None and (not isinstance(label, str) or label.strip() == ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a non-empty string when provided.", field="label")

    if kernel_id is not None and (not isinstance(kernel_id, str) or kernel_id.strip() == ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "kernel_id must be a non-empty string when provided.", field="kernel_id")

    if devices is not None and not isinstance(devices, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "devices must be an object when provided.", field="devices")

    if helpers is not None and not isinstance(helpers, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "helpers must be an object when provided.", field="helpers")

    if comments is not None and not isinstance(comments, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "comments must be a string when provided.", field="comments")

    instances = _load("linode_instances.json")
    inst_i = next((i for i, x in enumerate(instances) if x.get("id") == instance_id), None)
    if inst_i is None or instances[inst_i].get("deleted_at") is not None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    # Validate kernel reference if provided: must be active kernel catalog item
    if kernel_id is not None:
        catalog = _load("infra_catalog.json")
        k = next((c for c in catalog if c.get("id") == kernel_id and c.get("catalog_type") == "kernel"), None)
        if k is None:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Referenced kernel_id not found.", field="kernel_id", kernel_id=kernel_id)
        if k.get("status") != "active":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "kernel_id must reference an active kernel.", field="kernel_id", kernel_id=kernel_id)

    inst = instances[inst_i]
    configs = inst.get("configs") or []
    if not isinstance(configs, list):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Instance configs are malformed.", instance_id=instance_id)

    cfg_i = next((i for i, c in enumerate(configs) if isinstance(c, dict) and c.get("config_id") == config_id), None)
    if cfg_i is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Config not found for this instance.", instance_id=instance_id, config_id=config_id)

    if all(v is None for v in [label, kernel_id, devices, helpers, comments]):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one field must be provided to update.", fields=["label", "kernel_id", "devices", "helpers", "comments"])

    cfg = configs[cfg_i]
    changed = False

    if label is not None:
        cfg["label"] = label.strip()
        changed = True
    if kernel_id is not None:
        cfg["kernel_id"] = kernel_id
        changed = True
    if devices is not None:
        cfg["devices"] = devices
        changed = True
    if helpers is not None:
        cfg["helpers"] = helpers
        changed = True
    if comments is not None:
        cfg["comments"] = comments
        changed = True

    if not changed:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No changes applied.", instance_id=instance_id, config_id=config_id)

    ts = _now()
    cfg["updated_at"] = ts
    configs[cfg_i] = cfg
    inst["configs"] = configs
    inst["updated_at"] = ts
    instances[inst_i] = inst
    _save("linode_instances.json", instances)

    _log("ok")
    return {"data": cfg}

def delete_instance_config(instance_id, config_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- observable dynamics (request log + basic rate limit) ----
    logs_name = "request_log.json"
    logs = _load(logs_name)
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    max_per_window = 120
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs:
        try:
            if r.get("ts") >= cutoff:
                recent += 1
        except Exception:
            pass
    if recent >= max_per_window:
        entry = {"ts": now, "endpoint": "delete_instance_config", "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000), "credential_id": None}
        logs.append(entry)
        _save(logs_name, logs)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    def _log(status):
        entry = {"ts": now, "endpoint": "delete_instance_config", "status": status, "latency_ms": int((time.time() - t0) * 1000), "credential_id": None}
        logs.append(entry)
        _save(logs_name, logs)

    # ---- input validation ----
    if not isinstance(instance_id, str) or not re.match(r"^lin_[0-9A-Z]{18,}$", instance_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")
    if not isinstance(config_id, str) or not config_id:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed config_id.", field="config_id")

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []

    inst = next((x for x in instances if x.get("id") == instance_id and x.get("deleted_at") is None), None)
    if not inst:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    configs = inst.get("configs")
    if not isinstance(configs, list):
        configs = []

    idx = None
    for i, c in enumerate(configs):
        if isinstance(c, dict) and c.get("config_id") == config_id:
            idx = i
            break
    if idx is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Config not found for this instance.", instance_id=instance_id, config_id=config_id)

    # Service rule: refuse deletion when config is required for current/pending boot config.
    # No explicit "current config" field exists; interpret "required" as the only remaining config.
    if len(configs) == 1:
        _log("CONFLICT")
        return _err("CONFLICT", "Cannot delete the only remaining configuration profile for this instance.", instance_id=instance_id, config_id=config_id)

    # ---- mutate ----
    deleted_cfg = configs.pop(idx)
    inst["configs"] = configs
    inst["updated_at"] = now

    # Persist
    for i, x in enumerate(instances):
        if x.get("id") == instance_id:
            instances[i] = inst
            break
    _save("linode_instances.json", instances)

    _log("OK")
    return {
        "result": {
            "instance_id": instance_id,
            "deleted_config_id": config_id,
            "deleted_config": deleted_cfg
        }
    }

