    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request log + basic rate limit ----
    logs_name = "request_log.json"
    logs = _load(logs_name)
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    max_per_window = 240
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs:
        try:
            if r.get("ts") >= cutoff:
                recent += 1
        except Exception:
            pass
    if recent >= max_per_window:
        entry = {"ts": now, "endpoint": "list_instance_disks", "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000), "credential_id": None}
        logs.append(entry)
        _save(logs_name, logs)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    def _log(status):
        entry = {"ts": now, "endpoint": "list_instance_disks", "status": status, "latency_ms": int((time.time() - t0) * 1000), "credential_id": None}
        logs.append(entry)
        _save(logs_name, logs)

    # ---- input validation ----
    if not isinstance(instance_id, str) or not re.match(r"^lin_[0-9A-Z]{18,}$", instance_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 500.", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"=" * (-len(cursor) % 4)).decode("utf-8")
            if not raw.startswith("off:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("bad cursor")
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []

    inst = next((x for x in instances if x.get("id") == instance_id and x.get("deleted_at") is None), None)
    if not inst:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    disks = inst.get("disks")
    if not isinstance(disks, list):
        disks = []

    total = len(disks)
    page = disks[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log("OK")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

