def create_instance_disk(instance_id, label, size_mb, filesystem=None, image_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- request log + basic rate limit ----
    logs_name = "request_log.json"
    logs = _load(logs_name)
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    max_per_window = 120
    cutoff = (now_dt - datetime.timedelta(seconds=window_s)).isoformat() + "Z"
    recent = 0
    for r in logs:
        try:
            if r.get("ts") >= cutoff:
                recent += 1
        except Exception:
            pass
    if recent >= max_per_window:
        entry = {"ts": now, "endpoint": "create_instance_disk", "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000), "credential_id": None}
        logs.append(entry)
        _save(logs_name, logs)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    def _log(status):
        entry = {"ts": now, "endpoint": "create_instance_disk", "status": status, "latency_ms": int((time.time() - t0) * 1000), "credential_id": None}
        logs.append(entry)
        _save(logs_name, logs)

    # ---- input validation ----
    if not isinstance(instance_id, str) or not re.match(r"^lin_[0-9A-Z]{18,}$", instance_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")
    if not isinstance(label, str) or len(label.strip()) < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Label must be a non-empty string.", field="label")
    if not isinstance(size_mb, int) or size_mb < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "size_mb must be an integer >= 1.", field="size_mb")
    if filesystem is not None and not isinstance(filesystem, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filesystem must be a string when provided.", field="filesystem")
    if image_id is not None and not isinstance(image_id, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image_id must be a string when provided.", field="image_id")

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    catalog = _load("infra_catalog.json")
    if not isinstance(catalog, list):
        catalog = []
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []

    inst_idx = None
    inst = None
    for i, x in enumerate(instances):
        if x.get("id") == instance_id and x.get("deleted_at") is None:
            inst_idx = i
            inst = x
            break
    if inst is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    # Instance type must exist; enforce capacity check vs type's disk_mb when available
    type_id = inst.get("type_id")
    type_item = None
    if isinstance(type_id, str):
        for c in catalog:
            if c.get("id") == type_id and c.get("catalog_type") == "linode_type":
                type_item = c
                break
    if not type_item or type_item.get("status") not in ("active", "deprecated", "unavailable"):
        _log("CONFLICT")
        return _err("CONFLICT", "Instance type is missing or invalid in catalog; cannot validate disk capacity.", instance_id=instance_id, type_id=type_id)

    spec = type_item.get("spec") if isinstance(type_item.get("spec"), dict) else {}
    plan_disk_mb = spec.get("disk_mb")
    if not isinstance(plan_disk_mb, int) or plan_disk_mb <= 0:
        _log("CONFLICT")
        return _err("CONFLICT", "Instance type does not specify disk capacity; cannot create disk.", type_id=type_id)

    disks = inst.get("disks")
    if not isinstance(disks, list):
        disks = []

    # Enforce per-instance disk minimum (schema constraint)
    if size_mb < 256:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Disk size must be at least 256 MB.", field="size_mb")

    used_mb = 0
    for d in disks:
        if isinstance(d, dict) and isinstance(d.get("size_mb"), int):
            used_mb += d["size_mb"]
    if used_mb + size_mb > plan_disk_mb:
        _log("CONFLICT")
        return _err("CONFLICT", "Insufficient available disk space on the instance for this disk size.", used_mb=used_mb, requested_mb=size_mb, plan_disk_mb=plan_disk_mb)

    # Validate image_id if provided: must reference an active catalog item (modelled as catalog item)
    if image_id is not None:
        img = next((c for c in catalog if c.get("id") == image_id), None)
        if not img or img.get("status") != "active":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Image not found or not available.", image_id=image_id)

    # Generate unique disk_id within instance
    existing_ids = set()
    for d in disks:
        if isinstance(d, dict) and isinstance(d.get("disk_id"), str):
            existing_ids.add(d["disk_id"])

    def _new_id(prefix):
        import secrets, string
        alphabet = string.ascii_uppercase + string.digits
        for _ in range(50):
            sfx = "".join(secrets.choice(alphabet) for _ in range(20))
            nid = f"{prefix}{sfx}"
            if nid not in existing_ids:
                return nid
        return None

    disk_id = _new_id("dsk_")
    if not disk_id:
        _log("CONFLICT")
        return _err("CONFLICT", "Unable to allocate a unique disk id. Please retry.")

    # Create operation (queued->running->succeeded) and disk
    def _op_id():
        import secrets, string
        alphabet = string.ascii_lowercase + string.digits
        return "op_" + "".join(secrets.choice(alphabet) for _ in range(24))

    # Ensure only one running op per resource: we will not create a running op if one exists
    for o in ops:
        if o.get("resource_collection") == "linode_instances" and o.get("resource_id") == instance_id and o.get("status") == "running":
            _log("CONFLICT")
            return _err("CONFLICT", "Another operation is currently running for this instance.", instance_id=instance_id)

    opid = _op_id()
    op = {
        "id": opid,
        "resource_collection": "linode_instances",
        "resource_id": instance_id,
        "operation_type": "create",
        "status": "queued",
        "request": {
            "tool": "create_instance_disk",
            "instance_id": instance_id,
            "label": label.strip(),
            "size_mb": size_mb,
            "filesystem": filesystem,
            "image_id": image_id
        },
        "result": {"disk_id": disk_id},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None
    }
    ops.append(op)
    _save("operations.json", ops)

    # Transition op to running
    for i, o in enumerate(ops):
        if o.get("id") == opid:
            ops[i]["status"] = "running"
            ops[i]["started_at"] = now
            ops[i]["updated_at"] = now
            break
    _save("operations.json", ops)

    new_disk = {
        "disk_id": disk_id,
        "label": label.strip(),
        "filesystem": filesystem if filesystem is not None else (None if image_id is not None else None),
        "size_mb": size_mb,
        "status": "ready" if image_id is None else "provisioned",
        "created_at": now,
        "updated_at": now
    }

    # Persist disk in instance
    disks.append(new_disk)
    inst["disks"] = disks
    inst["last_operation_id"] = opid
    inst["updated_at"] = now
    instances[inst_idx] = inst
    _save("linode_instances.json", instances)

    # Mark op succeeded
    for i, o in enumerate(ops):
        if o.get("id") == opid:
            ops[i]["status"] = "succeeded"
            ops[i]["finished_at"] = now
            ops[i]["updated_at"] = now
            break
    _save("operations.json", ops)

    _log("OK")
    return {"data": new_disk, "meta": {"operation_id": opid}}

def get_instance_stats(instance_id, period=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "succeeded"
    err_obj = None

    try:
        if not isinstance(instance_id, str) or not re.match(r"^lin_[0-9A-Z]{18,}$", instance_id):
            err_obj = _err("VALIDATION_ERROR", "instance_id is malformed.")
            status = "failed"
            return err_obj
        if period is None:
            period = "hour"
        if not isinstance(period, str) or period not in ("hour", "day", "week", "month"):
            err_obj = _err("VALIDATION_ERROR", "period must be one of: hour, day, week, month.")
            status = "failed"
            return err_obj

        instances = _load("linode_instances.json")
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            err_obj = _err("NOT_FOUND", "Instance not found.")
            status = "failed"
            return err_obj

        # Reads normally exclude deleted, but stats-by-id for audit purposes can still exist;
        # however tool says NOT_FOUND only if instance does not exist. If soft-deleted, treat as conflict.
        if inst.get("deleted_at") is not None or inst.get("status") in ("deleting", "deleted"):
            err_obj = _err("CONFLICT", "Statistics unavailable for deleted/deleting instances.", instance_status=inst.get("status"))
            status = "failed"
            return err_obj

        # If instance is provisioning/error, consider stats unavailable.
        if inst.get("status") in ("provisioning",):
            err_obj = _err("CONFLICT", "Statistics cannot be produced while instance is provisioning.", instance_status=inst.get("status"))
            status = "failed"
            return err_obj

        series = inst.get("stats_timeseries") or []
        # Parse and filter by period window
        now = datetime.datetime.utcnow().replace(microsecond=0)
        if period == "hour":
            delta = datetime.timedelta(hours=1)
        elif period == "day":
            delta = datetime.timedelta(days=1)
        elif period == "week":
            delta = datetime.timedelta(days=7)
        else:
            delta = datetime.timedelta(days=30)
        start = now - delta

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        filtered = []
        for p in series:
            if not isinstance(p, dict):
                continue
            ts = _parse_ts(p.get("ts"))
            if ts is None:
                continue
            if ts >= start and ts <= now:
                filtered.append(p)

        # Sort ascending by ts
        filtered.sort(key=lambda p: p.get("ts") or "")

        # Summaries
        cpu_vals = [p.get("cpu_pct") for p in filtered if isinstance(p.get("cpu_pct"), (int, float))]
        def _avg(vals):
            return (sum(vals) / len(vals)) if vals else None

        stats = {
            "instance_id": instance_id,
            "period": period,
            "start": start.isoformat() + "Z",
            "end": now.isoformat() + "Z",
            "points": filtered,
            "summary": {
                "cpu_avg_pct": _avg(cpu_vals),
                "cpu_max_pct": (max(cpu_vals) if cpu_vals else None),
                "net_in_avg_bps": _avg([p.get("net_in_bps") for p in filtered if isinstance(p.get("net_in_bps"), (int, float))]),
                "net_out_avg_bps": _avg([p.get("net_out_bps") for p in filtered if isinstance(p.get("net_out_bps"), (int, float))]),
                "io_read_avg_bps": _avg([p.get("io_read_bps") for p in filtered if isinstance(p.get("io_read_bps"), (int, float))]),
                "io_write_avg_bps": _avg([p.get("io_write_bps") for p in filtered if isinstance(p.get("io_write_bps"), (int, float))]),
            }
        }
        return {"stats": stats}
    except Exception as e:
        status = "failed"
        err_obj = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        return err_obj
    finally:
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "get_instance_stats",
                "status": status,
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
                "request": {"instance_id": instance_id, "period": period},
                "error": err_obj.get("error") if isinstance(err_obj, dict) and "error" in err_obj else None
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

def get_instance_stats_by_date(instance_id, year, month, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_instance_stats_by_date"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, message=None, extra=None):
        # Best-effort request logging if a log collection exists.
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "ts": _iso_now(),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if message is not None:
                row["message"] = message
            if isinstance(extra, dict):
                row["meta"] = extra
            logs.append(row)
            _save("request_logs.json", logs)

    # Quota/rate limiting based on existing request log if present
    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        # Simple default limits: 120 req/min, 10k req/day
        per_min = 120
        per_day = 10000
        def _parse_ts(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        last_min = 0
        last_day = 0
        for r in logs[-20000:]:
            ts = _parse_ts(r.get("ts"))
            if not ts:
                continue
            dt = now - ts
            if dt.total_seconds() <= 60:
                last_min += 1
            if dt.total_seconds() <= 86400:
                last_day += 1
        if last_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if last_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", message=limit_err["error"]["message"])
        return limit_err

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^lin_[0-9A-HJKMNP-TV-Z]{18,}$", instance_id):
        e = _err("VALIDATION_ERROR", "instance_id is malformed.", field="instance_id")
        _log("error", message=e["error"]["message"])
        return e
    if not isinstance(year, int) or year < 1970 or year > 2100:
        e = _err("VALIDATION_ERROR", "year is out of range.", field="year")
        _log("error", message=e["error"]["message"])
        return e
    if not isinstance(month, int) or month < 1 or month > 12:
        e = _err("VALIDATION_ERROR", "month is out of range.", field="month")
        _log("error", message=e["error"]["message"])
        return e

    instances = _load("linode_instances.json")
    inst = None
    if isinstance(instances, list):
        for r in instances:
            if isinstance(r, dict) and r.get("id") == instance_id:
                inst = r
                break

    if not inst:
        e = _err("NOT_FOUND", "Linode instance not found.")
        _log("error", message=e["error"]["message"])
        return e

    # Exclude soft-deleted instances from normal reads; for stats, if deleted -> unavailable
    if inst.get("deleted_at") is not None or inst.get("status") in ("deleted", "deleting"):
        e = _err("CONFLICT", "Statistics are unavailable for deleted instances.")
        _log("error", message=e["error"]["message"])
        return e

    # Enforce "FORBIDDEN" is mentioned by vendor, but allowed codes list does not include it.
    # Ambient auth: if store has any instance, caller is considered authorized.
    # (No explicit credential parameter to validate.)

    # Metrics availability rule: treat provisioning/rebuilding/resizing/etc as unavailable for historical month stats.
    unavailable_states = set(["provisioning", "cloning", "rebuilding", "rescuing", "resizing", "error"])
    if inst.get("status") in unavailable_states:
        e = _err("CONFLICT", "Statistics for the requested month are unavailable due to instance state.")
        _log("error", message=e["error"]["message"])
        return e

    series = inst.get("stats_timeseries")
    if not isinstance(series, list):
        series = []

    # Filter points by year/month (UTC) based on ts ISO string
    def _parse_ts(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    points = []
    for p in series:
        if not isinstance(p, dict):
            continue
        ts = _parse_ts(p.get("ts"))
        if not ts:
            continue
        if ts.year == year and ts.month == month:
            points.append(p)

    # If no retained points for that month, conflict (unavailable due to retention)
    if len(points) == 0:
        e = _err("CONFLICT", "Statistics for the requested month are unavailable (no retained metrics).")
        _log("error", message=e["error"]["message"])
        return e

    # Sort points by timestamp
    points.sort(key=lambda x: x.get("ts") or "")

    body = {
        "instance_id": instance_id,
        "year": year,
        "month": month,
        "data": points,
        "meta": {
            "count": len(points),
        },
    }
    _log("ok")
    return body

