    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_volumes"
    call_status = "succeeded"
    request_log_name = "request_log.json"

    # Rate limit (if log exists)
    try:
        if os.path.exists(os.path.join(_DB, request_log_name)):
            logs = _load(request_log_name)
            now = datetime.datetime.utcnow()
            window_start = (now - datetime.timedelta(seconds=60)).isoformat() + "Z"
            recent = [r for r in logs if isinstance(r, dict) and r.get("ts") and r["ts"] >= window_start]
            if len(recent) >= 600:
                call_status = "rate_limited"
                return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        call_status = "failed"
        return _err("VALIDATION_ERROR", "Request log is corrupted")

    try:
        if region_id is not None:
            if not isinstance(region_id, str):
                call_status = "failed"
                return _err("VALIDATION_ERROR", "region_id must be a string", field="region_id")
            if not re.match(r"^cat_[0-9A-HJKMNP-TV-Z]{18,}$", region_id):
                call_status = "failed"
                return _err("VALIDATION_ERROR", "region_id is malformed", field="region_id")

        allowed_status = {"provisioning","active","updating","suspending","suspended","resizing","deleting","deleted","error"}
        if status is not None:
            if not isinstance(status, str) or status not in allowed_status:
                call_status = "failed"
                return _err("VALIDATION_ERROR", "Invalid status filter", field="status", allowed=sorted(list(allowed_status)))

        if page is None:
            page = 1
        if page_size is None:
            page_size = 100
        if not isinstance(page, int) or page < 1:
            call_status = "failed"
            return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
        if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
            call_status = "failed"
            return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500", field="page_size")

        allowed_sort_by = {"label","created_at","updated_at","status","region_id"}
        if sort_by is None:
            sort_by = "created_at"
        if sort_order is None:
            sort_order = "asc"
        if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
            call_status = "failed"
            return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by", allowed=sorted(list(allowed_sort_by)))
        if sort_order not in ("asc", "desc"):
            call_status = "failed"
            return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order", allowed=["asc","desc"])

        rows = _load("storage_dns_managed.json")
