def create_volume(label, region_id, spec, tags=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_volume"
    call_status = "succeeded"
    request_log_name = "request_log.json"

    # Rate limit (if log exists)
    try:
        if os.path.exists(os.path.join(_DB, request_log_name)):
            logs = _load(request_log_name)
            now = datetime.datetime.utcnow()
            window_start = (now - datetime.timedelta(seconds=60)).isoformat() + "Z"
            recent = [r for r in logs if isinstance(r, dict) and r.get("ts") and r["ts"] >= window_start]
            if len(recent) >= 300:  # tighter for mutations
                call_status = "rate_limited"
                return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        call_status = "failed"
        return _err("VALIDATION_ERROR", "Request log is corrupted")

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        # base32-ish using vendor alphabet set (no I, L, O, U); use token and map
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = secrets.token_bytes(12)
        n = int.from_bytes(raw, "big")
        out = []
        while n:
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        s = "".join(reversed(out)) or "0"
        if len(s) < 18:
            s = ("0" * (18 - len(s))) + s
        return f"{prefix}_{s}"

    try:
        if not isinstance(label, str) or len(label) < 1:
            call_status = "failed"
            return _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
        if not isinstance(region_id, str) or not re.match(r"^cat_[0-9A-HJKMNP-TV-Z]{18,}$", region_id):
            call_status = "failed"
            return _err("VALIDATION_ERROR", "region_id is malformed", field="region_id")
        if not isinstance(spec, dict):
            call_status = "failed"
            return _err("VALIDATION_ERROR", "spec must be an object", field="spec")
        if tags is None:
            tags = []
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            call_status = "failed"
            return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")

        # Validate region exists and active
        catalog = _load("infra_catalog.json")
        region_row = None
        for c in catalog:
            if isinstance(c, dict) and c.get("id") == region_id and c.get("catalog_type") == "region":
                region_row = c
                break
        if not region_row or region_row.get("status") != "active":
            call_status = "failed"
            return _err("VALIDATION_ERROR", "region_id must reference an active region catalog item", field="region_id")

        # Volume constraints: size between 10 and 10240 if provided
        if "size_gb" in spec:
            sg = spec.get("size_gb")
            if not isinstance(sg, int):
                call_status = "failed"
                return _err("VALIDATION_ERROR", "spec.size_gb must be an integer", field="spec.size_gb")
            if sg < 10 or sg > 10240:
                call_status = "failed"
                return _err("VALIDATION_ERROR", "spec.size_gb out of range (10..10240)", field="spec.size_gb")
        else:
            # Real APIs often default; but schema implies required by tools "size" - keep strict-ish:
            call_status = "failed"
            return _err("VALIDATION_ERROR", "spec.size_gb is required", field="spec.size_gb")

        rows = _load("storage_dns_managed.json")

        # Uniqueness: same label within region where not soft-deleted
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("resource_type") == "volume" and r.get("deleted_at") is None and r.get("region_id") == region_id and r.get("label") == label:
                call_status = "failed"
                return _err("CONFLICT", "A volume with this label already exists in the region", label=label, region_id=region_id)

        # Quota: if quotas.json exists, enforce; else basic fixed account cap
        try:
            quota_name = "quotas.json"
            if os.path.exists(os.path.join(_DB, quota_name)):
                quotas = _load(quota_name)
            else:
                quotas = []
            max_volumes = None
            max_volumes_per_region = None
            for q in quotas:
                if not isinstance(q, dict):
                    continue
                if q.get("resource") == "volume" and q.get("scope") == "account":
                    mv = q.get("limit")
                    if isinstance(mv, int):
                        max_volumes = mv
                if q.get("resource") == "volume" and q.get("scope") == "region" and q.get("region_id") == region_id:
                    mvr = q.get("limit")
                    if isinstance(mvr, int):
                        max_volumes_per_region = mvr

            active_vols = [r for r in rows if isinstance(r, dict) and r.get("resource_type") == "volume" and r.get("deleted_at") is None]
            active_vols_region = [r for r in active_vols if r.get("region_id") == region_id]
            # default caps if no quotas configured
            if max_volumes is None:
                max_volumes = 200
            if max_volumes_per_region is None:
                max_volumes_per_region = 100

            if len(active_vols) >= max_volumes or len(active_vols_region) >= max_volumes_per_region:
                call_status = "failed"
                return _err("QUOTA_EXCEEDED", "Volume quota exceeded", account_limit=max_volumes, region_limit=max_volumes_per_region)
        except Exception:
            call_status = "failed"
            return _err("VALIDATION_ERROR", "Quota data is corrupted")

        # Create operation (queued->running->succeeded) and resource
        ops = _load("operations.json")
        now = _now()
        vol_id = _new_id("vol")
        op_id = _new_id("op")

        # Ensure op id uniqueness
        existing_op_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        while op_id in existing_op_ids:
            op_id = _new_id("op")

        # Ensure volume id uniqueness
        existing_ids = {r.get("id") for r in rows if isinstance(r, dict)}
        while vol_id in existing_ids:
            vol_id = _new_id("vol")

        op = {
            "id": op_id,
            "resource_collection": "storage_dns_managed",
            "resource_id": vol_id,
            "operation_type": "create",
            "status": "succeeded",
            "request": {
                "resource_type": "volume",
                "label": label,
                "region_id": region_id,
                "spec": spec,
                "tags": tags
            },
            "result": {"id": vol_id},
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        }
        ops.append(op)

        vol = {
            "id": vol_id,
            "resource_type": "volume",
            "label": label,
            "region_id": region_id,
            "status": "active",
            "spec": spec,
            "attachments": [],
            "parent_id": None,
            "secrets": None,
            "last_operation_id": op_id,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None
        }

        rows.append(vol)
        _save("operations.json", ops)
        _save("storage_dns_managed.json", rows)

        return {"data": vol, "operation": op}
    finally:
        try:
            if os.path.exists(os.path.join(_DB, request_log_name)):
                logs = _load(request_log_name)
                logs.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "ts": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": call_status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "credential_id": None
                })
                _save(request_log_name, logs)
        except Exception:
            pass

def attach_volume(volume_id, linode_id, **_extra):
    import json, os, datetime, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "attach_volume"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None, operation_id=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(volume_id, str) or not volume_id:
        e = _err("VALIDATION_ERROR", "volume_id must be a string", field="volume_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(linode_id, str) or not linode_id:
        e = _err("VALIDATION_ERROR", "linode_id must be a string", field="linode_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    store = _load("storage_dns_managed.json")
    if not isinstance(store, list):
        store = []
    vol = None
    for r in store:
        if isinstance(r, dict) and r.get("id") == volume_id and r.get("deleted_at") is None:
            vol = r
            break
    if not vol or vol.get("resource_type") != "volume":
        e = _err("NOT_FOUND", "Volume not found", field="volume_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if vol.get("status") not in ("active", "updating", "resizing"):
        e = _err("CONFLICT", "Volume is not in an attachable state")
        _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "storage_dns_managed", "id": volume_id})
        return e

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == linode_id and r.get("deleted_at") is None:
            inst = r
            break
    if not inst:
        e = _err("NOT_FOUND", "Instance not found", field="linode_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    attachments = vol.get("attachments")
    if not isinstance(attachments, list):
        attachments = []
        vol["attachments"] = attachments
    if len(attachments) >= 1:
        e = _err("CONFLICT", "Volume is already attached")
        _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "storage_dns_managed", "id": volume_id})
        return e

    # region compatibility: if both have region_id, must match
    if vol.get("region_id") and inst.get("region_id") and vol.get("region_id") != inst.get("region_id"):
        e = _err("CONFLICT", "Volume and instance must be in the same region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []
    for op in operations:
        if isinstance(op, dict) and op.get("resource_collection") == "storage_dns_managed" and op.get("resource_id") == volume_id and op.get("status") == "running":
            e = _err("CONFLICT", "Another operation is currently running for this volume")
            _log("error", e["error"]["code"], e["error"]["message"], resource={"collection": "storage_dns_managed", "id": volume_id})
            return e

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    op_id = _new_id("op")
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": volume_id,
        "operation_type": "attach",
        "status": "succeeded",
        "request": {"volume_id": volume_id, "linode_id": linode_id},
        "result": {"attached_instance_id": linode_id},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    operations.append(op)

    vol["attachments"] = [{"instance_id": linode_id, "attached_at": now, "device": None}]
    vol["updated_at"] = now
    vol["last_operation_id"] = op_id

    _save("operations.json", operations)
    _save("storage_dns_managed.json", store)

    _log("ok", resource={"collection": "storage_dns_managed", "id": volume_id}, operation_id=op_id)
    return {"volume": vol, "operation": op}

def resize_volume(volume_id, size_gb, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
           		return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(volume_id, str):
        return _err("VALIDATION_ERROR", "volume_id must be a string")
    if not re.match(r"^vol_01H8[0-9A-Z]{15,}$", volume_id):
        return _err("VALIDATION_ERROR", "volume_id does not match required pattern")
    if not isinstance(size_gb, int):
        return _err("VALIDATION_ERROR", "size_gb must be an integer")
    if size_gb < 1:
        return _err("VALIDATION_ERROR", "size_gb must be at least 1")

    ops = _load("operations.json")
    managed = _load("storage_dns_managed.json")

    vol = None
    for r in managed:
        if r.get("id") == volume_id and r.get("resource_type") == "volume":
            vol = r
            break

    if not vol or vol.get("deleted_at") is not None or vol.get("status") == "deleted":
        ops.append({
            "id": f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}",
            "resource_collection": "storage_dns_managed",
            "resource_id": volume_id,
            "operation_type": "resize",
            "status": "failed",
            "request": {"tool": "resize_volume", "volume_id": volume_id, "size_gb": size_gb},
            "result": None,
            "error_message": "Volume not found",
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("operations.json", ops)
        return _err("NOT_FOUND", "Volume not found")

    spec = vol.get("spec") if isinstance(vol.get("spec"), dict) else {}
    cur_size = spec.get("size_gb")

    if not isinstance(cur_size, int):
        # store inconsistency; treat as conflict to avoid corrupting further
        ops.append({
            "id": f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}",
            "resource_collection": "storage_dns_managed",
            "resource_id": volume_id,
            "operation_type": "resize",
            "status": "failed",
            "request": {"tool": "resize_volume", "volume_id": volume_id, "size_gb": size_gb},
            "result": None,
            "error_message": "Volume size is not set correctly",
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("operations.json", ops)
        return _err("CONFLICT", "Volume size is not set correctly")

    if size_gb < cur_size:
        ops.append({
            "id": f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}",
            "resource_collection": "storage_dns_managed",
            "resource_id": volume_id,
            "operation_type": "resize",
            "status": "failed",
            "request": {"tool": "resize_volume", "volume_id": volume_id, "size_gb": size_gb, "current_size_gb": cur_size},
            "result": None,
            "error_message": "Requested size is smaller than current size",
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("operations.json", ops)
        return _err("CONFLICT", "Requested size is smaller than current size")

    if size_gb == cur_size:
        op_id = f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}"
        op_row = {
            "id": op_id,
            "resource_collection": "storage_dns_managed",
            "resource_id": volume_id,
            "operation_type": "resize",
            "status": "succeeded",
            "request": {"tool": "resize_volume", "volume_id": volume_id, "size_gb": size_gb},
            "result": {"no_change": True},
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        }
        ops.append(op_row)
        vol["last_operation_id"] = op_id
        vol["updated_at"] = now
        _save("storage_dns_managed.json", managed)
        _save("operations.json", ops)
        return {"volume": vol, "operation": op_row}

    # Validate volume constraints for volumes: size between 10 and 10240; region_id not null
    if size_gb < 10 or size_gb > 10240:
        return _err("VALIDATION_ERROR", "For volumes, size_gb must be between 10 and 10240")
    if vol.get("region_id") is None:
        return _err("VALIDATION_ERROR", "For volumes, region_id must be set")

    # State: must be able to transition to resizing from active per lifecycle
    if vol.get("status") not in ("active", "error"):
        return _err("CONFLICT", "Volume is not in a state that can be resized")

    # Only one running op per resource
    for op in ops:
        if op.get("resource_collection") == "storage_dns_managed" and op.get("resource_id") == volume_id and op.get("status") == "running":
            return _err("CONFLICT", "Another operation is currently running on this volume")

    op_id = f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}"
    op_row = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": volume_id,
        "operation_type": "resize",
        "status": "running",
        "request": {"tool": "resize_volume", "volume_id": volume_id, "size_gb": size_gb, "previous_size_gb": cur_size},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op_row)

    vol["status"] = "resizing"
    vol["last_operation_id"] = op_id
    vol["updated_at"] = now

    # Complete immediately
    spec["size_gb"] = size_gb
    vol["spec"] = spec
    vol["status"] = "active"
    vol["updated_at"] = now

    op_row["status"] = "succeeded"
    op_row["updated_at"] = now
    op_row["finished_at"] = now
    op_row["result"] = {"size_gb": size_gb}

    _save("storage_dns_managed.json", managed)
    _save("operations.json", ops)
    return {"volume": vol, "operation": op_row}

def get_ip_addresses(region_id=None, instance_id=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # request log + lightweight rate limiting (best-effort; only if collection exists)
    def _log(status_code, message=None, extra=None, latency_ms=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{hashlib.sha256((now + str(time.time())).encode()).hexdigest()[:16]}",
                "tool": "get_ip_addresses",
                "timestamp": now,
                "status": status_code,
                "latency_ms": latency_ms if latency_ms is not None else int((time.time() - start) * 1000),
            }
            if message is not None:
                row["message"] = message
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)

    # basic fixed-window rate limit if request_logs.json present
    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        window_s = 60
        limit_n = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                else:
                    s2 = s
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                return None
        recent = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= limit_n:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=window_s, limit=limit_n)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    # Validate inputs
    if region_id is not None and not isinstance(region_id, str):
        e = _err("VALIDATION_ERROR", "region_id must be a string")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    if instance_id is not None:
        if not isinstance(instance_id, str):
            e = _err("VALIDATION_ERROR", "instance_id must be a string")
            _log("VALIDATION_ERROR", e["error"]["message"])
            return e
        if not re.match(r"^lin_01H8[0-9A-Z]{15,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is malformed")
            _log("VALIDATION_ERROR", e["error"]["message"])
            return e

    allowed_status = {"provisioning", "active", "updating", "deleting", "deleted", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "status is invalid", allowed=list(sorted(allowed_status)))
            _log("VALIDATION_ERROR", e["error"]["message"])
            return e

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    allowed_sort_by = {"created_at", "updated_at", "label", "status"}
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        e = _err("VALIDATION_ERROR", "sort_by is invalid", allowed=list(sorted(allowed_sort_by)))
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    allowed_sort_order = {"asc", "desc"}
    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        e = _err("VALIDATION_ERROR", "sort_order is invalid", allowed=list(sorted(allowed_sort_order)))
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    # Validate cursor (opaque)
    cursor_offset = 0
    cursor_sig = None
    def _cursor_payload(off):
        payload = json.dumps(
            {"o": off, "s": {"region_id": region_id, "instance_id": instance_id, "status": status, "sort_by": sort_by, "sort_order": sort_order}},
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")
        return payload

    if cursor is not None:
        if not isinstance(cursor, str):
            e = _err("VALIDATION_ERROR", "cursor must be a string")
            _log("VALIDATION_ERROR", e["error"]["message"])
            return e
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "o" not in obj or "sig" not in obj or "s" not in obj:
                raise ValueError("bad cursor")
            if not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad offset")
            cursor_offset = obj["o"]
            cursor_sig = obj["sig"]
            # verify signature and that filters match
            expected_sig = hashlib.sha256(_cursor_payload(cursor_offset)).hexdigest()
            if cursor_sig != expected_sig:
                raise ValueError("cursor signature mismatch")
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid")
            _log("VALIDATION_ERROR", e["error"]["message"])
            return e

    # Validate region existence if provided
    if region_id is not None:
        catalog = _load("infra_catalog.json")
        ok_region = False
        for c in catalog:
            if c.get("id") == region_id and c.get("catalog_type") == "region" and c.get("status") == "active":
                ok_region = True
                break
        if not ok_region:
            e = _err("VALIDATION_ERROR", "region_id is not a valid active region")
            _log("VALIDATION_ERROR", e["error"]["message"])
            return e

    # Validate instance existence if provided (must be non-deleted)
    if instance_id is not None:
        insts = _load("linode_instances.json")
        exists = False
        for i in insts:
            if i.get("id") == instance_id and i.get("deleted_at") is None:
                exists = True
                break
        if not exists:
            e = _err("NOT_FOUND", "Instance not found")
            _log("NOT_FOUND", e["error"]["message"])
            return e

    net = _load("network_security.json")
    rows = []
    for r in net:
        if r.get("resource_type") != "ip_address":
            continue
        # exclude soft-deleted
        if r.get("deleted_at") is not None:
            continue
        if region_id is not None and r.get("region_id") != region_id:
            continue
        if instance_id is not None and r.get("instance_id") != instance_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    def _key(v):
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return v
        return str(v)

    reverse = (sort_order == "desc")
    rows.sort(key=lambda x: _key(x.get(sort_by)), reverse=reverse)

    total = len(rows)
    if cursor_offset > total:
        e = _err("VALIDATION_ERROR", "cursor is out of range")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    page = rows[cursor_offset:cursor_offset + limit]
    next_cursor = None
    next_off = cursor_offset + len(page)
    has_more = next_off < total
    if has_more:
        sig = hashlib.sha256(_cursor_payload(next_off)).hexdigest()
        next_cursor = base64.urlsafe_b64encode(json.dumps({"o": next_off, "sig": sig, "s": {"region_id": region_id, "instance_id": instance_id, "status": status, "sort_by": sort_by, "sort_order": sort_order}}, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("OK", latency_ms=int((time.time() - start) * 1000))
    return resp

