def update_ip_address(ip_id, rdns, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_code, message=None, extra=None, latency_ms=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{hashlib.sha256((now + str(time.time())).encode()).hexdigest()[:16]}",
                "tool": "update_ip_address",
                "timestamp": now,
                "status": status_code,
                "latency_ms": latency_ms if latency_ms is not None else int((time.time() - start) * 1000),
            }
            if message is not None:
                row["message"] = message
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)

    # rate limit (only if logs exist)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
            except Exception:
                return None
        recent = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            e = _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=120)
            _log("RATE_LIMIT", e["error"]["message"])
            return e

    if not isinstance(ip_id, str) or not re.match(r"^ip_01H8[0-9A-Z]{15,}$", ip_id):
        e = _err("VALIDATION_ERROR", "ip_id is malformed")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    if not isinstance(rdns, str):
        e = _err("VALIDATION_ERROR", "rdns must be a string")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    rdns = rdns.strip()
    # allow empty string to clear -> stored as None
    def _is_valid_hostname(h):
        if h == "":
            return True
        if len(h) > 253:
            return False
        labels = h.split(".")
        # must contain at least 2 labels for FQDN-like rdns
        if len(labels) < 2:
            return False
        allowed = re.compile(r"^[A-Za-z0-9-]{1,63}$")
        for lab in labels:
            if not allowed.match(lab):
                return False
            if lab.startswith("-") or lab.endswith("-"):
                return False
        return True

    if not _is_valid_hostname(rdns):
        e = _err("VALIDATION_ERROR", "rdns must be a valid hostname or empty string to clear")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    net = _load("network_security.json")
    idx = None
    for i, r in enumerate(net):
        if r.get("id") == ip_id and r.get("resource_type") == "ip_address":
            idx = i
            break

    if idx is None or net[idx].get("deleted_at") is not None:
        e = _err("NOT_FOUND", "IP address not found")
        _log("NOT_FOUND", e["error"]["message"])
        return e

    ip = net[idx]
    # Only allow changing reverse DNS; enforce lifecycle constraints
    if ip.get("status") != "active":
        e = _err("CONFLICT", "IP address is not in an updatable state", status=ip.get("status"))
        _log("CONFLICT", e["error"]["message"])
        return e

    spec = ip.get("spec")
    if not isinstance(spec, dict):
        spec = {}
    spec["rdns"] = None if rdns == "" else rdns
    ip["spec"] = spec
    ip["updated_at"] = now

    # Create operation (update)
    ops = _load("operations.json")
    # enforce only one running per resource
    for o in ops:
        if o.get("resource_collection") == "network_security" and o.get("resource_id") == ip_id and o.get("status") == "running":
            e = _err("CONFLICT", "Another operation is currently running for this resource")
            _log("CONFLICT", e["error"]["message"])
            return e

    op_id = f"op_{hashlib.sha256((ip_id + now + 'update').encode()).hexdigest()[:20]}"
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": ip_id,
        "operation_type": "update",
        "status": "succeeded",
        "request": {"ip_id": ip_id, "patch": {"spec": {"rdns": spec["rdns"]}}},
        "result": {"updated_fields": ["spec.rdns"]},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now
    }
    ops.append(op)
    ip["last_operation_id"] = op_id

    net[idx] = ip
    _save("network_security.json", net)
    _save("operations.json", ops)

    resp = {"data": ip, "operation": op}
    _log("OK", latency_ms=int((time.time() - start) * 1000))
    return resp

def allocate_ip(region_id, ip_version, instance_id=None, **_extra):
