        e = _err("VALIDATION_ERROR", "ip_version must be one of: ipv4, ipv6", field="ip_version")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if instance_id is not None and (not isinstance(instance_id, str) or not instance_id):
        e = _err("VALIDATION_ERROR", "instance_id must be a string when provided", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    # Validate region catalog id
    infra = _load("infra_catalog.json")
    infra_rows = infra if isinstance(infra, list) else (infra.get("rows") if isinstance(infra, dict) else [])
    if not isinstance(infra_rows, list):
        infra_rows = []
    reg = None
