        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = None
    if instance_id is not None:
        for r in instances:
            if isinstance(r, dict) and r.get("id") == instance_id and r.get("deleted_at") is None:
                inst = r
                break
        if not inst:
            e = _err("NOT_FOUND", "Instance not found", field="instance_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if inst.get("region_id") and inst.get("region_id") != region_id:
            e = _err("CONFLICT", "IP region_id must match instance region_id when assigning")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []

    used = set()
    for r in ns:
        if isinstance(r, dict) and r.get("resource_type") == "ip_address" and r.get("deleted_at") is None:
            addr = (r.get("spec") or {}).get("address")
            if isinstance(addr, str):
                used.add(addr)

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    # Generate a deterministic-ish RFC5737 / RFC3849 test-net IP not already used
    address = None
    if ip_version == "ipv4":
        # 203.0.113.0/24
        for _ in range(1024):
            cand = f"203.0.113.{random.randint(1, 254)}"
            if cand not in used:
                address = cand
                break
        if address is None:
            e = _err("CONFLICT", "No available IPv4 addresses in allocation pool")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        version = 4
    else:
        # 2001:db8::/64
        for _ in range(1024):
            hextet = random.randint(1, 65535)
            cand = f"2001:db8::{hextet:x}"
            if cand not in used:
                address = cand
                break
        if address is None:
            e = _err("CONFLICT", "No available IPv6 addresses in allocation pool")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        version = 6

    try:
        ipaddress.ip_address(address)
    except Exception:
        e = _err("CONFLICT", "Internal allocation generated an invalid IP address")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    ip_id = _new_id("ip")
    op_id = _new_id("op")

    ip_row = {
        "id": ip_id,
        "resource_type": "ip_address",
        "region_id": region_id,
        "status": "active",
        "label": None,
        "parent_id": None,
        "instance_id": instance_id,
        "spec": {"address": address, "version": version, "rdns": None},
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": ip_id,
        "operation_type": "assign" if instance_id else "create",
        "status": "succeeded",
        "request": {"region_id": region_id, "ip_version": ip_version, "instance_id": instance_id},
        "result": {"id": ip_id, "address": address},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    operations.append(op)
    ns.append(ip_row)

    _save("operations.json", operations)
    _save("network_security.json", ns)

    _log("ok", resource={"collection": "network_security", "id": ip_id}, operation_id=op_id)
    return {"ip_address": ip_row, "operation": op}

def share_ips(from_instance_id, to_instance_id, ip_address_ids, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # -------- usage log (best-effort, schema may not include) ----------
    def _log(status_code, credential_used=None, extra=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"req_{base64.urlsafe_b64encode(os.urandom(12)).decode('ascii').rstrip('=')}",
                "endpoint": "share_ips",
                "status": status_code,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
                "credential": credential_used,
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        # -------- validate inputs ----------
        if not isinstance(from_instance_id, str) or not re.match(r"^lin_[0-9A-Z]{18,}$", from_instance_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "from_instance_id is malformed")
        if not isinstance(to_instance_id, str) or not re.match(r"^lin_[0-9A-Z]{18,}$", to_instance_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "to_instance_id is malformed")
        if from_instance_id == to_instance_id:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "from_instance_id must not equal to_instance_id")
        if not isinstance(ip_address_ids, list) or len(ip_address_ids) < 1:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "ip_address_ids must be a non-empty array")
        for i, ipid in enumerate(ip_address_ids):
            if not isinstance(ipid, str) or not re.match(r"^ip_[0-9A-Z]{18,}$", ipid):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"ip_address_ids[{i}] is malformed")

        # -------- load data ----------
        instances = _load("linode_instances.json")
        net = _load("network_security.json")
        ops = _load("operations.json")

        if not isinstance(instances, list) or not isinstance(net, list) or not isinstance(ops, list):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Datastore is not in expected format")

        inst_by_id = {r.get("id"): r for r in instances if isinstance(r, dict)}
        from_inst = inst_by_id.get(from_instance_id)
        to_inst = inst_by_id.get(to_instance_id)

        # Existence checks (NOT_FOUND if missing)
        if not from_inst or from_inst.get("deleted_at") is not None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Source Linode instance not found")
        if not to_inst or to_inst.get("deleted_at") is not None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Destination Linode instance not found")

        # Fetch and validate IP resources
        ip_rows = []
        for ipid in ip_address_ids:
            row = next((r for r in net if isinstance(r, dict) and r.get("id") == ipid), None)
            if not row or row.get("deleted_at") is not None or row.get("resource_type") != "ip_address":
                _log("NOT_FOUND")
                return _err("NOT_FOUND", f"IP address not found: {ipid}")
            ip_rows.append(row)

        # Conflict: must all be active and currently attached to source
        for row in ip_rows:
            if row.get("status") != "active":
                _log("CONFLICT")
                return _err("CONFLICT", f"IP is not active: {row.get('id')}")
            if row.get("instance_id") != from_instance_id:
                _log("CONFLICT")
                return _err("CONFLICT", f"IP is not currently attached to source instance: {row.get('id')}")

        # Create operation (async)
        def _gen_id(prefix):
            return prefix + base64.urlsafe_b64encode(os.urandom(14)).decode("ascii").rstrip("=")

        op_id = _gen_id("op_")
        op = {
            "id": op_id,
            "resource_collection": "linode_instances",
            "resource_id": from_instance_id,
            "operation_type": "share_ips",
            "status": "queued",
            "request": {
                "from_instance_id": from_instance_id,
                "to_instance_id": to_instance_id,
                "ip_address_ids": list(ip_address_ids),
            },
            "result": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": None,
            "finished_at": None,
        }

        # Apply immediate model changes to represent "shared": attach IP rows to destination as well via spec.shared_with
        # (schema doesn't model multi-attach on IP; implement "share" as keeping instance_id but noting share target)
        for row in ip_rows:
            spec = row.get("spec")
            if not isinstance(spec, dict):
                spec = {}
            shared = spec.get("shared_with")
            if not isinstance(shared, list):
                shared = []
            if to_instance_id not in shared:
                shared.append(to_instance_id)
            spec["shared_with"] = shared
            row["spec"] = spec
            row["last_operation_id"] = op_id
            row["updated_at"] = now

        # Persist
        ops.append(op)
        _save("operations.json", ops)
        _save("network_security.json", net)

        _log("200", extra={"operation_id": op_id})
        return {"operation": op}
    except Exception as e:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

