        # requests per minute
        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            cutoff = (now - datetime.timedelta(seconds=60)).replace(tzinfo=None)
            cnt = 0
            for r in logs[::-1]:
                ts = r.get("ts")
                if not isinstance(ts, str):
                    continue
                try:
                    t = datetime.datetime.fromisoformat(ts.replace("Z", ""))
                except Exception:
                    continue
                if t < cutoff:
                    break
                cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        # daily quota
        qd = limits.get("requests_per_day")
        if isinstance(qd, int) and qd > 0:
            cutoff = (now - datetime.timedelta(days=1)).replace(tzinfo=None)
            cnt = 0
            for r in logs[::-1]:
                ts = r.get("ts")
                if not isinstance(ts, str):
                    continue
                try:
                    t = datetime.datetime.fromisoformat(ts.replace("Z", ""))
                except Exception:
                    continue
                if t < cutoff:
                    break
                cnt += 1
            if cnt >= qd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    limerr = _enforce_limits()
    if limerr:
        _log(429, error_code=limerr["error"]["code"])
        return limerr

    # Validate inputs
    if region_id is not None and not isinstance(region_id, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region_id must be a string")
    if status is not None:
        if not isinstance(status, str):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string")
        allowed = ["provisioning", "active", "updating", "deleting", "deleted", "error"]
        if status not in allowed:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported status filter", allowed=allowed)
    if label is not None and not isinstance(label, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a string")
    if limit is not None:
        if not isinstance(limit, int):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 500:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit out of range", minimum=1, maximum=500)
    if cursor is not None and not isinstance(cursor, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is not None:
        if not isinstance(sort, str):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort must be a string")
        if sort not in ["created_at", "updated_at", "label", "status"]:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported sort field", allowed=["created_at", "updated_at", "label", "status"])
    if order is not None:
        if not isinstance(order, str):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order must be a string")
        if order not in ["asc", "desc"]:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported order", allowed=["asc", "desc"])

    # Ambient auth: if there is no data in store that can satisfy, treat as unauthorized
    ns = _load("network_security.json")
    if not isinstance(ns, list):
        _log(403, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to list firewalls")

    # Filter to firewalls and exclude soft-deleted
    rows = []
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "firewall":
            continue
        if r.get("deleted_at") is not None:
            continue
        if region_id is not None and r.get("region_id") != region_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if label is not None and r.get("label") != label:
            continue
        rows.append(r)

    # Sort
    sfield = sort or "created_at"
    direction = order or "asc"
    def _key(x):
        v = x.get(sfield)
        if v is None:
            return ""
        return v
    rows.sort(key=_key, reverse=(direction == "desc"))

    # Cursor pagination (opaque base64 JSON: {"o": <offset>, "s": <sort>, "d": <order>})
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if isinstance(payload, dict) and isinstance(payload.get("o"), int):
                # ensure cursor compatible with current sort/order
                if payload.get("s") == sfield and payload.get("d") == direction and payload["o"] >= 0:
                    offset = payload["o"]
                else:
                    _log(400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "cursor is invalid for the requested sort/order")
            else:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is malformed")
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed")

    page_size = limit or 100
    total = len(rows)
    page = rows[offset:offset + page_size]
    next_cursor = None
    has_more = offset + page_size < total
    if has_more:
        payload = {"o": offset + page_size, "s": sfield, "d": direction}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": page_size,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sfield,
            "order": direction
        }
    }

