def create_firewall(label, region_id, spec, **_extra):
    import json, os, datetime, secrets, time, ipaddress, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_firewall"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None, operation_id=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(label, str) or not label.strip():
        e = _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(region_id, str) or not region_id:
        e = _err("VALIDATION_ERROR", "region_id must be a string", field="region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(spec, dict):
        e = _err("VALIDATION_ERROR", "spec must be an object", field="spec")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    # validate region
    infra = _load("infra_catalog.json")
    infra_rows = infra if isinstance(infra, list) else (infra.get("rows") if isinstance(infra, dict) else [])
    if not isinstance(infra_rows, list):
        infra_rows = []
    reg = None
    for r in infra_rows:
        if isinstance(r, dict) and r.get("id") == region_id:
            reg = r
            break
    if not reg or reg.get("catalog_type") != "region" or reg.get("status") != "active":
        e = _err("VALIDATION_ERROR", "region_id must reference an active region catalog item", field="region_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []

    # unique firewall label per region
    for r in ns:
        if isinstance(r, dict) and r.get("resource_type") == "firewall" and r.get("deleted_at") is None:
            if r.get("region_id") == region_id and r.get("label") == label:
                e = _err("CONFLICT", "A firewall with this label already exists in the specified region_id", field="label")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    # validate rules (atomic replacement elsewhere; here just validate structure)
    rules = (spec.get("rules") if isinstance(spec.get("rules"), dict) else {})
    inbound = rules.get("inbound", [])
    outbound = rules.get("outbound", [])
    if inbound is None:
        inbound = []
    if outbound is None:
        outbound = []
    if not isinstance(inbound, list) or not isinstance(outbound, list):
        e = _err("VALIDATION_ERROR", "spec.rules.inbound and spec.rules.outbound must be arrays")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if len(inbound) > 256:
        e = _err("VALIDATION_ERROR", "spec.rules.inbound exceeds maximum of 256 rules")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if len(outbound) > 256:
        e = _err("VALIDATION_ERROR", "spec.rules.outbound exceeds maximum of 256 rules")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    def _valid_cidr(x):
        try:
            ipaddress.ip_network(x, strict=False)
            return True
        except Exception:
            return False

    def _valid_ports(p):
        if p is None:
            return True
        if isinstance(p, int):
            return 0 <= p <= 65535
        if isinstance(p, str):
            if p.isdigit():
                v = int(p)
                return 0 <= v <= 65535
            if "-" in p:
                a, b = p.split("-", 1)
                if a.isdigit() and b.isdigit():
                    a, b = int(a), int(b)
                    return 0 <= a <= b <= 65535
        if isinstance(p, list):
            return all(_valid_ports(x) for x in p)
        return False

    def _valid_rule(rule, path):
        if not isinstance(rule, dict):
            return _err("VALIDATION_ERROR", f"{path} must be an object")
        proto = rule.get("protocol")
        if proto not in (None, "TCP", "UDP", "ICMP", "tcp", "udp", "icmp"):
            return _err("VALIDATION_ERROR", f"{path}.protocol is invalid")
        ports = rule.get("ports")
        if not _valid_ports(ports):
            return _err("VALIDATION_ERROR", f"{path}.ports contains invalid port", field=f"{path}.ports")
        for cidr_field in ("addresses", "sources", "destination"):
            v = rule.get(cidr_field)
            if v is None:
                continue
            # accept either string or array of strings
            if isinstance(v, str):
                if not _valid_cidr(v):
                    return _err("VALIDATION_ERROR", f"{path}.{cidr_field} must be a valid CIDR", field=f"{path}.{cidr_field}")
            elif isinstance(v, list):
                for i, s in enumerate(v):
                    if not isinstance(s, str) or not _valid_cidr(s):
                        return _err("VALIDATION_ERROR", f"{path}.{cidr_field}[{i}] must be a valid CIDR", field=f"{path}.{cidr_field}")
            else:
                return _err("VALIDATION_ERROR", f"{path}.{cidr_field} must be a CIDR string or array of CIDR strings", field=f"{path}.{cidr_field}")
        action = rule.get("action")
        if action not in (None, "ACCEPT", "DROP", "accept", "drop"):
            return _err("VALIDATION_ERROR", f"{path}.action is invalid")
        return None

    for i, r in enumerate(inbound):
        er = _valid_rule(r, f"inbound[{i}]")
        if er:
            _log("error", er["error"]["code"], er["error"]["message"])
            return er
    for i, r in enumerate(outbound):
        er = _valid_rule(r, f"outbound[{i}]")
        if er:
            _log("error", er["error"]["code"], er["error"]["message"])
            return er

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    fw_id = _new_id("fw")
    op_id = _new_id("op")

    fw = {
        "id": fw_id,
        "resource_type": "firewall",
        "region_id": region_id,
        "status": "active",
        "label": label,
        "parent_id": None,
        "instance_id": None,
        "spec": spec,
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": fw_id,
        "operation_type": "create",
        "status": "succeeded",
        "request": {"label": label, "region_id": region_id, "spec": spec},
        "result": {"id": fw_id},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    operations.append(op)
    ns.append(fw)
    _save("operations.json", operations)
    _save("network_security.json", ns)

    _log("ok", resource={"collection": "network_security", "id": fw_id}, operation_id=op_id)
    return {"firewall": fw, "operation": op}

