        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Firewall not found", firewall_id=firewall_id)

    if fw.get("status") in ("deleting", "deleted") or fw.get("deleted_at") is not None:
        _log(409, error_code="CONFLICT")
        return _err("CONFLICT", "Firewall is deleting or deleted and cannot be updated", status=fw.get("status"))

    # Validate rules if provided
    def _valid_cidr(c):
        if not isinstance(c, str):
            return False
        if c.lower() == "any":
            return True
        m = re.match(r"^(\d{1,3}\.){3}\d{1,3}\/\d{1,2}$", c)
        if not m:
            if "/" in c and ":" in c:
                pref = c.split("/")[-1]
                try:
                    p = int(pref)
                    return 0 <= p <= 128
                except Exception:
                    return False
            return False
        ip, pref = c.split("/")
        try:
            pref = int(pref)
        except Exception:
            return False
        if pref < 0 or pref > 32:
            return False
        parts = ip.split(".")
        for p in parts:
            try:
                n = int(p)
            except Exception:
                return False
            if n < 0 or n > 255:
                return False
        return True

    def _valid_port(port):
        if port is None:
            return True
        if isinstance(port, int):
            return 1 <= port <= 65535
        if isinstance(port, str):
            if port.isdigit():
                v = int(port)
                return 1 <= v <= 65535
            if "-" in port:
                a, b = port.split("-", 1)
                if a.isdigit() and b.isdigit():
                    a, b = int(a), int(b)
                    return 1 <= a <= b <= 65535
        return False

    def _validate_ruleset(rules):
        if not isinstance(rules, dict):
            return "spec.rules must be an object"
        inbound = rules.get("inbound", [])
        outbound = rules.get("outbound", [])
        if not isinstance(inbound, list) or not isinstance(outbound, list):
            return "spec.rules.inbound and spec.rules.outbound must be arrays"
        if len(inbound) > 256 or len(outbound) > 256:
            return "Maximum of 256 inbound and 256 outbound rules allowed"
        allowed_top = {"label", "action", "protocol", "ports", "addresses", "description"}
        allowed_action = {"ACCEPT", "DROP"}
        allowed_proto = {"TCP", "UDP", "ICMP", "IPENCAP", "AH", "ESP", "GRE", "ALL"}
        def _validate_rule(rule):
            if not isinstance(rule, dict):
                return "Each rule must be an object"
            unknown = set(rule.keys()) - allowed_top
            if unknown:
                return f"Unsupported rule fields: {sorted(list(unknown))}"
            act = rule.get("action")
            if act not in allowed_action:
                return "rule.action must be ACCEPT or DROP"
            proto = rule.get("protocol")
            if proto not in allowed_proto:
                return "rule.protocol is unsupported"
            ports = rule.get("ports")
            if proto in {"TCP", "UDP"}:
                if ports is None:
                    pass
                elif isinstance(ports, list):
                    if not ports:
                        return "rule.ports must not be empty when provided"
                    for p in ports:
                        if not _valid_port(p):
                            return "rule.ports contains an invalid port or range"
                else:
                    if not _valid_port(ports):
                        return "rule.ports must be a port, range, or array of those"
            else:
                if ports is not None:
                    return "rule.ports may only be set for TCP/UDP"
            addrs = rule.get("addresses")
            if addrs is not None:
                if not isinstance(addrs, dict):
                    return "rule.addresses must be an object"
                for k in ["ipv4", "ipv6"]:
                    if k in addrs:
                        if not isinstance(addrs[k], list):
                            return f"rule.addresses.{k} must be an array"
                        for cidr in addrs[k]:
                            if not _valid_cidr(cidr):
                                return f"rule.addresses.{k} contains an invalid CIDR"
            return None
        for r in inbound:
            e = _validate_rule(r)
            if e: return f"inbound rule invalid: {e}"
        for r in outbound:
            e = _validate_rule(r)
            if e: return f"outbound rule invalid: {e}"
        return None

    if spec is not None and "rules" in spec:
        msg = _validate_ruleset(spec.get("rules"))
        if msg:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", msg)

    # Determine changes
    changes = {}
    if label is not None and label != fw.get("label"):
        # uniqueness per region
        region_id = fw.get("region_id")
        for r in ns:
            if not isinstance(r, dict):
                continue
            if r.get("resource_type") == "firewall" and r.get("deleted_at") is None and r.get("id") != firewall_id and r.get("region_id") == region_id and r.get("label") == label:
                _log(409, error_code="CONFLICT")
                return _err("CONFLICT", "A firewall with the same label already exists in this region", label=label, region_id=region_id)
        changes["label"] = label
    if spec is not None and spec != fw.get("spec"):
        changes["spec"] = spec

    if not changes:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No changes provided")

    # Create operation + apply update (async-ish)
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []
    op_existing = {o.get("id") for o in ops if isinstance(o, dict)}
    def _new_op_id():
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        while True:
            s = "".join(secrets.choice(alphabet) for _ in range(20))
            i = f"op_{s}"
            if i not in op_existing:
                return i

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_id = _new_op_id()
    operation = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": firewall_id,
        "operation_type": "update",
        "status": "running",
        "request": {"firewall_id": firewall_id, **changes},
        "result": {"changed_fields": sorted(list(changes.keys()))},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(operation)

    # Apply
    for k, v in changes.items():
        fw[k] = v
    fw["status"] = "updating" if fw.get("status") == "active" else fw.get("status")
    fw["last_operation_id"] = op_id
    fw["updated_at"] = now
    _save("network_security.json", ns)
    _save("operations.json", ops)

    # Complete immediately for offline realism: updating -> active
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op_id:
            o["status"] = "succeeded"
            o["updated_at"] = finished
            o["finished_at"] = finished
            break
    fw["status"] = "active"
    fw["updated_at"] = finished
    _save("operations.json", ops)
    _save("network_security.json", ns)

    _log(200)
    return {"data": fw, "operation": operation}

def delete_firewall(firewall_id, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validation
    if not isinstance(firewall_id, str) or not re.match(r"^fw_01H8[0-9A-Z]{15,}$", firewall_id):
        return _err("VALIDATION_ERROR", "firewall_id is malformed.", field="firewall_id")

    # ---- Load
    net = _load("network_security.json")
    ops = _load("operations.json")

    # ---- Find firewall (exclude soft-deleted for normal ops)
    fw = None
    for r in net:
        if r.get("id") == firewall_id and r.get("resource_type") == "firewall" and r.get("deleted_at") is None:
            fw = r
            break
    if fw is None:
        return _err("NOT_FOUND", "Firewall not found.", firewall_id=firewall_id)

    # ---- Lifecycle / conflict checks
    status = fw.get("status")
    if status in ("deleting", "deleted") or fw.get("deleted_at") is not None:
        return _err("CONFLICT", "Firewall is already deleting or deleted.", status=status)

    allowed = {"provisioning": ["active", "error"], "active": ["updating", "deleting", "error"], "updating": ["active", "error"], "deleting": ["deleted", "error"], "error": ["updating", "deleting"], "deleted": []}
    if "deleting" not in allowed.get(status, []):
        return _err("CONFLICT", "Firewall cannot be deleted from its current state.", status=status)

    # ---- Operations constraint: only one running per resource
    for op in ops:
        if op.get("resource_collection") == "network_security" and op.get("resource_id") == firewall_id and op.get("status") == "running":
            return _err("CONFLICT", "Another operation is currently running for this firewall.", operation_id=op.get("id"))

    # ---- Create operation + transition deleting -> deleted (async modeled as immediate with op trail)
    def _new_op_id():
        return "op_01H8" + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(18))

    op_id = _new_op_id()
    op_row = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": firewall_id,
        "operation_type": "delete",
        "status": "running",
        "request": {"firewall_id": firewall_id},
        "result": None,
        "error_message": None,
        "created_at": ts,
        "updated_at": ts,
        "started_at": ts,
        "finished_at": None
    }
    ops.append(op_row)

    # Update firewall to deleting
    fw["status"] = "deleting"
    fw["last_operation_id"] = op_id
    fw["updated_at"] = ts

    # Also soft-delete firewall_devices under this firewall? (No declared cascade rule for firewall)
    # We keep firewall_device rows intact but they will be effectively orphaned; real APIs often remove devices automatically,
    # but business rules only specify nodebalancer cascade. We'll leave them.

    # Finish operation and mark deleted (soft delete)
    ts2 = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    fw["status"] = "deleted"
    fw["deleted_at"] = ts2
    fw["updated_at"] = ts2

    op_row["status"] = "succeeded"
    op_row["result"] = {"deleted_firewall_id": firewall_id}
    op_row["updated_at"] = ts2
    op_row["finished_at"] = ts2

    _save("network_security.json", net)
    _save("operations.json", ops)

    return {
        "operation": op_row,
        "firewall": fw,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_firewall_rules(firewall_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
