    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # --- Rate limit / audit logging helpers ---
    def _log(status, credential_id=None, message=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "get_firewall_rules",
            "credential_id": credential_id,
            "request": {"firewall_id": firewall_id},
            "status": status,
            "message": message,
            "latency_ms": latency_ms,
            "created_at": ts
        })
        _save("request_log.json", logs)

    def _rate_limit_check():
        # Default: 60 requests/min across all calls if no explicit quota collection exists.
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit = 60
        now = datetime.datetime.now(datetime.timezone.utc)
        c = 0
        for r in reversed(logs[-2000:]):
            try:
                t = datetime.datetime.fromisoformat(r.get("created_at"))
                if t.tzinfo is None:
                    t = t.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if (now - t).total_seconds() <= window_s:
                c += 1
            else:
                break
        if c >= limit:
            return _err("RATE_LIMIT", f"Rate limit exceeded: {limit} requests per {window_s} seconds.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("rate_limited", None, rl["error"]["message"])
        return rl

    # --- Validate inputs ---
    if not isinstance(firewall_id, str):
        _log("validation_error", None, "firewall_id must be a string")
        return _err("VALIDATION_ERROR", "firewall_id must be a string.")
    if not re.match(r"^fw_01H8[0-9A-Z]{15,}$", firewall_id):
        _log("validation_error", None, "firewall_id malformed")
        return _err("VALIDATION_ERROR", "firewall_id is malformed.", field="firewall_id", pattern="^fw_01H8[0-9A-Z]{15,}$")

    # --- Ambient auth resolution ---
    # No credential parameter in this tool; per contract, a well-formed request should not be refused.
    # We only return UNAUTHORIZED if the datastore contains no viable context at all.
    # For this offline datastore, treat presence of any catalog as service availability.
    catalog = _load("infra_catalog.json")
    if not isinstance(catalog, list) or len(catalog) == 0:
        _log("unauthorized", None, "No ambient auth context available in datastore")
        return _err("UNAUTHORIZED", "Not authorized.")

    # --- Fetch firewall and rules ---
    net = _load("network_security.json")
    if not isinstance(net, list):
        net = []

    fw = None
    for r in net:
        if isinstance(r, dict) and r.get("id") == firewall_id:
            fw = r
            break

    if fw is None:
        _log("not_found", None, "Firewall not found")
        return _err("NOT_FOUND", "Firewall not found.", firewall_id=firewall_id)

    # Exclude soft-deleted resources from normal reads.
    if fw.get("deleted_at") is not None or fw.get("status") == "deleted":
        _log("not_found", None, "Firewall is deleted")
        return _err("NOT_FOUND", "Firewall not found.", firewall_id=firewall_id)

    if fw.get("resource_type") != "firewall":
        _log("not_found", None, "ID exists but is not a firewall resource")
        return _err("NOT_FOUND", "Firewall not found.", firewall_id=firewall_id)

    spec = fw.get("spec") if isinstance(fw.get("spec"), dict) else {}
    rules = spec.get("rules")
    if not isinstance(rules, dict):
        # Realistic default if absent
        rules = {"inbound": [], "outbound": []}

    inbound = rules.get("inbound") if isinstance(rules.get("inbound"), list) else []
    outbound = rules.get("outbound") if isinstance(rules.get("outbound"), list) else []

    # Enforce declared max rules as a sanity check; datastore should already comply.
    if len(inbound) > 256 or len(outbound) > 256:
        _log("conflict", None, "Firewall ruleset exceeds maximum rule count")
        return _err("CONFLICT", "Firewall ruleset is invalid (exceeds maximum rule count).", max_inbound=256, max_outbound=256)

    body = {
        "firewall_id": firewall_id,
        "rules": {
            "inbound": inbound,
            "outbound": outbound
        },
        "updated_at": fw.get("updated_at")
    }

    _log("ok", None, None)
    return body

def update_firewall_rules(firewall_id, rules, **_extra):
    import json, os, datetime, re, time, ipaddress, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validation
    if not isinstance(firewall_id, str) or not re.match(r"^fw_01H8[0-9A-Z]{15,}$", firewall_id):
        return _err("VALIDATION_ERROR", "firewall_id is malformed.", field="firewall_id")
    if not isinstance(rules, dict):
        return _err("VALIDATION_ERROR", "rules must be an object.", field="rules")

    inbound = rules.get("inbound")
    outbound = rules.get("outbound")
    if inbound is None or outbound is None or not isinstance(inbound, list) or not isinstance(outbound, list):
        return _err("VALIDATION_ERROR", "rules must include inbound and outbound arrays.", field="rules")
    if len(inbound) > 256 or len(outbound) > 256:
        return _err("VALIDATION_ERROR", "Too many rules (max 256 inbound and 256 outbound).")

    def _valid_protocol(p):
        return p in ("TCP", "UDP", "ICMP", "IPENCAP", "GRE", "ALL") or isinstance(p, str) and p.lower() in ("tcp", "udp", "icmp", "all")

    def _parse_ports(v):
        # Accept int, "80", "80-90", "80,443", ["80","443"], etc.
        if v is None:
            return True
        if isinstance(v, int):
            return 1 <= v <= 65535
        if isinstance(v, str):
            parts = [x.strip() for x in v.split(",") if x.strip()]
            for part in parts:
                if "-" in part:
                    a, b = part.split("-", 1)
                    if not (a.isdigit() and b.isdigit()):
                        return False
                    ai, bi = int(a), int(b)
                    if not (1 <= ai <= 65535 and 1 <= bi <= 65535 and ai <= bi):
                        return False
                else:
                    if not part.isdigit():
                        return False
                    pi = int(part)
                    if not (1 <= pi <= 65535):
                        return False
            return True
        if isinstance(v, list):
            for it in v:
                if not _parse_ports(it):
                    return False
            return True
        return False

    def _parse_cidrs(v):
        # Accept string or list. "0.0.0.0/0" etc.
        if v is None:
            return True
        if isinstance(v, str):
            vals = [x.strip() for x in v.split(",") if x.strip()]
            for c in vals:
                try:
                    ipaddress.ip_network(c, strict=False)
                except Exception:
                    return False
            return True
        if isinstance(v, list):
            for c in v:
                if not isinstance(c, str):
                    return False
                try:
                    ipaddress.ip_network(c, strict=False)
                except Exception:
                    return False
            return True
        return False

    def _validate_rule(rule, direction, idx):
        if not isinstance(rule, dict):
            return _err("VALIDATION_ERROR", f"{direction}[{idx}] must be an object.")
        proto = rule.get("protocol")
        if proto is None or not isinstance(proto, str) or not _valid_protocol(proto):
            return _err("VALIDATION_ERROR", f"{direction}[{idx}].protocol is invalid.")
        # Ports commonly used for TCP/UDP; optional otherwise.
        ports = rule.get("ports")
        if ports is not None and not _parse_ports(ports):
            return _err("VALIDATION_ERROR", f"{direction}[{idx}].ports is invalid.")
        # CIDRs (often "addresses" or "ipv4"/"ipv6" in vendor APIs; here accept 'cidr'/'cidrs'/'addresses')
        cidr_val = rule.get("cidr")
        if cidr_val is None and "cidrs" in rule:
            cidr_val = rule.get("cidrs")
        if cidr_val is None and "addresses" in rule:
            cidr_val = rule.get("addresses")
        if cidr_val is not None and not _parse_cidrs(cidr_val):
            return _err("VALIDATION_ERROR", f"{direction}[{idx}] has invalid CIDR(s).")
        return None

    for i, r in enumerate(inbound):
        e = _validate_rule(r, "inbound", i)
        if e:
            return e
    for i, r in enumerate(outbound):
        e = _validate_rule(r, "outbound", i)
        if e:
            return e

    # ---- Load and locate firewall
    net = _load("network_security.json")
    ops = _load("operations.json")

    fw = None
    for r in net:
        if r.get("id") == firewall_id and r.get("resource_type") == "firewall" and r.get("deleted_at") is None:
            fw = r
            break
    if fw is None:
        return _err("NOT_FOUND", "Firewall not found.", firewall_id=firewall_id)

    # ---- Must be updatable: only 'active' -> 'updating' -> 'active' supported
    status = fw.get("status")
    allowed = {"provisioning": ["active", "error"], "active": ["updating", "deleting", "error"], "updating": ["active", "error"], "deleting": ["deleted", "error"], "error": ["updating", "deleting"], "deleted": []}
    if "updating" not in allowed.get(status, []):
        return _err("CONFLICT", "Firewall is in a non-updatable lifecycle state.", status=status)

    # Only one running op per resource
    for op in ops:
        if op.get("resource_collection") == "network_security" and op.get("resource_id") == firewall_id and op.get("status") == "running":
            return _err("CONFLICT", "Another operation is currently running for this firewall.", operation_id=op.get("id"))

    def _new_op_id():
        return "op_01H8" + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(18))

    op_id = _new_op_id()
    op_row = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": firewall_id,
        "operation_type": "update",
        "status": "running",
        "request": {"firewall_id": firewall_id, "rules": {"inbound": inbound, "outbound": outbound}},
        "result": None,
        "error_message": None,
        "created_at": ts,
        "updated_at": ts,
        "started_at": ts,
        "finished_at": None
    }
    ops.append(op_row)

    # Apply update atomically by replacing spec.rules
    fw["status"] = "updating"
    fw["last_operation_id"] = op_id
    fw["updated_at"] = ts

    if fw.get("spec") is None or not isinstance(fw.get("spec"), dict):
        fw["spec"] = {}
    fw["spec"]["rules"] = {"inbound": inbound, "outbound": outbound}

    # Finish
    ts2 = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    fw["status"] = "active"
    fw["updated_at"] = ts2

    op_row["status"] = "succeeded"
    op_row["result"] = {"updated_fields": ["spec.rules"]}
    op_row["updated_at"] = ts2
    op_row["finished_at"] = ts2

    _save("network_security.json", net)
    _save("operations.json", ops)

    return {
        "firewall": fw,
        "operation": op_row,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

