def create_firewall_device(firewall_id, instance_id, **_extra):
    import json, os, datetime, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_firewall_device"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(firewall_id, str) or not firewall_id:
        e = _err("VALIDATION_ERROR", "firewall_id must be a string", field="firewall_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(instance_id, str) or not instance_id:
        e = _err("VALIDATION_ERROR", "instance_id must be a string", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []
    fw = None
    for r in ns:
        if isinstance(r, dict) and r.get("id") == firewall_id and r.get("deleted_at") is None:
            fw = r
            break
    if not fw or fw.get("resource_type") != "firewall":
        e = _err("NOT_FOUND", "Firewall not found", field="firewall_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id and r.get("deleted_at") is None:
            inst = r
            break
    if not inst:
        e = _err("NOT_FOUND", "Instance not found", field="instance_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # prevent duplicates: existing firewall_device with same parent_id+instance_id
    for r in ns:
        if isinstance(r, dict) and r.get("resource_type") == "firewall_device" and r.get("deleted_at") is None:
            if r.get("parent_id") == firewall_id and r.get("instance_id") == instance_id:
                e = _err("CONFLICT", "Instance is already attached to this firewall")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    dev_id = _new_id("fwd")
    dev = {
        "id": dev_id,
        "resource_type": "firewall_device",
        "region_id": fw.get("region_id"),
        "status": "active",
        "label": None,
        "parent_id": firewall_id,
        "instance_id": instance_id,
        "spec": {"firewall_id": firewall_id, "instance_id": instance_id},
        "last_operation_id": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    ns.append(dev)
    _save("network_security.json", ns)

    _log("ok", resource={"collection": "network_security", "id": dev_id})
    return {"firewall_device": dev}

def delete_firewall_device(firewall_id, device_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    usage_file = "usage_audit.json"
    usage = _load(usage_file)
    def _log(status, code=None, message=None, credential_id=None):
        dt_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{uuid.uuid4().hex}",
            "ts": now,
            "endpoint": "delete_firewall_device",
            "status": status,
            "latency_ms": dt_ms,
            "credential_id": credential_id,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        usage.append(row)
        _save(usage_file, usage)

    if not isinstance(firewall_id, str) or not re.match(r"^fw_01H8[0-9A-Z]{15,}$", firewall_id):
        _log("error", "VALIDATION_ERROR", "firewall_id is malformed")
        return _err("VALIDATION_ERROR", "firewall_id is malformed")
    if not isinstance(device_id, str) or not re.match(r"^(fwdev_01H8[0-9A-Z]{15,}|[a-zA-Z0-9_-]+)$", device_id):
        _log("error", "VALIDATION_ERROR", "device_id is malformed")
        return _err("VALIDATION_ERROR", "device_id is malformed")

    net = _load("network_security.json")
    ops = _load("operations.json")

    fw = next((r for r in net if r.get("id") == firewall_id and r.get("resource_type") == "firewall" and r.get("deleted_at") is None), None)
    if not fw:
        _log("error", "NOT_FOUND", "Firewall not found")
        return _err("NOT_FOUND", "Firewall not found")

    # firewall must be deletable-ish (cannot detach when deleting/deleted)
    if fw.get("status") in ("deleting", "deleted"):
        _log("error", "CONFLICT", "Firewall is not in a detachable state")
        return _err("CONFLICT", "Firewall is not in a detachable state")

    dev = next(
        (r for r in net
         if r.get("id") == device_id
         and r.get("resource_type") == "firewall_device"
         and r.get("parent_id") == firewall_id
         and r.get("deleted_at") is None),
        None
    )
    if not dev:
        _log("error", "NOT_FOUND", "Firewall device attachment not found")
        return _err("NOT_FOUND", "Firewall device attachment not found")

    # operation (detach)
    op_id = f"op_01H8{uuid.uuid4().hex.upper()[:18]}"
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": firewall_id,
        "operation_type": "detach",
        "status": "succeeded",
        "request": {"firewall_id": firewall_id, "device_id": device_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    ops.append(op)

    # soft-delete attachment row via status transitions
    dev["status"] = "deleting"
    dev["updated_at"] = now
    dev["last_operation_id"] = op_id
    dev["deleted_at"] = now
    dev["status"] = "deleted"

    fw["updated_at"] = now
    fw["last_operation_id"] = op_id

    _save("operations.json", ops)
    _save("network_security.json", net)

    _log("success")
    return {"data": {"id": device_id, "deleted": True}}

