def list_nodebalancers(region_id=None, status=None, label=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_nodebalancers"

    # --- helpers ---
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        # Choose an existing file if present; otherwise create service-local request log.
        candidates = ["request_log.json", "requests.json", "audit_log.json", "usage.json", "linode_request_log.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "linode_request_log.json"

    def _log(status_code, error_code=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        logs.append(row)
        _save(fn, logs)

    def _is_str(x):
        return isinstance(x, str)

    # --- validate inputs ---
    if region_id is not None and not _is_str(region_id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region_id must be a string")
    if label is not None and not _is_str(label):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a string")
    allowed_status = {"provisioning", "active", "updating", "deleting", "deleted", "error"}
    if status is not None:
        if not _is_str(status) or status not in allowed_status:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid", allowed=list(sorted(allowed_status)))
    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not _is_str(cursor):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    allowed_sort_by = {"created_at", "updated_at", "label", "status"}
    if sort_by is None:
        sort_by = "created_at"
    if not _is_str(sort_by) or sort_by not in allowed_sort_by:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by is invalid", allowed=list(sorted(allowed_sort_by)))
    allowed_sort_order = {"asc", "desc"}
    if sort_order is None:
        sort_order = "asc"
    if not _is_str(sort_order) or sort_order not in allowed_sort_order:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order is invalid", allowed=list(sorted(allowed_sort_order)))

    # --- load data ---
    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []
    catalog = _load("infra_catalog.json")
    if not isinstance(catalog, list):
        catalog = []

    # Validate region_id reference if provided (must refer to catalog_type=region; allow deprecated/unavailable for filtering)
    if region_id is not None:
        ok_region = any(isinstance(r, dict) and r.get("id") == region_id and r.get("catalog_type") == "region" for r in catalog)
        if not ok_region:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "region_id does not refer to a known region", region_id=region_id)

    # --- filter (exclude soft-deleted by default) ---
    rows = []
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "nodebalancer":
            continue
        if r.get("deleted_at") is not None:
            continue
        if region_id is not None and r.get("region_id") != region_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if label is not None and r.get("label") != label:
            continue
        rows.append(r)

    total = len(rows)

    # --- sort ---
    reverse = (sort_order == "desc")

    def _sort_key(x):
        v = x.get(sort_by)
        if v is None:
            # ensure Nones are stable at end
            return (1, "")
        return (0, v)

    rows.sort(key=_sort_key, reverse=reverse)

    # --- cursor pagination: cursor is an offset encoded as "offset:<int>" ---
    offset = 0
    if cursor:
        m = re.fullmatch(r"offset:(\d+)", cursor)
        if not m:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        offset = int(m.group(1))
        if offset < 0 or offset > total:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor out of range")

    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = f"offset:{next_off}" if has_more else None

    _log(200, None)
    return {
        "data": page,
        "meta": {
            "total": total,
