def create_nodebalancer(label, region_id, tags=None, spec=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "create_nodebalancer"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        candidates = ["request_log.json", "requests.json", "audit_log.json", "usage.json", "linode_request_log.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "linode_request_log.json"

    def _log(status_code, error_code=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        logs.append(row)
        _save(fn, logs)

    def _gen_id(existing_ids):
        # Match required pattern ^nb_01H8[0-9A-Z]{15,}$
        # Generate suffix from time+counter.
        base = datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f")
        raw = hashlib.sha1(base.encode("utf-8")).hexdigest().upper()
        # Convert hex to base36-ish uppercase [0-9A-Z] by mapping nibbles
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        num = int(raw[:20], 16)
        chars = []
        while num > 0 and len(chars) < 20:
            num, rem = divmod(num, 36)
            chars.append(alphabet[rem])
        suffix = "".join(chars).rjust(16, "0")
        nid = "nb_01H8" + suffix
        i = 0
        while nid in existing_ids:
            i += 1
            # perturb
            num2 = (int(suffix, 36) + i) % (36 ** 16)
            s2 = ""
            n = num2
            for _ in range(16):
                n, rem = divmod(n, 36)
                s2 = alphabet[rem] + s2
            nid = "nb_01H8" + s2
        return nid

    # --- validations ---
    if not isinstance(label, str) or not label.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string")
    if len(label) > 128:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label is too long (max 128)")
    if not isinstance(region_id, str) or not region_id.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region_id is required and must be a non-empty string")

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of strings")
    else:
        tags = []

    if spec is not None and not isinstance(spec, dict):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spec must be an object")

    if spec is None:
        spec = {}

    # --- resolve region: must exist and be active at create time (per catalog rule) ---
    catalog = _load("infra_catalog.json")
    if not isinstance(catalog, list):
        catalog = []
    region_row = None
    for r in catalog:
        if isinstance(r, dict) and r.get("id") == region_id and r.get("catalog_type") == "region":
            region_row = r
            break
    if region_row is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "region_id not found", region_id=region_id)
    if region_row.get("status") != "active":
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region_id is not active", region_id=region_id, status=region_row.get("status"))

    # --- quota: enforce a simple account quota using existing rows (service-local; no explicit schema) ---
    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []
    existing_nodebalancers = [
        r for r in ns
        if isinstance(r, dict)
        and r.get("resource_type") == "nodebalancer"
        and r.get("deleted_at") is None
        and r.get("status") != "deleted"
    ]
    # Default quota (reasonable): 25 active/non-deleted nodebalancers
    quota_limit = 25
    if len(existing_nodebalancers) >= quota_limit:
        _log(429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "NodeBalancer quota exceeded", quota=quota_limit, current=len(existing_nodebalancers))

    # --- create operation + resource ---
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []

    existing_ids = {r.get("id") for r in ns if isinstance(r, dict)}
    new_id = _gen_id(existing_ids)

    op_id = "op_" + hashlib.sha256(f"create|nodebalancer|{new_id}|{_now()}".encode("utf-8")).hexdigest()[:24]
    ts = _now()

    # operation: queued -> running -> succeeded (synchronously)
    op_row = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": new_id,
        "operation_type": "create",
        "status": "running",
        "request": {
            "label": label,
            "region_id": region_id,
            "tags": tags,
            "spec": spec,
        },
        "result": None,
        "error_message": None,
        "created_at": ts,
        "updated_at": ts,
        "started_at": ts,
        "finished_at": None,
    }

    # new resource
    nb_row = {
        "id": new_id,
        "resource_type": "nodebalancer",
        "region_id": region_id,
        "status": "provisioning",
        "label": label,
        "parent_id": None,
        "instance_id": None,
        "spec": {"tags": tags, **spec},
        "last_operation_id": op_id,
        "created_at": ts,
        "updated_at": ts,
        "deleted_at": None,
    }

    # persist provisioning + running op
    ns.append(nb_row)
    ops.append(op_row)
    _save("network_security.json", ns)
    _save("operations.json", ops)

    # finalize: provisioning -> active, op running -> succeeded
    nb_row["status"] = "active"
    nb_row["updated_at"] = _now()

    op_row["status"] = "succeeded"
    op_row["updated_at"] = nb_row["updated_at"]
    op_row["finished_at"] = nb_row["updated_at"]
    op_row["result"] = {"id": new_id, "status": nb_row["status"]}

    _save("network_security.json", ns)
    _save("operations.json", ops)

    _log(201, None)
    return {"data": nb_row}

def delete_nodebalancer(nodebalancer_id, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "delete_nodebalancer"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        candidates = ["request_log.json", "requests.json", "audit_log.json", "usage.json", "linode_request_log.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "linode_request_log.json"

    def _log(status_code, error_code=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        logs.append(row)
        _save(fn, logs)

    # validate id
    if not isinstance(nodebalancer_id, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nodebalancer_id must be a string")
    if not re.fullmatch(r"^nb_01H8[0-9A-Z]{15,}$", nodebalancer_id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nodebalancer_id is malformed")

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []

    # find nodebalancer
    nb = None
    for r in ns:
        if isinstance(r, dict) and r.get("id") == nodebalancer_id and r.get("resource_type") == "nodebalancer":
            nb = r
            break
    if nb is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer not found", nodebalancer_id=nodebalancer_id)

    # conflict if already deleting/deleted or soft-deleted
    if nb.get("status") in ("deleting", "deleted") or nb.get("deleted_at") is not None:
        _log(409, "CONFLICT")
        return _err("CONFLICT", "NodeBalancer is already deleting/deleted", status=nb.get("status"))

    # lifecycle transition enforcement for network_security: active/updating/error -> deleting allowed
    allowed_from = {"active", "updating", "error", "provisioning"}  # provisioning can go to deleting via active? but allow delete anyway
    if nb.get("status") not in allowed_from:
        _log(409, "CONFLICT")
        return _err("CONFLICT", "NodeBalancer is not in a deletable state", status=nb.get("status"))

    # ensure no other running op on this resource (business constraint)
    for op in ops:
        if (
            isinstance(op, dict)
            and op.get("resource_collection") == "network_security"
            and op.get("resource_id") == nodebalancer_id
            and op.get("status") == "running"
        ):
            _log(409, "CONFLICT")
            return _err("CONFLICT", "Another operation is currently running on this NodeBalancer", operation_id=op.get("id"))

    # cascade soft-delete to configs and nodes (hierarchy integrity rule) using same operation id
    ts = _now()
    op_id = "op_" + hashlib.sha256(f"delete|nodebalancer|{nodebalancer_id}|{ts}".encode("utf-8")).hexdigest()[:24]
    op_row = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": nodebalancer_id,
        "operation_type": "delete",
        "status": "running",
        "request": {"nodebalancer_id": nodebalancer_id, "cascade": True},
        "result": None,
        "error_message": None,
        "created_at": ts,
        "updated_at": ts,
        "started_at": ts,
        "finished_at": None,
    }
    ops.append(op_row)

    # stage: set deleting status for nb + children
    affected_children = {"configs": 0, "nodes": 0}
    nb["status"] = "deleting"
    nb["last_operation_id"] = op_id
    nb["updated_at"] = ts

    # children: nodebalancer_config parent_id == nb id, nodebalancer_node parent_id == config id
    config_ids = []
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("deleted_at") is not None:
            continue
        if r.get("resource_type") == "nodebalancer_config" and r.get("parent_id") == nodebalancer_id:
            r["status"] = "deleting"
            r["last_operation_id"] = op_id
            r["updated_at"] = ts
            config_ids.append(r.get("id"))
            affected_children["configs"] += 1
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("deleted_at") is not None:
            continue
        if r.get("resource_type") == "nodebalancer_node" and r.get("parent_id") in config_ids:
            r["status"] = "deleting"
            r["last_operation_id"] = op_id
            r["updated_at"] = ts
            affected_children["nodes"] += 1

    _save("operations.json", ops)
    _save("network_security.json", ns)

    # finalize: set deleted + deleted_at for nb + children (soft delete)
    ts2 = _now()
    nb["status"] = "deleted"
    nb["deleted_at"] = ts2
    nb["updated_at"] = ts2

    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("last_operation_id") != op_id:
            continue
        if r.get("resource_type") in ("nodebalancer_config", "nodebalancer_node"):
            r["status"] = "deleted"
            r["deleted_at"] = ts2
            r["updated_at"] = ts2

    op_row["status"] = "succeeded"
    op_row["updated_at"] = ts2
    op_row["finished_at"] = ts2
    op_row["result"] = {"id": nodebalancer_id, "deleted": True, "cascaded": affected_children}

    _save("operations.json", ops)
    _save("network_security.json", ns)

    _log(200, None)
    return {
        "data": {
            "id": nodebalancer_id,
            "status": "deleted",
            "deleted_at": nb.get("deleted_at"),
            "operation_id": op_id,
            "cascaded": affected_children,
        }
    }

def list_nodebalancer_configs(nodebalancer_id, status=None, label=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_nodebalancer_configs"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _record(status_code, credential_id=None, extra=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{hashlib.sha256((endpoint+_now()+str(time.time())).encode('utf-8')).hexdigest()[:20]}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_log.json", logs)

    def _check_rl_quota():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit", {"requests_per_minute": 600})
        quota = cfg.get("quota", {"requests_per_day": 20000})

        rpm = rl.get("requests_per_minute", 600)
        rpd = quota.get("requests_per_day", 20000)

        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        n_min = 0
        n_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                n_min += 1
            if ts >= day_ago:
                n_day += 1

        if isinstance(rpm, int) and rpm > 0 and n_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(rpd, int) and rpd > 0 and n_day >= rpd:
            return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    rlerr = _check_rl_quota()
    if rlerr:
        _record(rlerr["error"]["code"])
        return rlerr

    # Validate inputs
    if not isinstance(nodebalancer_id, str) or not re.match(r"^nb_01H8[0-9A-Z]{15,}$", nodebalancer_id):
        e = _err("VALIDATION_ERROR", "nodebalancer_id is missing or invalid.", field="nodebalancer_id")
        _record(e["error"]["code"])
        return e

    allowed_status = {"provisioning", "active", "updating", "deleting", "deleted", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
            _record(e["error"]["code"])
            return e

    if label is not None and (not isinstance(label, str) or label == ""):
        e = _err("VALIDATION_ERROR", "label must be a non-empty string when provided.", field="label")
        _record(e["error"]["code"])
        return e

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit out of range (1-200).", field="limit")
        _record(e["error"]["code"])
        return e

    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.", field="cursor")
        _record(e["error"]["code"])
        return e

    allowed_sort_by = {"created_at", "updated_at", "label", "status"}
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        e = _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
        _record(e["error"]["code"])
        return e

    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in {"asc", "desc"}:
        e = _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")
        _record(e["error"]["code"])
        return e

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []

    # Find parent nodebalancer (must exist, not soft-deleted)
    parent = None
    for r in ns:
        if r.get("id") == nodebalancer_id and r.get("resource_type") == "nodebalancer" and r.get("deleted_at") is None:
            parent = r
            break
    if not parent:
        e = _err("NOT_FOUND", "NodeBalancer not found.", nodebalancer_id=nodebalancer_id)
        _record(e["error"]["code"])
        return e

    # Filter configs
    rows = []
    for r in ns:
        if r.get("resource_type") != "nodebalancer_config":
            continue
        if r.get("deleted_at") is not None:
            continue
        if r.get("parent_id") != nodebalancer_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if label is not None and r.get("label") != label:
            continue
        rows.append(r)

    # Sort
    reverse = (sort_order == "desc")
    def _sort_key(x):
        v = x.get(sort_by)
        return (v is None, v)
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination (opaque)
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if obj.get("v") != 1 or obj.get("nodebalancer_id") != nodebalancer_id:
                raise ValueError("bad cursor scope")
            start = int(obj.get("offset", 0))
            if start < 0:
                start = 0
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _record(e["error"]["code"])
            return e

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        payload = {"v": 1, "nodebalancer_id": nodebalancer_id, "offset": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
