    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_nodebalancer_config"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _record(status_code, credential_id=None, extra=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{hashlib.sha256((endpoint+_now()+str(time.time())).encode('utf-8')).hexdigest()[:20]}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_log.json", logs)

    def _check_rl_quota():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit", {"requests_per_minute": 600})
        quota = cfg.get("quota", {"requests_per_day": 20000})

        rpm = rl.get("requests_per_minute", 600)
        rpd = quota.get("requests_per_day", 20000)

        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        n_min = 0
        n_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                n_min += 1
            if ts >= day_ago:
                n_day += 1

        if isinstance(rpm, int) and rpm > 0 and n_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(rpd, int) and rpd > 0 and n_day >= rpd:
            return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    rlerr = _check_rl_quota()
    if rlerr:
        _record(rlerr["error"]["code"])
        return rlerr

    # Validate inputs
    if not isinstance(nodebalancer_id, str) or not re.match(r"^nb_01H8[0-9A-Z]{15,}$", nodebalancer_id):
        e = _err("VALIDATION_ERROR", "nodebalancer_id is missing or invalid.", field="nodebalancer_id")
        _record(e["error"]["code"])
        return e
    if not isinstance(config_id, str) or not re.match(r"^nb_01H8[0-9A-Z]{15,}$", config_id):
        e = _err("VALIDATION_ERROR", "config_id is missing or invalid.", field="config_id")
        _record(e["error"]["code"])
        return e

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []

    # Parent nodebalancer must exist and not deleted
    parent = None
    for r in ns:
        if r.get("id") == nodebalancer_id and r.get("resource_type") == "nodebalancer" and r.get("deleted_at") is None:
            parent = r
            break
    if not parent:
        e = _err("NOT_FOUND", "NodeBalancer not found.", nodebalancer_id=nodebalancer_id)
        _record(e["error"]["code"])
        return e

    # Find config and validate ownership
    cfg_idx = None
    cfg_row = None
    for i, r in enumerate(ns):
        if r.get("id") == config_id and r.get("resource_type") == "nodebalancer_config":
            cfg_idx = i
            cfg_row = r
            break
    if not cfg_row or cfg_row.get("deleted_at") is not None or cfg_row.get("parent_id") != nodebalancer_id:
        e = _err("NOT_FOUND", "NodeBalancer config not found for this NodeBalancer.", nodebalancer_id=nodebalancer_id, config_id=config_id)
        _record(e["error"]["code"])
        return e

    # Must be deletable
    if cfg_row.get("status") in {"deleting", "deleted"}:
        e = _err("CONFLICT", "Config is not in a deletable state.", status=cfg_row.get("status"))
        _record(e["error"]["code"])
        return e

    # Also enforce hierarchy: nodes exist under config; deleting config is allowed but should soft-delete nodes too (integrity)
    # (Business rule explicitly mentions cascading when deleting nodebalancer; we also cascade here to avoid orphan nodes.)
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []

    # Enforce only one running op per resource
    for op in ops:
        if op.get("resource_collection") == "network_security" and op.get("resource_id") == config_id and op.get("status") == "running":
            e = _err("CONFLICT", "Another operation is currently running for this config.")
            _record(e["error"]["code"])
            return e

    now = _now()
    op_id = "op_01H8" + secrets.token_hex(10).upper()
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": config_id,
        "operation_type": "delete",
        "status": "running",
        "request": {"tool": endpoint, "nodebalancer_id": nodebalancer_id, "config_id": config_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }

    # Transition to deleting
    cfg_row["last_operation_id"] = op_id
    cfg_row["status"] = "deleting"
    cfg_row["updated_at"] = now

    # Cascade nodes under this config: mark deleting too
    affected_nodes = []
    for r in ns:
        if r.get("resource_type") == "nodebalancer_node" and r.get("deleted_at") is None and r.get("parent_id") == config_id:
            if r.get("status") not in {"deleting", "deleted"}:
                r["last_operation_id"] = op_id
                r["status"] = "deleting"
                r["updated_at"] = now
            affected_nodes.append(r.get("id"))

    # Complete delete quickly: set deleted_at and status deleted on config and child nodes
    done = _now()
    cfg_row["status"] = "deleted"
    cfg_row["deleted_at"] = done
    cfg_row["updated_at"] = done

    for r in ns:
        if r.get("resource_type") == "nodebalancer_node" and r.get("parent_id") == config_id and r.get("deleted_at") is None:
            r["status"] = "deleted"
            r["deleted_at"] = done
            r["updated_at"] = done

    op["status"] = "succeeded"
    op["updated_at"] = done
    op["finished_at"] = done
    op["result"] = {"deleted_config_id": config_id, "deleted_node_ids": affected_nodes}
    ops.append(op)

    _save("network_security.json", ns)
    _save("operations.json", ops)

    resp = {"data": {"id": config_id, "deleted": True, "operation_id": op_id}}
    _record("OK", extra={"operation_id": op_id, "cascaded_nodes": len(affected_nodes)})
    return resp

