def create_nodebalancer_node(nodebalancer_id, config_id, address, label=None, weight=None, mode=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / rate limit (best-effort if collection exists) ----
    logs_name = None
    for cand in ("request_logs.json", "usage.json", "audit_log.json", "audit_logs.json", "requests.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            logs_name = cand
            break
    def _log(status, credential_id=None, error_code=None):
        if not logs_name:
            return
        logs = _load(logs_name)
        row = {
            "id": "req_" + hashlib.sha256((now + str(time.time())).encode("utf-8")).hexdigest()[:20],
            "endpoint": "create_nodebalancer_node",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(logs_name, logs)

    # ---- validation ----
    pat = re.compile(r"^nb_01H8[0-9A-Z]{15,}$")
    if not isinstance(nodebalancer_id, str) or not pat.match(nodebalancer_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nodebalancer_id is missing or invalid.")
    if not isinstance(config_id, str) or not pat.match(config_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "config_id is missing or invalid.")
    if not isinstance(address, str) or not address.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "address is required.")
    if label is not None and not isinstance(label, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a string.")
    if weight is not None:
        if not isinstance(weight, int) or weight < 1 or weight > 255:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "weight must be an integer between 1 and 255.")
    if mode is not None:
        if not isinstance(mode, str) or mode not in ("accept", "reject", "drain", "backup"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "mode must be one of: accept, reject, drain, backup.")

    # ---- load resources ----
    ns = _load("network_security.json")
    ops = _load("operations.json")

    nb = None
    cfg = None
    for r in ns:
        if r.get("deleted_at") is None and r.get("resource_type") == "nodebalancer" and r.get("id") == nodebalancer_id:
            nb = r
            break
    if not nb:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer not found.")

    for r in ns:
        if r.get("deleted_at") is None and r.get("resource_type") == "nodebalancer_config" and r.get("id") == config_id:
            cfg = r
            break
    if not cfg:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer config not found.")
    if cfg.get("parent_id") != nodebalancer_id:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer config does not belong to the specified NodeBalancer.")

    # ---- ensure parent hierarchy integrity (config must have a nodebalancer parent already checked) ----
    if cfg.get("status") in ("deleting", "deleted") or nb.get("status") in ("deleting", "deleted"):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Cannot create a node under a deleting/deleted NodeBalancer or config.")

    # ---- enforce "only one running operation per resource" for config ----
    for o in ops:
        if o.get("resource_collection") == "network_security" and o.get("resource_id") == config_id and o.get("status") == "running":
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Another operation is currently running for this NodeBalancer config.")

    # ---- create operation ----
    def _new_id(prefix):
        raw = (prefix + now + str(time.time())).encode("utf-8")
        tok = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        return "nb_01H8" + tok[:20]

    op_id = "op_" + hashlib.sha256((now + "create_nodebalancer_node" + config_id).encode("utf-8")).hexdigest()[:24]
    # Make op_id unique
    existing_op_ids = {o.get("id") for o in ops if isinstance(o, dict)}
    if op_id in existing_op_ids:
        op_id = "op_" + hashlib.sha256((now + "create_nodebalancer_node" + config_id + str(time.time())).encode("utf-8")).hexdigest()[:24]

    node_id = _new_id("node")

    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": node_id,  # node id as target
        "operation_type": "create",
        "status": "running",
        "request": {
            "nodebalancer_id": nodebalancer_id,
            "config_id": config_id,
            "label": label,
            "address": address,
            "weight": weight if weight is not None else 100,
            "mode": mode if mode is not None else "accept",
        },
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }

    # ---- create node row ----
    node = {
        "id": node_id,
        "resource_type": "nodebalancer_node",
        "region_id": nb.get("region_id"),
        "status": "provisioning",
        "label": label,
        "parent_id": config_id,
        "instance_id": None,
        "spec": {
            "address": address,
            "weight": weight if weight is not None else 100,
            "mode": mode if mode is not None else "accept",
        },
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    # ---- persist, then complete operation ----
    ns.append(node)
    ops.append(op)
    _save("network_security.json", ns)
    _save("operations.json", ops)

    # Transition: provisioning -> active
    # Find node and op to update in persisted structures
    ns2 = _load("network_security.json")
    ops2 = _load("operations.json")
    for r in ns2:
        if r.get("id") == node_id and r.get("resource_type") == "nodebalancer_node":
            r["status"] = "active"
            r["updated_at"] = now
            r["last_operation_id"] = op_id
            break
    for o in ops2:
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["updated_at"] = now
            o["finished_at"] = now
            o["result"] = {"id": node_id}
            break
    _save("network_security.json", ns2)
    _save("operations.json", ops2)

    # Return created node (non-deleted)
    created = None
    for r in ns2:
        if r.get("id") == node_id and r.get("deleted_at") is None:
            created = r
            break

    if not created:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Created node could not be retrieved.")

    _log("ok")
    return {"data": created}

def delete_nodebalancer_node(nodebalancer_id, config_id, node_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs_name = None
    for cand in ("request_logs.json", "usage.json", "audit_log.json", "audit_logs.json", "requests.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            logs_name = cand
            break
    def _log(status, credential_id=None, error_code=None):
        if not logs_name:
            return
        logs = _load(logs_name)
        row = {
            "id": "req_" + hashlib.sha256((now + str(time.time())).encode("utf-8")).hexdigest()[:20],
            "endpoint": "delete_nodebalancer_node",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(logs_name, logs)

    pat = re.compile(r"^nb_01H8[0-9A-Z]{15,}$")
    if not isinstance(nodebalancer_id, str) or not pat.match(nodebalancer_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nodebalancer_id is missing or invalid.")
    if not isinstance(config_id, str) or not pat.match(config_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "config_id is missing or invalid.")
    if not isinstance(node_id, str) or not pat.match(node_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "node_id is missing or invalid.")

    ns = _load("network_security.json")
    ops = _load("operations.json")

    nb = None
    cfg = None
    node = None

    for r in ns:
        if r.get("deleted_at") is None and r.get("resource_type") == "nodebalancer" and r.get("id") == nodebalancer_id:
            nb = r
            break
    if not nb:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer not found.")

    for r in ns:
        if r.get("deleted_at") is None and r.get("resource_type") == "nodebalancer_config" and r.get("id") == config_id:
            cfg = r
            break
    if not cfg:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer config not found.")
    if cfg.get("parent_id") != nodebalancer_id:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer config does not belong to the specified NodeBalancer.")

    for r in ns:
        if r.get("resource_type") == "nodebalancer_node" and r.get("id") == node_id:
            node = r
            break
    if not node or node.get("deleted_at") is not None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer node not found.")
    if node.get("parent_id") != config_id:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "NodeBalancer node does not belong to the specified config.")

    if node.get("status") in ("deleting", "deleted"):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Node is not in a deletable state.")

    # only one running op per node
    for o in ops:
        if o.get("resource_collection") == "network_security" and o.get("resource_id") == node_id and o.get("status") == "running":
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Another operation is currently running for this node.")

    # Create delete operation and soft delete
    op_id = "op_" + hashlib.sha256((now + "delete_nodebalancer_node" + node_id).encode("utf-8")).hexdigest()[:24]
    existing_op_ids = {o.get("id") for o in ops if isinstance(o, dict)}
    if op_id in existing_op_ids:
        op_id = "op_" + hashlib.sha256((now + "delete_nodebalancer_node" + node_id + str(time.time())).encode("utf-8")).hexdigest()[:24]

    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": node_id,
        "operation_type": "delete",
        "status": "running",
        "request": {"nodebalancer_id": nodebalancer_id, "config_id": config_id, "node_id": node_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    ops.append(op)

    # Transition active/updating/error -> deleting -> deleted
    # Validate lifecycle transition existence in schema: network_security has those transitions; enforce legal move
    cur = node.get("status")
    allowed_from = {
        "provisioning": ["active", "error"],
        "active": ["updating", "deleting", "error"],
        "updating": ["active", "error"],
        "deleting": ["deleted", "error"],
        "error": ["updating", "deleting"],
        "deleted": [],
    }
    if cur not in allowed_from or "deleting" not in allowed_from.get(cur, []):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", f"Node cannot be deleted from status '{cur}'.")

    # apply
    changed = False
    for r in ns:
        if r.get("id") == node_id and r.get("resource_type") == "nodebalancer_node" and r.get("deleted_at") is None:
            r["status"] = "deleting"
            r["updated_at"] = now
            r["last_operation_id"] = op_id
            r["deleted_at"] = now  # soft-delete timestamp set at delete request time
            changed = True
            break
    if not changed:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Node not found for deletion.")

    _save("network_security.json", ns)
    _save("operations.json", ops)

    # finalize status -> deleted
    ns2 = _load("network_security.json")
    ops2 = _load("operations.json")
    for r in ns2:
        if r.get("id") == node_id and r.get("resource_type") == "nodebalancer_node":
            # deleting -> deleted is allowed
            r["status"] = "deleted"
            r["updated_at"] = now
            r["last_operation_id"] = op_id
            break
    for o in ops2:
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["updated_at"] = now
            o["finished_at"] = now
            o["result"] = {"deleted": True}
            break
    _save("network_security.json", ns2)
    _save("operations.json", ops2)

    _log("ok")
    return {"data": {"id": node_id, "deleted": True}}

def list_regions(status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs_name = None
    for cand in ("request_logs.json", "usage.json", "audit_log.json", "audit_logs.json", "requests.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            logs_name = cand
            break
    def _log(status_s, credential_id=None, error_code=None):
        if not logs_name:
            return
        logs = _load(logs_name)
        row = {
            "id": "req_" + hashlib.sha256((now + str(time.time())).encode("utf-8")).hexdigest()[:20],
            "endpoint": "list_regions",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(logs_name, logs)

    # validation
    if status is not None and (not isinstance(status, str) or status not in ("active", "deprecated", "unavailable")):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, unavailable.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort_by is None:
        sort_by = "label"
    if not isinstance(sort_by, str) or sort_by not in ("label", "status", "created_at", "updated_at", "id"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by must be one of: label, status, created_at, updated_at, id.")
    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc.")

    # decode cursor
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("off:"):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    cat = _load("infra_catalog.json")
    rows = [r for r in cat if isinstance(r, dict) and r.get("catalog_type") == "region"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    def _key(v):
        x = v.get(sort_by)
        return "" if x is None else x

    rows.sort(key=_key, reverse=(sort_order == "desc"))

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
    }

