def list_placement_groups(region_id=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_placement_groups"
    used_cred = None

    def _log(status_code):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": used_cred,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": datetime.datetime.utcnow().isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Rate limit / quota enforcement (best-effort if collections exist)
    def _enforce_limits():
        nonlocal used_cred
        creds = _load("credentials.json")
        if not isinstance(creds, list):
            creds = []
        # choose any active credential row if present, else None (ambient auth)
        for c in creds:
            if isinstance(c, dict) and c.get("status") in (None, "active", "enabled"):
                used_cred = c.get("id")
                break

        policies = _load("usage_policies.json")
        if not isinstance(policies, list):
            policies = []
        policy = None
        for p in policies:
            if not isinstance(p, dict):
                continue
            if used_cred is not None and p.get("credential_id") == used_cred:
                policy = p
                break
        if policy is None:
            for p in policies:
                if isinstance(p, dict) and p.get("credential_id") in (None, "", "ambient"):
                    policy = p
                    break

        if not policy:
            return None

        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        # Rate limit per minute
        rpm = policy.get("rate_limit_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            cutoff = now - datetime.timedelta(minutes=1)
            n = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if used_cred is not None and r.get("credential_id") != used_cred:
                    continue
                ts = _parse_ts(r.get("ts"))
                if ts and ts >= cutoff:
                    n += 1
            if n >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rpm, window_seconds=60)

        # Daily quota
        qpd = policy.get("quota_per_day")
        if isinstance(qpd, int) and qpd >= 0:
            cutoff = now - datetime.timedelta(days=1)
            n = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if used_cred is not None and r.get("credential_id") != used_cred:
                    continue
                ts = _parse_ts(r.get("ts"))
                if ts and ts >= cutoff:
                    n += 1
            if n >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=qpd, window_seconds=86400)

        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log(limit_err["error"]["code"])
        return limit_err

    # Validate inputs
    if region_id is not None and not isinstance(region_id, str):
        e = _err("VALIDATION_ERROR", "region_id must be a string.")
        _log(e["error"]["code"])
        return e
    allowed_status = {"provisioning", "active", "updating", "deleting", "deleted", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "status is invalid.", allowed=sorted(list(allowed_status)))
            _log(e["error"]["code"])
            return e
    if limit is not None:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer.")
            _log(e["error"]["code"])
            return e
        if limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit out of range.", minimum=1, maximum=200)
            _log(e["error"]["code"])
            return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.")
        _log(e["error"]["code"])
        return e
    allowed_sort_by = {"label", "status", "region_id", "created_at", "updated_at", "id"}
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
            e = _err("VALIDATION_ERROR", "sort_by is invalid.", allowed=sorted(list(allowed_sort_by)))
            _log(e["error"]["code"])
            return e
    allowed_sort_order = {"asc", "desc"}
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
            e = _err("VALIDATION_ERROR", "sort_order is invalid.", allowed=sorted(list(allowed_sort_order)))
            _log(e["error"]["code"])
            return e

    if sort_by is None:
        sort_by = "created_at"
    if sort_order is None:
        sort_order = "asc"

    # Validate region exists if provided
    if region_id is not None:
        catalog = _load("infra_catalog.json")
        if not isinstance(catalog, list):
            catalog = []
        found_region = False
        for it in catalog:
            if isinstance(it, dict) and it.get("catalog_type") == "region" and it.get("id") == region_id:
                found_region = True
                break
        if not found_region:
            e = _err("NOT_FOUND", "Region not found.", region_id=region_id)
            _log(e["error"]["code"])
            return e

    rows = _load("network_security.json")
    if not isinstance(rows, list):
        rows = []

    # Filter to placement groups; exclude soft-deleted by default
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "placement_group":
            continue
        if r.get("deleted_at") is not None:
            continue
        if region_id is not None and r.get("region_id") != region_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        out.append(r)

    def _sort_key(x):
        v = x.get(sort_by)
        if v is None:
            return ""
        return v

    reverse = (sort_order == "desc")
    try:
        out.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # mixed types; fall back to string
        out.sort(key=lambda x: str(x.get(sort_by, "")), reverse=reverse)

    # Cursor pagination: cursor encodes an integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("o:"):
                offset = int(raw.split(":", 1)[1])
            else:
                offset = int(raw)
            if offset < 0:
                raise ValueError()
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log(e["error"]["code"])
            return e

    page_limit = limit if limit is not None else 100
    total = len(out)
    page = out[offset:offset + page_limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(("o:%d" % next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": page_limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log("OK")
    return resp

