def delete_placement_group(placement_group_id, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / quota ----
    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256(f"{now}:{time.time_ns()}:{os.getpid()}".encode()).hexdigest()[:20],
            "ts": now,
            "endpoint": "delete_placement_group",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(entry)
        _save("request_log.json", logs)

    def _enforce_rate_limit():
        # Best-effort: if no request_log exists, create it and proceed.
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        # naive per-endpoint sliding window: 300 req / 60s
        window_s = 60
        limit = 300
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in reversed(logs[-2000:]):
            if isinstance(r, dict) and r.get("endpoint") == "delete_placement_group":
                ts = r.get("ts")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
        if recent >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log("error", error_code="RATE_LIMIT")
        return rl

    # ---- validate inputs ----
    if not isinstance(placement_group_id, str) or not re.match(r"^pg_01H8[0-9A-Z]{15,}$", placement_group_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "placement_group_id is invalid.")

    net = _load("network_security.json")
    if not isinstance(net, list):
        net = []

    pg = None
    pg_idx = None
    for i, r in enumerate(net):
        if isinstance(r, dict) and r.get("id") == placement_group_id and r.get("resource_type") == "placement_group":
            pg = r
            pg_idx = i
            break

    if not pg or pg.get("deleted_at") is not None or pg.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Placement group not found.")

    # Ensure it is deletable: must be active-ish and have no assigned instances
    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []

    assigned = []
    for inst in instances:
        if isinstance(inst, dict) and inst.get("deleted_at") is None and inst.get("placement_group_id") == placement_group_id:
            assigned.append(inst.get("id"))

    if assigned:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Placement group has assigned instances and cannot be deleted.", instance_ids=assigned)

    # lifecycle transitions allowed: active/updating -> deleting -> deleted; provisioning -> active/error only
    status = pg.get("status")
    allowed_to_delete_from = {"active", "updating", "error"}
    if status not in allowed_to_delete_from:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Placement group cannot be deleted in its current state.", current_status=status)

    # Ensure no other running operation for this resource
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []

    for op in ops:
        if isinstance(op, dict) and op.get("resource_collection") == "network_security" and op.get("resource_id") == placement_group_id:
            if op.get("status") == "running":
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "Another operation is currently running for this placement group.", operation_id=op.get("id"))

    # Create operation (delete) and perform soft-delete with deleting -> deleted
    def _new_op_id():
        return "op_" + hashlib.sha256(f"{now}:{time.time_ns()}:{placement_group_id}".encode()).hexdigest()[:20]

    op_id = _new_op_id()
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": placement_group_id,
        "operation_type": "delete",
        "status": "running",
        "request": {"placement_group_id": placement_group_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }

    # Move to deleting
    pg["status"] = "deleting"
    pg["updated_at"] = now
    pg["last_operation_id"] = op_id
    net[pg_idx] = pg
    ops.append(op)
    _save("network_security.json", net)
    _save("operations.json", ops)

    # Complete deletion
    now2 = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    pg["status"] = "deleted"
    pg["deleted_at"] = now2
    pg["updated_at"] = now2
    pg["last_operation_id"] = op_id
    net[pg_idx] = pg

    # Finish op
    for i in range(len(ops) - 1, -1, -1):
        if ops[i].get("id") == op_id:
            ops[i]["status"] = "succeeded"
            ops[i]["updated_at"] = now2
            ops[i]["finished_at"] = now2
            ops[i]["result"] = {"deleted": True}
            break

    _save("network_security.json", net)
    _save("operations.json", ops)

    resp = {
        "placement_group_id": placement_group_id,
        "status": "deleted",
        "deleted_at": now2,
        "operation_id": op_id,
    }
    _log("ok")
    return resp

def assign_instances(placement_group_id, instance_ids, **_extra):
    import json, os, datetime, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "assign_instances"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None, operation_id=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(placement_group_id, str) or not placement_group_id:
        e = _err("VALIDATION_ERROR", "placement_group_id must be a string", field="placement_group_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(instance_ids, list) or len(instance_ids) < 1 or any((not isinstance(x, str) or not x) for x in instance_ids):
        e = _err("VALIDATION_ERROR", "instance_ids must be a non-empty array of strings", field="instance_ids")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if len(set(instance_ids)) != len(instance_ids):
        e = _err("VALIDATION_ERROR", "instance_ids must not contain duplicates", field="instance_ids")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    ns = _load("network_security.json")
    if not isinstance(ns, list):
        ns = []
    pg = None
    for r in ns:
        if isinstance(r, dict) and r.get("id") == placement_group_id and r.get("deleted_at") is None:
            pg = r
            break
    if not pg or pg.get("resource_type") != "placement_group":
        e = _err("NOT_FOUND", "Placement group not found", field="placement_group_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if pg.get("status") not in ("active", "updating"):
        e = _err("CONFLICT", "Placement group is not in an assignable state")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst_map = {r.get("id"): r for r in instances if isinstance(r, dict) and r.get("deleted_at") is None}

    missing = [iid for iid in instance_ids if iid not in inst_map]
    if missing:
        e = _err("NOT_FOUND", "One or more instances were not found", missing_instance_ids=missing)
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # region match and single placement group membership
    pg_region = pg.get("region_id")
    for iid in instance_ids:
        inst = inst_map[iid]
        if pg_region and inst.get("region_id") and inst.get("region_id") != pg_region:
            e = _err("CONFLICT", "placement group and instance must share the same region_id", instance_id=iid)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        existing_pg = inst.get("placement_group_id")
        if existing_pg is not None and existing_pg != placement_group_id:
            e = _err("CONFLICT", "Instance already belongs to a different placement group", instance_id=iid, current_placement_group_id=existing_pg)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    op_id = _new_id("op")
    op = {
        "id": op_id,
        "resource_collection": "linode_instances",
        "resource_id": instance_ids[0],  # audit trail anchor
        "operation_type": "assign",
        "status": "succeeded",
        "request": {"placement_group_id": placement_group_id, "instance_ids": instance_ids},
        "result": {"assigned_instance_ids": instance_ids},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    operations.append(op)

    for iid in instance_ids:
        inst_map[iid]["placement_group_id"] = placement_group_id
        inst_map[iid]["updated_at"] = now
        inst_map[iid]["last_operation_id"] = op_id

    _save("operations.json", operations)
    _save("linode_instances.json", instances)

    _log("ok", resource={"collection": "network_security", "id": placement_group_id}, operation_id=op_id)
    return {"placement_group_id": placement_group_id, "assigned_instance_ids": instance_ids, "operation": op}

def unassign_instances(placement_group_id, instance_ids, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256(f"{now}:{time.time_ns()}:{os.getpid()}".encode()).hexdigest()[:20],
            "ts": now,
            "endpoint": "unassign_instances",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(entry)
        _save("request_log.json", logs)

    def _enforce_rate_limit():
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit = 300
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in reversed(logs[-2000:]):
            if isinstance(r, dict) and r.get("endpoint") == "unassign_instances":
                ts = r.get("ts")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
        if recent >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log("error", error_code="RATE_LIMIT")
        return rl

    if not isinstance(placement_group_id, str) or not re.match(r"^pg_01H8[0-9A-Z]{15,}$", placement_group_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "placement_group_id is invalid.")
    if not isinstance(instance_ids, list) or len(instance_ids) < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_ids must be a non-empty array.")
    for x in instance_ids:
        if not isinstance(x, str) or not re.match(r"^lin_01H8[0-9A-Z]{15,}$", x):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instance_ids contains an invalid id.", instance_id=x)

    net = _load("network_security.json")
    if not isinstance(net, list):
        net = []
    pg = None
    for r in net:
        if isinstance(r, dict) and r.get("id") == placement_group_id and r.get("resource_type") == "placement_group":
            pg = r
            break
    if not pg or pg.get("deleted_at") is not None or pg.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Placement group not found.")

    if pg.get("status") not in ("active", "updating"):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Placement group is not in a modifiable state.", current_status=pg.get("status"))

    instances = _load("linode_instances.json")
    if not isinstance(instances, list):
        instances = []
    by_id = {r.get("id"): r for r in instances if isinstance(r, dict)}

    missing = [iid for iid in instance_ids if iid not in by_id or by_id[iid].get("deleted_at") is not None or by_id[iid].get("status") == "deleted"]
    if missing:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "One or more instances were not found.", instance_ids=missing)

    # Determine which will change (must be assigned to this pg to unassign)
    to_change = [iid for iid in instance_ids if by_id[iid].get("placement_group_id") == placement_group_id]
    not_assigned = [iid for iid in instance_ids if by_id[iid].get("placement_group_id") != placement_group_id]

    if not to_change:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "None of the specified instances are assigned to this placement group.", not_assigned_instance_ids=not_assigned)

    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []
    for op in ops:
        if isinstance(op, dict) and op.get("status") == "running" and op.get("resource_collection") == "linode_instances" and op.get("resource_id") in to_change:
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Another operation is currently running for one or more instances.", operation_id=op.get("id"))

    def _new_op_id(seed):
        return "op_" + hashlib.sha256(f"{now}:{time.time_ns()}:{seed}".encode()).hexdigest()[:20]

    op_ids = []
    for iid in to_change:
        op_id = _new_op_id(iid)
        op_ids.append(op_id)
        ops.append({
            "id": op_id,
            "resource_collection": "linode_instances",
            "resource_id": iid,
            "operation_type": "unassign",
            "status": "running",
            "request": {"placement_group_id": placement_group_id, "instance_id": iid},
            "result": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": None,
        })
    _save("operations.json", ops)

    now2 = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    changed = []
    for idx, inst in enumerate(instances):
        if not isinstance(inst, dict):
            continue
        iid = inst.get("id")
        if iid in to_change:
            inst["placement_group_id"] = None
            inst["updated_at"] = now2
            inst["last_operation_id"] = op_ids[to_change.index(iid)]
            instances[idx] = inst
            changed.append(iid)

    for i in range(len(ops)):
        op = ops[i]
        if isinstance(op, dict) and op.get("id") in op_ids:
            op["status"] = "succeeded"
            op["updated_at"] = now2
            op["finished_at"] = now2
            op["result"] = {"placement_group_id": None}
            ops[i] = op

    _save("linode_instances.json", instances)
    _save("operations.json", ops)

    membership = [r.get("id") for r in instances if isinstance(r, dict) and r.get("deleted_at") is None and r.get("placement_group_id") == placement_group_id]
    result = {
        "placement_group": pg,
        "assigned_instance_ids": membership,
        "changed_instance_ids": changed,
        "not_assigned_instance_ids": not_assigned,
        "operation_ids": op_ids,
    }
    _log("ok")
    return result

def list_vpcs(region_id=None, status=None, label=None, parent_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256(f"{now}:{time.time_ns()}:{os.getpid()}".encode()).hexdigest()[:20],
            "ts": now,
            "endpoint": "list_vpcs",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(entry)
        _save("request_log.json", logs)

    def _enforce_rate_limit():
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit_r = 600  # reads a bit higher
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in reversed(logs[-4000:]):
            if isinstance(r, dict) and r.get("endpoint") == "list_vpcs":
                ts = r.get("ts")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
        if recent >= limit_r:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log("error", error_code="RATE_LIMIT")
        return rl

    # ---- validate ----
    if region_id is not None and not isinstance(region_id, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region_id must be a string.")
    if label is not None and not isinstance(label, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a string.")
    if parent_id is not None and not isinstance(parent_id, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_id must be a string.")
    allowed_status = {"provisioning", "active", "updating", "deleting", "deleted", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid.", allowed=list(sorted(allowed_status)))
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    allowed_sort_by = {"created_at", "updated_at", "label", "status"}
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by is invalid.", allowed=list(sorted(allowed_sort_by)))
    allowed_sort_order = {"asc", "desc"}
    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order is invalid.", allowed=list(sorted(allowed_sort_order)))
    if cursor is not None and not isinstance(cursor, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Validate region_id reference if provided
    if region_id is not None:
        cat = _load("infra_catalog.json")
        if not isinstance(cat, list):
            cat = []
        ok_region = any(isinstance(r, dict) and r.get("id") == region_id and r.get("catalog_type") == "region" for r in cat)
        if not ok_region:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "region_id does not reference a known region catalog item.", region_id=region_id)

    # ---- load VPCs from network_security ----
    net = _load("network_security.json")
    if not isinstance(net, list):
        net = []

    rows = []
    for r in net:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "vpc":
            continue
        # Exclude soft-deleted by default
        if r.get("deleted_at") is not None or r.get("status") == "deleted":
            continue
        if region_id is not None and r.get("region_id") != region_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if label is not None and r.get("label") != label:
            continue
        if parent_id is not None and r.get("parent_id") != parent_id:
            continue
        rows.append(r)

    # ---- sort ----
    reverse = (sort_order == "desc")
    def _key(x):
        v = x.get(sort_by)
        if v is None:
            return ""
        return v
    rows.sort(key=_key, reverse=reverse)

    # ---- cursor pagination (opaque) ----
    start = 0
    if cursor:
        # cursor is base64url of "offset:<n>"
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8", "strict")
            if raw.startswith("offset:"):
                start = int(raw.split(":", 1)[1])
                if start < 0:
                    raise ValueError("neg")
            else:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        nxt = f"offset:{start + limit}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(nxt).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
    }
    _log("ok")
    return resp

def get_vpc(vpc_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_vpc"

    # Rate/quota + request log (best-effort; if missing collection file, create it)
    def _log(status, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            row = {
                "id": f"req_{int(time.time()*1000)}",
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Input validation
    if not isinstance(vpc_id, str):
        _log("error", {"code": "VALIDATION_ERROR", "message": "vpc_id must be a string"})
        return _err("VALIDATION_ERROR", "vpc_id must be a string")
    if not re.match(r"^vpc_01H8[0-9A-Z]{15,}$", vpc_id):
        _log("error", {"code": "VALIDATION_ERROR", "message": "vpc_id does not match required pattern"})
        return _err("VALIDATION_ERROR", "vpc_id does not match required pattern")

    ns = _load("network_security.json")
    vpc = None
    for r in ns:
        if isinstance(r, dict) and r.get("id") == vpc_id and r.get("resource_type") == "vpc":
            vpc = r
            break
    if not vpc or vpc.get("deleted_at") is not None or vpc.get("status") == "deleted":
        _log("error", {"code": "NOT_FOUND", "message": "VPC not found"})
        return _err("NOT_FOUND", "VPC not found")

    _log("ok", meta={"resource_id": vpc_id})
    return {"data": vpc}

def create_vpc(label, region_id, spec=None, **_extra):
    import json, os, datetime, time, re, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_vpc"

    def _log(status, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            row = {
                "id": f"req_{int(time.time()*1000)}",
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    if not isinstance(label, str) or not label.strip():
        _log("error", {"code": "VALIDATION_ERROR", "message": "label is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string")
    if not isinstance(region_id, str) or not region_id.strip():
        _log("error", {"code": "VALIDATION_ERROR", "message": "region_id is required and must be a string"})
        return _err("VALIDATION_ERROR", "region_id is required and must be a string")
    if spec is None:
        spec = {}
    if not isinstance(spec, dict):
        _log("error", {"code": "VALIDATION_ERROR", "message": "spec must be an object"})
        return _err("VALIDATION_ERROR", "spec must be an object")

    catalog = _load("infra_catalog.json")
    region_ok = False
    for c in catalog:
        if isinstance(c, dict) and c.get("id") == region_id and c.get("catalog_type") == "region" and c.get("status") == "active":
            region_ok = True
            break
    if not region_ok:
        _log("error", {"code": "VALIDATION_ERROR", "message": "region_id must reference an active region in infra_catalog"})
        return _err("VALIDATION_ERROR", "region_id must reference an active region in infra_catalog")

    ns = _load("network_security.json")
    # Uniqueness: placement_group enforces; VPC uniqueness implied by tool text; enforce unique(label, region_id) for vpc where not deleted.
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") == "vpc" and r.get("deleted_at") is None and r.get("status") != "deleted":
            if r.get("region_id") == region_id and (r.get("label") or "") == label:
                _log("error", {"code": "CONFLICT", "message": "A VPC with this label already exists in the region"})
                return _err("CONFLICT", "A VPC with this label already exists in the region")

    # Create ids
    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        # keep prefix like vpc_01H8 then 16+ chars
        tail = "".join(random.choice(alphabet) for _ in range(18))
        return f"{prefix}{tail}"

    vpc_id = _gen_id("vpc_01H8")
    existing_ids = {r.get("id") for r in ns if isinstance(r, dict)}
    tries = 0
    while vpc_id in existing_ids and tries < 10:
        vpc_id = _gen_id("vpc_01H8")
        tries += 1
    if vpc_id in existing_ids:
        _log("error", {"code": "CONFLICT", "message": "Could not allocate unique id"})
        return _err("CONFLICT", "Could not allocate unique id")

    ops = _load("operations.json")
    op_id = f"op_{int(time.time()*1000)}"

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    vpc_row = {
        "id": vpc_id,
        "resource_type": "vpc",
        "region_id": region_id,
        "status": "provisioning",
        "label": label,
        "parent_id": None,
        "instance_id": None,
        "spec": spec,
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    op_row = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": vpc_id,
        "operation_type": "create",
        "status": "succeeded",
        "request": {"label": label, "region_id": region_id, "spec": spec},
        "result": {"id": vpc_id},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }

    ns.append(vpc_row)
    ops.append(op_row)

    _save("network_security.json", ns)
    _save("operations.json", ops)

    # Backend may flip to active; keep realistic immediate activation
    vpc_row["status"] = "active"
    vpc_row["updated_at"] = now
    _save("network_security.json", ns)

    _log("ok", meta={"resource_id": vpc_id, "operation_id": op_id})
    return {"data": vpc_row}

def update_vpc(vpc_id, label=None, spec=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_vpc"

    def _log(status_s, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            row = {
                "id": f"req_{int(time.time()*1000)}",
                "ts": now,
                "endpoint": endpoint,
                "status": status_s,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(vpc_id, str):
        _log("error", {"code": "VALIDATION_ERROR", "message": "vpc_id must be a string"})
        return _err("VALIDATION_ERROR", "vpc_id must be a string")
    if not re.match(r"^vpc_01H8[0-9A-Z]{15,}$", vpc_id):
        _log("error", {"code": "VALIDATION_ERROR", "message": "vpc_id does not match required pattern"})
        return _err("VALIDATION_ERROR", "vpc_id does not match required pattern")

    if label is not None and (not isinstance(label, str) or not label.strip()):
        _log("error", {"code": "VALIDATION_ERROR", "message": "label must be a non-empty string"})
        return _err("VALIDATION_ERROR", "label must be a non-empty string")
    if spec is not None and not isinstance(spec, dict):
        _log("error", {"code": "VALIDATION_ERROR", "message": "spec must be an object"})
        return _err("VALIDATION_ERROR", "spec must be an object")
    allowed_status = ["provisioning", "active", "updating", "deleting", "deleted", "error"]
    if status is not None and status not in allowed_status:
        _log("error", {"code": "VALIDATION_ERROR", "message": "status is not in allowed enum"})
        return _err("VALIDATION_ERROR", "status is not in allowed enum")

    ns = _load("network_security.json")
    idx = None
    for i, r in enumerate(ns):
        if isinstance(r, dict) and r.get("id") == vpc_id and r.get("resource_type") == "vpc":
            idx = i
            break
    if idx is None or ns[idx].get("deleted_at") is not None or ns[idx].get("status") == "deleted":
        _log("error", {"code": "NOT_FOUND", "message": "VPC not found"})
        return _err("NOT_FOUND", "VPC not found")

    vpc = ns[idx]

    # Label uniqueness per region
    if label is not None and label != vpc.get("label"):
        for r in ns:
            if not isinstance(r, dict):
                continue
            if r.get("resource_type") == "vpc" and r.get("deleted_at") is None and r.get("status") != "deleted":
                if r.get("region_id") == vpc.get("region_id") and (r.get("label") or "") == label and r.get("id") != vpc_id:
                    _log("error", {"code": "CONFLICT", "message": "A VPC with this label already exists in the region"})
                    return _err("CONFLICT", "A VPC with this label already exists in the region")

    # Status changes are generally managed by operations; only allow legal lifecycle transitions if requested.
    lifecycle = {
        "provisioning": ["active", "error"],
        "active": ["updating", "deleting", "error"],
        "updating": ["active", "error"],
        "deleting": ["deleted", "error"],
        "error": ["updating", "deleting"],
        "deleted": [],
    }
    if status is not None:
        cur = vpc.get("status")
        if cur not in lifecycle:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Current VPC status invalid"})
            return _err("VALIDATION_ERROR", "Current VPC status invalid")
        if status == cur:
            pass
        elif status not in lifecycle.get(cur, []):
            _log("error", {"code": "INVALID_TRANSITION", "message": f"Illegal status transition from {cur} to {status}"})
            return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}")

    if label is None and spec is None and status is None:
        _log("error", {"code": "VALIDATION_ERROR", "message": "No mutable fields provided"})
        return _err("VALIDATION_ERROR", "No mutable fields provided")

    # Create operation + update row
    ops = _load("operations.json")
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_id = f"op_{int(time.time()*1000)}"
    changed = {}
    if label is not None:
        vpc["label"] = label
        changed["label"] = label
    if spec is not None:
        vpc["spec"] = spec
        changed["spec"] = spec
    if status is not None:
        vpc["status"] = status
        changed["status"] = status

    vpc["updated_at"] = now
    vpc["last_operation_id"] = op_id

    op_row = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": vpc_id,
        "operation_type": "update",
        "status": "succeeded",
        "request": {"vpc_id": vpc_id, "label": label, "spec": spec, "status": status},
        "result": {"changed": list(changed.keys())},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    ops.append(op_row)

    ns[idx] = vpc
    _save("network_security.json", ns)
    _save("operations.json", ops)

    _log("ok", meta={"resource_id": vpc_id, "operation_id": op_id})
    return {"data": vpc}

def delete_vpc(vpc_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_vpc"

    def _log(status_s, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            row = {
                "id": f"req_{int(time.time()*1000)}",
                "ts": now,
                "endpoint": endpoint,
                "status": status_s,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(vpc_id, str):
        _log("error", {"code": "VALIDATION_ERROR", "message": "vpc_id must be a string"})
        return _err("VALIDATION_ERROR", "vpc_id must be a string")
    if not re.match(r"^vpc_01H8[0-9A-Z]{15,}$", vpc_id):
        _log("error", {"code": "VALIDATION_ERROR", "message": "vpc_id does not match required pattern"})
        return _err("VALIDATION_ERROR", "vpc_id does not match required pattern")

    ns = _load("network_security.json")
    ops = _load("operations.json")

    vpc_i = None
    for i, r in enumerate(ns):
        if isinstance(r, dict) and r.get("id") == vpc_id and r.get("resource_type") == "vpc":
            vpc_i = i
            break
    if vpc_i is None:
        _log("error", {"code": "NOT_FOUND", "message": "VPC not found"})
        return _err("NOT_FOUND", "VPC not found")

    vpc = ns[vpc_i]
    if vpc.get("deleted_at") is not None or vpc.get("status") == "deleted":
        _log("error", {"code": "NOT_FOUND", "message": "VPC not found"})
        return _err("NOT_FOUND", "VPC not found")

    # Enforce delete_vpc rule: must soft-delete subnets first (operation ordering).
    subnets = []
    for r in ns:
        if isinstance(r, dict) and r.get("resource_type") == "vpc_subnet" and r.get("parent_id") == vpc_id and r.get("deleted_at") is None and r.get("status") != "deleted":
            subnets.append(r)
    if subnets:
        _log("error", {"code": "CONFLICT", "message": "VPC has active subnets; delete subnets before deleting VPC"})
        return _err("CONFLICT", "VPC has active subnets; delete subnets before deleting VPC", dependent_subnet_ids=[s.get("id") for s in subnets])

    lifecycle = {
        "provisioning": ["active", "error"],
        "active": ["updating", "deleting", "error"],
        "updating": ["active", "error"],
        "deleting": ["deleted", "error"],
        "error": ["updating", "deleting"],
        "deleted": [],
    }
    cur = vpc.get("status")
    if cur == "deleting":
        # idempotent-ish: if already deleting, acknowledge
        _log("ok", meta={"resource_id": vpc_id, "already": "deleting"})
        return {"data": {"id": vpc_id, "status": "deleting"}}
    if cur not in lifecycle or "deleting" not in lifecycle.get(cur, []):
        _log("error", {"code": "CONFLICT", "message": f"VPC cannot be deleted from status {cur}"})
        return _err("CONFLICT", f"VPC cannot be deleted from status {cur}")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_id = f"op_{int(time.time()*1000)}"

    # Transition to deleting, then deleted with soft delete.
    vpc["status"] = "deleting"
    vpc["updated_at"] = now
    vpc["last_operation_id"] = op_id

    op_row = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": vpc_id,
        "operation_type": "delete",
        "status": "succeeded",
        "request": {"vpc_id": vpc_id},
        "result": {"deleted": True},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    ops.append(op_row)

    # Finalize soft delete immediately for offline backend determinism
    vpc["status"] = "deleted"
    vpc["deleted_at"] = now
    vpc["updated_at"] = now

    ns[vpc_i] = vpc
    _save("network_security.json", ns)
    _save("operations.json", ops)

    _log("ok", meta={"resource_id": vpc_id, "operation_id": op_id})
    return {"data": {"id": vpc_id, "status": "deleted", "deleted_at": now}}

def list_vpc_subnets(vpc_id, limit=None, cursor=None, sort_by=None, sort_order=None, status=None, **_extra):
    import json, os, datetime, re, base64, time
    import ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_str(x):
        return isinstance(x, str)

    def _log_and_enforce(endpoint, request_obj):
        logs = _load("request_logs.json")
        usage = _load("usage_counters.json")
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        now_iso = now_dt.isoformat()

        # Identify caller context (ambient). If an api_keys store exists, pick any active key.
        api_keys = _load("api_keys.json")
        cred = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") in (None, "active"):
                cred = k
                break
        credential_id = cred.get("id") if isinstance(cred, dict) else None

        # Rate limit: 120 requests per rolling minute per credential (or global if none).
        window_s = 60
        limit_per_window = 120
        cutoff = now_dt - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts_dt >= cutoff:
                recent += 1
        if recent >= limit_per_window:
            # log rejected call
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": "RATE_LIMIT",
                "timestamp": now_iso,
                "latency_ms": 0,
                "request": request_obj
            })
            _save("request_logs.json", logs)
            return False, _err("RATE_LIMIT", "Rate limit exceeded"), credential_id, logs, usage, now_iso

        return True, None, credential_id, logs, usage, now_iso

    def _finalize_log(logs, usage, credential_id, endpoint, request_obj, status_code, started):
        end = time.time()
        now_iso = _now()
        logs.append({
            "id": f"req_{int(end*1000)}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "timestamp": now_iso,
            "latency_ms": int((end - started) * 1000),
            "request": request_obj
        })
        _save("request_logs.json", logs)

        # Increment simple usage counter if present
        if isinstance(usage, dict):
            k = endpoint
            cur = usage.get(k, 0)
            if isinstance(cur, int):
                usage[k] = cur + 1
            else:
                usage[k] = 1
            _save("usage_counters.json", usage)

    started = time.time()
    endpoint = "list_vpc_subnets"
    request_obj = {"vpc_id": vpc_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order, "status": status}

    ok, early, credential_id, logs, usage, _ = _log_and_enforce(endpoint, request_obj)
    if not ok:
        return early

    def _return(payload, status_code="OK"):
        _finalize_log(logs, usage, credential_id, endpoint, request_obj, status_code, started)
        return payload

    # Validate inputs
    if not _is_str(vpc_id) or not re.match(r"^vpc_01H8[0-9A-Z]{15,}$", vpc_id):
        return _return(_err("VALIDATION_ERROR", "vpc_id is malformed."), "VALIDATION_ERROR")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _return(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 500."), "VALIDATION_ERROR")

    if cursor is not None and not _is_str(cursor):
        return _return(_err("VALIDATION_ERROR", "cursor must be a string."), "VALIDATION_ERROR")

    allowed_sort_by = {"created_at", "updated_at", "label", "status"}
    if sort_by is None:
        sort_by = "created_at"
    if not _is_str(sort_by) or sort_by not in allowed_sort_by:
        return _return(_err("VALIDATION_ERROR", "sort_by is invalid.", allowed=sorted(list(allowed_sort_by))), "VALIDATION_ERROR")

    allowed_sort_order = {"asc", "desc"}
    if sort_order is None:
        sort_order = "asc"
    if not _is_str(sort_order) or sort_order not in allowed_sort_order:
        return _return(_err("VALIDATION_ERROR", "sort_order is invalid.", allowed=sorted(list(allowed_sort_order))), "VALIDATION_ERROR")

    allowed_status = {"provisioning", "active", "updating", "deleting", "deleted", "error"}
    if status is not None:
        if not _is_str(status) or status not in allowed_status:
            return _return(_err("VALIDATION_ERROR", "status is invalid.", allowed=sorted(list(allowed_status))), "VALIDATION_ERROR")

    # Load resources
    ns = _load("network_security.json")
    if not isinstance(ns, list):
        return _return(_err("CONFLICT", "Datastore is corrupted (network_security not a list)."), "CONFLICT")

    # Authorization (ambient): if we have any API key, assume authorized; if no key store, allow.
    api_keys = _load("api_keys.json")
    if api_keys != [] and not any(isinstance(k, dict) and k.get("status") in (None, "active") for k in api_keys):
        return _return(_err("UNAUTHORIZED", "No authorized token available."), "UNAUTHORIZED")

    # Find VPC exists and not soft-deleted
    vpc = None
    for r in ns:
        if isinstance(r, dict) and r.get("resource_type") == "vpc" and r.get("id") == vpc_id and r.get("deleted_at") is None:
            vpc = r
            break
    if vpc is None:
        return _return(_err("NOT_FOUND", "VPC not found."), "NOT_FOUND")

    # Collect subnets
    subnets = []
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "vpc_subnet":
            continue
        if r.get("parent_id") != vpc_id:
            continue
        # Reads exclude deleted_at IS NOT NULL
        if r.get("deleted_at") is not None:
            continue
        if status is not None and r.get("status") != status:
            continue
        subnets.append(r)

    # Sort
    def _key(x):
        v = x.get(sort_by)
        if v is None:
            return ""
        return v

    reverse = (sort_order == "desc")
    try:
        subnets.sort(key=_key, reverse=reverse)
    except Exception:
        # If incomparable types, fall back to string
        subnets.sort(key=lambda x: str(x.get(sort_by))), reverse

    # Cursor pagination: cursor is base64 of integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            return _return(_err("VALIDATION_ERROR", "cursor is invalid."), "VALIDATION_ERROR")

    total = len(subnets)
    page = subnets[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    return _return({
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }, "OK")

