def create_vpc_subnet(vpc_id, label, spec, **_extra):
    import json, os, datetime, re, time, secrets
    import ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        # Looks like: prefix_01H8 + base32-ish uppercase
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        tail = "".join(secrets.choice(alphabet) for _ in range(18))
        return f"{prefix}_01H8{tail}"

    def _log_and_enforce(endpoint, request_obj):
        logs = _load("request_logs.json")
        usage = _load("usage_counters.json")
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        now_iso = now_dt.isoformat()

        api_keys = _load("api_keys.json")
        cred = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") in (None, "active"):
                cred = k
                break
        credential_id = cred.get("id") if isinstance(cred, dict) else None

        window_s = 60
        limit_per_window = 120
        cutoff = now_dt - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts_dt >= cutoff:
                recent += 1
        if recent >= limit_per_window:
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": "RATE_LIMIT",
                "timestamp": now_iso,
                "latency_ms": 0,
                "request": request_obj
            })
            _save("request_logs.json", logs)
            return False, _err("RATE_LIMIT", "Rate limit exceeded"), credential_id, logs, usage

        return True, None, credential_id, logs, usage

    def _finalize_log(logs, usage, credential_id, endpoint, request_obj, status_code, started):
        end = time.time()
        logs.append({
            "id": f"req_{int(end*1000)}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "timestamp": _now(),
            "latency_ms": int((end - started) * 1000),
            "request": request_obj
        })
        _save("request_logs.json", logs)
        if isinstance(usage, dict):
            usage[endpoint] = int(usage.get(endpoint, 0) or 0) + 1
            _save("usage_counters.json", usage)

    started = time.time()
    endpoint = "create_vpc_subnet"
    request_obj = {"vpc_id": vpc_id, "label": label, "spec": spec}

    ok, early, credential_id, logs, usage = _log_and_enforce(endpoint, request_obj)
    if not ok:
        return early

    def _return(payload, status_code="OK"):
        _finalize_log(logs, usage, credential_id, endpoint, request_obj, status_code, started)
        return payload

    # Validate
    if not isinstance(vpc_id, str) or not re.match(r"^vpc_01H8[0-9A-Z]{15,}$", vpc_id):
        return _return(_err("VALIDATION_ERROR", "vpc_id is malformed."), "VALIDATION_ERROR")
    if not isinstance(label, str) or len(label.strip()) < 1:
        return _return(_err("VALIDATION_ERROR", "label must be a non-empty string."), "VALIDATION_ERROR")
    if not isinstance(spec, dict):
        return _return(_err("VALIDATION_ERROR", "spec must be an object."), "VALIDATION_ERROR")

    # Require CIDR in spec (per schema constraint for vpc_subnet)
    cidr = spec.get("cidr")
    if not isinstance(cidr, str):
        return _return(_err("VALIDATION_ERROR", "spec.cidr is required and must be a string."), "VALIDATION_ERROR")
    try:
        new_net = ipaddress.ip_network(cidr, strict=True)
        if new_net.version != 4:
            return _return(_err("VALIDATION_ERROR", "spec.cidr must be an IPv4 RFC4632 CIDR."), "VALIDATION_ERROR")
    except Exception:
        return _return(_err("VALIDATION_ERROR", "spec.cidr is not a valid CIDR."), "VALIDATION_ERROR")

    api_keys = _load("api_keys.json")
    if api_keys != [] and not any(isinstance(k, dict) and k.get("status") in (None, "active") for k in api_keys):
        return _return(_err("UNAUTHORIZED", "No authorized token available."), "UNAUTHORIZED")

    ns = _load("network_security.json")
    ops = _load("operations.json")
    if not isinstance(ns, list) or not isinstance(ops, list):
        return _return(_err("CONFLICT", "Datastore is corrupted."), "CONFLICT")

    # VPC must exist
    vpc = None
    for r in ns:
        if isinstance(r, dict) and r.get("resource_type") == "vpc" and r.get("id") == vpc_id and r.get("deleted_at") is None:
            vpc = r
            break
    if vpc is None:
        return _return(_err("NOT_FOUND", "VPC not found."), "NOT_FOUND")

    # Uniqueness: label within VPC (treat case-insensitive)
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "vpc_subnet" or r.get("parent_id") != vpc_id:
            continue
        if r.get("deleted_at") is not None:
            continue
        if isinstance(r.get("label"), str) and r.get("label").strip().lower() == label.strip().lower():
            return _return(_err("CONFLICT", "A subnet with this label already exists in the VPC."), "CONFLICT")

    # Non-overlap within same VPC
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "vpc_subnet" or r.get("parent_id") != vpc_id:
            continue
        if r.get("deleted_at") is not None:
            continue
        existing_cidr = (r.get("spec") or {}).get("cidr")
        if not isinstance(existing_cidr, str):
            continue
        try:
            existing_net = ipaddress.ip_network(existing_cidr, strict=True)
        except Exception:
            continue
        if new_net.overlaps(existing_net):
            return _return(_err("CONFLICT", "Subnet CIDR overlaps with an existing subnet in this VPC.", conflicting_subnet_id=r.get("id")), "CONFLICT")

    # Create subnet record
    now = _now()
    subnet_id = _gen_id("subnet")
    new_row = {
        "id": subnet_id,
        "resource_type": "vpc_subnet",
        "region_id": vpc.get("region_id"),
        "status": "provisioning",
        "label": label.strip(),
        "parent_id": vpc_id,
        "instance_id": None,
        "spec": spec,
        "last_operation_id": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }

    # Create operation and immediately mark succeeded (offline simulation of async)
    op_id = _gen_id("op")
    op_now = now
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": subnet_id,
        "operation_type": "create",
        "status": "running",
        "request": {"vpc_id": vpc_id, "label": new_row["label"], "spec": spec},
        "result": None,
        "error_message": None,
        "created_at": op_now,
        "updated_at": op_now,
        "started_at": op_now,
        "finished_at": None
    }

    # Enforce only one running operation per resource: new resource so OK.
    ops.append(op)
    new_row["last_operation_id"] = op_id
    ns.append(new_row)

    # Complete operation + transition subnet
    finished = _now()
    op["status"] = "succeeded"
    op["updated_at"] = finished
    op["finished_at"] = finished
    op["result"] = {"id": subnet_id, "status": "active"}
    new_row["status"] = "active"
    new_row["updated_at"] = finished

    _save("operations.json", ops)
    _save("network_security.json", ns)

    return _return({"data": new_row, "meta": {}}, "OK")

