            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "timestamp": _now(),
            "latency_ms": int((end - started) * 1000),
            "request": request_obj
        })
        _save("request_logs.json", logs)
        if isinstance(usage, dict):
            usage[endpoint] = int(usage.get(endpoint, 0) or 0) + 1
            _save("usage_counters.json", usage)

    started = time.time()
    endpoint = "update_vpc_subnet"
    request_obj = {"vpc_id": vpc_id, "subnet_id": subnet_id, "label": label, "spec": spec}

    ok, early, credential_id, logs, usage = _log_and_enforce(endpoint, request_obj)
    if not ok:
        return early

    def _return(payload, status_code="OK"):
        _finalize_log(logs, usage, credential_id, endpoint, request_obj, status_code, started)
        return payload

