        return _return(_err("VALIDATION_ERROR", "subnet_id is malformed."), "VALIDATION_ERROR")

    if label is None and spec is None:
        return _return(_err("VALIDATION_ERROR", "At least one of label or spec must be provided."), "VALIDATION_ERROR")
    if label is not None:
        if not isinstance(label, str) or len(label.strip()) < 1:
            return _return(_err("VALIDATION_ERROR", "label must be a non-empty string."), "VALIDATION_ERROR")
    if spec is not None and not isinstance(spec, dict):
        return _return(_err("VALIDATION_ERROR", "spec must be an object."), "VALIDATION_ERROR")

