    if subnet.get("status") in ("deleting", "deleted"):
        return _return(_err("CONFLICT", "Subnet cannot be updated in its current state.", status=subnet.get("status")), "CONFLICT")

    # Enforce only one running operation per resource
    for op in ops:
        if not isinstance(op, dict):
            continue
        if op.get("resource_collection") == "network_security" and op.get("resource_id") == subnet_id and op.get("status") == "running":
            return _return(_err("CONFLICT", "Another operation is currently running for this subnet.", operation_id=op.get("id")), "CONFLICT")

    # Proposed changes
    new_label = subnet.get("label")
    if label is not None:
        new_label = label.strip()

    new_spec = subnet.get("spec") if isinstance(subnet.get("spec"), dict) else {}
    if spec is not None:
        new_spec = spec

    # Validate CIDR if spec contains it (or if overwriting spec)
    if spec is not None:
        cidr = new_spec.get("cidr")
        if not isinstance(cidr, str):
            return _return(_err("VALIDATION_ERROR", "spec.cidr is required and must be a string."), "VALIDATION_ERROR")
        try:
            new_net = ipaddress.ip_network(cidr, strict=True)
            if new_net.version != 4:
                return _return(_err("VALIDATION_ERROR", "spec.cidr must be an IPv4 RFC4632 CIDR."), "VALIDATION_ERROR")
        except Exception:
            return _return(_err("VALIDATION_ERROR", "spec.cidr is not a valid CIDR."), "VALIDATION_ERROR")
    else:
        # use existing subnet cidr for overlap checks
        cidr = (new_spec or {}).get("cidr")
        new_net = None
        if isinstance(cidr, str):
            try:
                new_net = ipaddress.ip_network(cidr, strict=True)
            except Exception:
                new_net = None

    # Uniqueness: label within VPC (case-insensitive), excluding self
    for r in ns:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "vpc_subnet" or r.get("parent_id") != vpc_id:
            continue
        if r.get("deleted_at") is not None:
            continue
        if r.get("id") == subnet_id:
            continue
        if isinstance(r.get("label"), str) and r.get("label").strip().lower() == (new_label or "").strip().lower():
            return _return(_err("CONFLICT", "A subnet with this label already exists in the VPC."), "CONFLICT")

    # Non-overlap: check if cidr is available
    if new_net is not None:
        for r in ns:
            if not isinstance(r, dict):
                continue
            if r.get("resource_type") != "vpc_subnet" or r.get("parent_id") != vpc_id:
                continue
            if r.get("deleted_at") is not None:
                continue
            if r.get("id") == subnet_id:
                continue
            existing_cidr = (r.get("spec") or {}).get("cidr")
            if not isinstance(existing_cidr, str):
                continue
            try:
                existing_net = ipaddress.ip_network(existing_cidr, strict=True)
            except Exception:
                continue
            if new_net.overlaps(existing_net):
                return _return(_err("CONFLICT", "Subnet CIDR overlaps with an existing subnet in this VPC.", conflicting_subnet_id=r.get("id")), "CONFLICT")

    # Create operation and apply update (atomic replacement)
    now = _now()
    op_id = _gen_id("op")
    op = {
        "id": op_id,
        "resource_collection": "network_security",
        "resource_id": subnet_id,
        "operation_type": "update",
        "status": "running",
        "request": {"vpc_id": vpc_id, "subnet_id": subnet_id, "label": (label.strip() if isinstance(label, str) else None), "spec": spec},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op)

    # Update subnet fields
    subnet["label"] = new_label
    subnet["spec"] = new_spec
    subnet["updated_at"] = now
    subnet["last_operation_id"] = op_id
    # lifecycle: set to updating during operation, then active
    if subnet.get("status") == "active":
        subnet["status"] = "updating"
