    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_object_storage_bucket"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status, error=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": None,
            "error": error
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(label, str) or not label.strip():
        _log(400, {"code": "VALIDATION_ERROR", "message": "label must be a non-empty string"})
        return _err("VALIDATION_ERROR", "label must be a non-empty string")
    if not isinstance(region_id, str) or not re.match(r"^(cat_01H8[0-9A-Z]{15,}|[a-z0-9-]+)$", region_id):
        _log(400, {"code": "VALIDATION_ERROR", "message": "region_id is invalid"})
        return _err("VALIDATION_ERROR", "region_id is invalid")
    if spec is not None and not isinstance(spec, dict):
        _log(400, {"code": "VALIDATION_ERROR", "message": "spec must be an object"})
        return _err("VALIDATION_ERROR", "spec must be an object")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log(400, {"code": "VALIDATION_ERROR", "message": "tags must be an array of strings"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings")

    catalog = _load("infra_catalog.json")
    if not isinstance(catalog, list):
        catalog = []

    # Resolve region: allow catalog id or slug in region catalog spec.slug
    resolved_region = None
    for c in catalog:
        if not isinstance(c, dict):
            continue
        if c.get("catalog_type") != "region" or c.get("status") != "active":
            continue
        if c.get("id") == region_id:
            resolved_region = c
            break
        spec_c = c.get("spec") if isinstance(c.get("spec"), dict) else {}
        if spec_c.get("slug") == region_id:
            resolved_region = c
            break

    if not resolved_region:
        _log(404, {"code": "NOT_FOUND", "message": "region_id does not correspond to a supported Object Storage region"})
        return _err("NOT_FOUND", "region_id does not correspond to a supported Object Storage region")

    # Enforce that region supports object storage (best-effort via capabilities in spec)
    reg_spec = resolved_region.get("spec") if isinstance(resolved_region.get("spec"), dict) else {}
    caps = reg_spec.get("capabilities")
    if isinstance(caps, list) and ("object_storage" not in caps and "object-storage" not in caps):
        _log(404, {"code": "NOT_FOUND", "message": "region_id does not support Object Storage"})
        return _err("NOT_FOUND", "region_id does not support Object Storage")

    resources = _load("storage_dns_managed.json")
    if not isinstance(resources, list):
        resources = []

    # Determine bucket_name and uniqueness (spec.bucket_name, region_id) where deleted_at is null
    bucket_spec = dict(spec) if isinstance(spec, dict) else {}
    bucket_name = bucket_spec.get("bucket_name") or label.strip()
    if not isinstance(bucket_name, str) or not bucket_name.strip():
        _log(400, {"code": "VALIDATION_ERROR", "message": "spec.bucket_name must be a non-empty string when provided"})
        return _err("VALIDATION_ERROR", "spec.bucket_name must be a non-empty string when provided")
    bucket_name = bucket_name.strip()
    bucket_spec["bucket_name"] = bucket_name

    # Default access
    if "default_access" not in bucket_spec:
        bucket_spec["default_access"] = "private"
    if "access" not in bucket_spec:
        bucket_spec["access"] = {"acl": bucket_spec.get("default_access")}
    if tags is not None:
        bucket_spec["tags"] = list(tags)

    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "object_bucket":
            continue
        if r.get("deleted_at") is not None or r.get("status") == "deleted":
            continue
        if r.get("region_id") != resolved_region.get("id"):
            continue
        rspec = r.get("spec") if isinstance(r.get("spec"), dict) else {}
        if rspec.get("bucket_name") == bucket_name:
            _log(409, {"code": "CONFLICT", "message": "A bucket with the same name already exists in this region"})
            return _err("CONFLICT", "A bucket with the same name already exists in this region")

    # Create operation
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []

    def _new_id(prefix):
        return f"{prefix}_01H8{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}{datetime.datetime.utcnow().strftime('%f')}"[:(len(prefix)+1+4+15+10)]  # ensure long-ish, stable prefix

    bucket_id = _new_id("objbkt")
    op_id = _new_id("op")

    # Create bucket resource (provisioning -> active immediately for offline sim)
    bucket_row = {
        "id": bucket_id,
        "resource_type": "object_bucket",
        "label": label.strip(),
        "region_id": resolved_region.get("id"),
        "status": "active",
        "spec": bucket_spec,
        "attachments": [],
        "parent_id": None,
        "secrets": None,
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }
    resources.append(bucket_row)

    op_now = now
    op_row = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": bucket_id,
        "operation_type": "create",
        "status": "succeeded",
        "request": {
            "resource_type": "object_bucket",
            "label": label.strip(),
            "region_id": resolved_region.get("id"),
            "spec": bucket_spec,
        },
        "result": {"id": bucket_id, "status": "active"},
        "error_message": None,
        "created_at": op_now,
        "updated_at": op_now,
        "started_at": op_now,
        "finished_at": op_now
    }
    ops.append(op_row)

    _save("storage_dns_managed.json", resources)
    _save("operations.json", ops)

    _log(201)
    return {"bucket": bucket_row, "operation": op_row}

def delete_object_storage_bucket(bucket_id, force=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
