    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_object_storage_bucket"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status, error=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": None,
            "error": error
        })
        _save("request_logs.json", logs)

    if force is None:
        force = False

    # Validate
    if not isinstance(bucket_id, str):
        _log(400, {"code": "VALIDATION_ERROR", "message": "bucket_id must be a string"})
        return _err("VALIDATION_ERROR", "bucket_id must be a string")
    if not re.match(r"^objbkt_01H8[0-9A-Z]{15,}$", bucket_id):
        _log(400, {"code": "VALIDATION_ERROR", "message": "bucket_id is malformed"})
        return _err("VALIDATION_ERROR", "bucket_id is malformed")
    if not isinstance(force, bool):
        _log(400, {"code": "VALIDATION_ERROR", "message": "force must be a boolean"})
        return _err("VALIDATION_ERROR", "force must be a boolean")

    resources = _load("storage_dns_managed.json")
    if not isinstance(resources, list):
        resources = []
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []

    idx = None
    bucket = None
    for i, r in enumerate(resources):
        if isinstance(r, dict) and r.get("id") == bucket_id and r.get("resource_type") == "object_bucket":
            idx = i
            bucket = r
            break

    if not bucket or bucket.get("deleted_at") is not None or bucket.get("status") == "deleted":
        _log(404, {"code": "NOT_FOUND", "message": "Bucket not found"})
        return _err("NOT_FOUND", "Bucket not found")

    # Non-empty check: model as spec.object_count or spec.objects_count or spec.contents_nonempty flag
    bspec = bucket.get("spec") if isinstance(bucket.get("spec"), dict) else {}
    obj_count = bspec.get("object_count")
    if obj_count is None:
        obj_count = bspec.get("objects_count")
    nonempty = bspec.get("nonempty")
    if nonempty is None:
        nonempty = bspec.get("contents_nonempty")

    is_nonempty = False
    if isinstance(obj_count, int) and obj_count > 0:
        is_nonempty = True
    if isinstance(nonempty, bool) and nonempty:
        is_nonempty = True

    if is_nonempty and not force:
        _log(409, {"code": "CONFLICT", "message": "Bucket is not empty. Use force=true to delete."})
        return _err("CONFLICT", "Bucket is not empty. Use force=true to delete.")

    # Create delete operation and perform soft delete with lifecycle deleting -> deleted
    def _new_id(prefix):
        return f"{prefix}_01H8{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}{datetime.datetime.utcnow().strftime('%f')}"[:(len(prefix)+1+4+15+10)]

    op_id = _new_id("op")

    # Transition to deleting then deleted (audited via single succeeded op)
    bucket["status"] = "deleted"
    bucket["deleted_at"] = now
    bucket["updated_at"] = now
    bucket["last_operation_id"] = op_id
    # If force, clear object indicators
    if force:
        if isinstance(bucket.get("spec"), dict):
            bucket["spec"]["object_count"] = 0
            bucket["spec"]["objects_count"] = 0
            bucket["spec"]["nonempty"] = False
            bucket["spec"]["contents_nonempty"] = False

    # Also soft-delete any child resources (e.g., certificates) that belong to this bucket
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("parent_id") == bucket_id and r.get("deleted_at") is None and r.get("status") != "deleted":
            r["status"] = "deleted"
            r["deleted_at"] = now
            r["updated_at"] = now
            r["last_operation_id"] = op_id

    op_row = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": bucket_id,
        "operation_type": "delete",
        "status": "succeeded",
        "request": {"bucket_id": bucket_id, "force": force},
        "result": {"id": bucket_id, "deleted": True},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now
    }
    ops.append(op_row)

    resources[idx] = bucket
    _save("storage_dns_managed.json", resources)
    _save("operations.json", ops)

    _log(200)
    return {"bucket_id": bucket_id, "deleted": True, "operation": op_row}

