def update_object_storage_bucket_access(bucket_id, access, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_object_storage_bucket_access"
    status = "succeeded"

    try:
        # Validate inputs
        if not isinstance(bucket_id, str) or not re.match(r"^objbkt_01H8[0-9A-Z]{15,}$", bucket_id):
            status = "failed"
            return _err("VALIDATION_ERROR", "Invalid bucket_id.", field="bucket_id")

        if not isinstance(access, dict):
            status = "failed"
            return _err("VALIDATION_ERROR", "Invalid access; expected object.", field="access")

        allowed_keys = {"acl", "cors_enabled", "cors_rules"}
        for k in access.keys():
            if k not in allowed_keys:
                status = "failed"
                return _err("VALIDATION_ERROR", "Invalid access field.", field=f"access.{k}")

        if "acl" in access:
            if access["acl"] not in ("private", "public-read"):
                status = "failed"
                return _err("VALIDATION_ERROR", "Invalid acl.", field="access.acl")

        if "cors_enabled" in access and not isinstance(access["cors_enabled"], bool):
            status = "failed"
            return _err("VALIDATION_ERROR", "Invalid cors_enabled; expected boolean.", field="access.cors_enabled")

        if "cors_rules" in access:
            if not isinstance(access["cors_rules"], list) or any(not isinstance(x, dict) for x in access["cors_rules"]):
                status = "failed"
                return _err("VALIDATION_ERROR", "Invalid cors_rules; expected array of objects.", field="access.cors_rules")

        # cors_rules require cors_enabled true (either in this patch or already enabled)
        store = _load("storage_dns_managed.json")
        bucket = None
        for r in store:
            if r.get("id") == bucket_id and r.get("resource_type") == "object_bucket" and r.get("deleted_at") is None:
                bucket = r
                break
        if not bucket:
            status = "failed"
            return _err("NOT_FOUND", "Bucket not found.", bucket_id=bucket_id)

        spec = bucket.get("spec") if isinstance(bucket.get("spec"), dict) else {}
        current_access = spec.get("access") if isinstance(spec.get("access"), dict) else {}
        current_cors_enabled = current_access.get("cors_enabled", False)
        patch_cors_enabled = access.get("cors_enabled", None)
        effective_cors_enabled = current_cors_enabled if patch_cors_enabled is None else patch_cors_enabled

        if "cors_rules" in access and not effective_cors_enabled:
            status = "failed"
            return _err("VALIDATION_ERROR", "cors_rules provided but cors_enabled is false.", field="access.cors_rules")

        # Apply patch to per-bucket access (not default_access)
        new_access = dict(current_access)
        for k, v in access.items():
            new_access[k] = v

        # If cors_enabled explicitly false, clear cors_rules (provider behavior: rules not applicable)
        if "cors_enabled" in access and access["cors_enabled"] is False:
            new_access.pop("cors_rules", None)

        # Create operation (update)
        ops = _load("operations.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

        # Enforce only one running operation per resource
        for op in ops:
            if op.get("resource_collection") == "storage_dns_managed" and op.get("resource_id") == bucket_id and op.get("status") == "running":
                status = "failed"
                return _err("CONFLICT", "Another operation is currently running for this resource.", resource_id=bucket_id)

        def _new_id(prefix):
            raw = f"{prefix}_{datetime.datetime.utcnow().timestamp()}_{os.getpid()}_{len(ops)}".encode("utf-8")
            return prefix + "_" + base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=").upper()[:20]

        op_id = _new_id("op_01H8")
        op = {
            "id": op_id,
            "resource_collection": "storage_dns_managed",
            "resource_id": bucket_id,
            "operation_type": "update",
            "status": "running",
            "request": {"bucket_id": bucket_id, "access_patch": access, "effective_access": new_access},
            "result": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": None
        }
        ops.append(op)

        # Mutate resource
        bucket["spec"] = dict(spec)
        bucket["spec"]["access"] = new_access
        bucket["status"] = "updating" if bucket.get("status") in ("active", "updating") else bucket.get("status")
        bucket["last_operation_id"] = op_id
        bucket["updated_at"] = now

        # Finish operation successfully
        op["status"] = "succeeded"
        op["updated_at"] = now
        op["finished_at"] = now
        op["result"] = {"updated_fields": list(access.keys())}

        # Return bucket to active if it was active/updating
        if bucket.get("status") == "updating":
            bucket["status"] = "active"

        _save("storage_dns_managed.json", store)
        _save("operations.json", ops)

        return {
            "bucket_id": bucket_id,
            "access": bucket["spec"].get("access", {}),
            "updated_at": bucket.get("updated_at"),
            "operation_id": op_id
        }
    finally:
        # Request log dynamics (best-effort; do not fail call if logging fails)
        try:
            logs = _load("request_log.json")
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", logs)
        except Exception:
            pass

