        spec = bucket.get("spec") if isinstance(bucket.get("spec"), dict) else {}
        objects = spec.get("objects", [])
        if not isinstance(objects, list):
            objects = []

        # Normalize object shape: {key,last_modified,size}
        norm = []
        for o in objects:
            if not isinstance(o, dict):
                continue
            key = o.get("key")
            if not isinstance(key, str):
                continue
            if prefix and not key.startswith(prefix):
                continue
            lm = o.get("last_modified")
            if not isinstance(lm, str):
                lm = bucket.get("updated_at") or bucket.get("created_at")
            size = o.get("size")
            if not isinstance(size, int):
                try:
                    size = int(size)
                except Exception:
                    size = 0
            norm.append({"key": key, "last_modified": lm, "size": size, **{k: v for k, v in o.items() if k not in ("key", "last_modified", "size")}})

        # Apply delimiter grouping (common prefixes)
        common_prefixes = []
        if delimiter:
            seen = set()
            kept = []
            for o in norm:
                k = o["key"]
                start = len(prefix) if prefix else 0
                idx = k.find(delimiter, start)
                if idx != -1:
                    cp = k[:idx + len(delimiter)]
                    if cp not in seen:
                        seen.add(cp)
                        common_prefixes.append(cp)
                    continue
                kept.append(o)
            norm = kept
            common_prefixes.sort(reverse=(order == "desc"))

        # Sort objects
        reverse = (order == "desc")
        if sort == "key":
            norm.sort(key=lambda x: x.get("key", ""), reverse=reverse)
        elif sort == "last_modified":
            norm.sort(key=lambda x: x.get("last_modified", ""), reverse=reverse)
        else:
            norm.sort(key=lambda x: x.get("size", 0), reverse=reverse)

        # Pagination via cursor = {"offset": int}
        offset = 0
        if cursor:
            cobj = _decode_cursor(cursor)
            if not cobj or "offset" not in cobj or not isinstance(cobj["offset"], int) or cobj["offset"] < 0:
                status = "failed"
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            offset = cobj["offset"]

        total = len(norm)
        page = norm[offset:offset + limit]
        next_cursor = None
        if offset + limit < total:
            next_cursor = _encode_cursor({"offset": offset + limit, "sort": sort, "order": order, "prefix": prefix, "delimiter": delimiter})

        return {
            "bucket_id": bucket_id,
            "data": page,
            "common_prefixes": common_prefixes,
            "page": {
                "total": total,
                "limit": limit,
                "offset": offset,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor
            }
        }
    finally:
        try:
            logs = _load("request_log.json")
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", logs)
        except Exception:
            pass

