def upload_object_storage_bucket_certificate(bucket_id, certificate, **_extra):
    import json, os, datetime, re, time, base64, hashlib, ssl

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "upload_object_storage_bucket_certificate"
    status = "succeeded"

    def _pem_has_block(pem, block):
        return isinstance(pem, str) and ("-----BEGIN " + block + "-----") in pem and ("-----END " + block + "-----") in pem

    try:
        if not isinstance(bucket_id, str) or not re.match(r"^objbkt_01H8[0-9A-Z]{15,}$", bucket_id):
            status = "failed"
            return _err("VALIDATION_ERROR", "Invalid bucket_id.", field="bucket_id")

        if not isinstance(certificate, dict):
            status = "failed"
            return _err("VALIDATION_ERROR", "Invalid certificate; expected object.", field="certificate")

        for k in certificate.keys():
            if k not in ("private_key_pem", "certificate_pem", "ca_chain_pem"):
                status = "failed"
                return _err("VALIDATION_ERROR", "Invalid certificate field.", field=f"certificate.{k}")

        pk = certificate.get("private_key_pem")
        cert_pem = certificate.get("certificate_pem")
        ca_pem = certificate.get("ca_chain_pem")

        if not isinstance(pk, str) or not pk.strip():
            status = "failed"
            return _err("VALIDATION_ERROR", "private_key_pem is required.", field="certificate.private_key_pem")
        if not isinstance(cert_pem, str) or not cert_pem.strip():
            status = "failed"
            return _err("VALIDATION_ERROR", "certificate_pem is required.", field="certificate.certificate_pem")
        if ca_pem is not None and (not isinstance(ca_pem, str) or not ca_pem.strip()):
            status = "failed"
            return _err("VALIDATION_ERROR", "Invalid ca_chain_pem.", field="certificate.ca_chain_pem")

        # Basic PEM validation
        if not (_pem_has_block(pk, "PRIVATE KEY") or _pem_has_block(pk, "RSA PRIVATE KEY") or _pem_has_block(pk, "EC PRIVATE KEY")):
            status = "failed"
            return _err("VALIDATION_ERROR", "private_key_pem is not valid PEM.", field="certificate.private_key_pem")
        if not _pem_has_block(cert_pem, "CERTIFICATE"):
            status = "failed"
            return _err("VALIDATION_ERROR", "certificate_pem is not valid PEM.", field="certificate.certificate_pem")
        if ca_pem is not None and not _pem_has_block(ca_pem, "CERTIFICATE"):
            status = "failed"
            return _err("VALIDATION_ERROR", "ca_chain_pem is not valid PEM.", field="certificate.ca_chain_pem")

        # Key/cert mismatch check (best-effort using stdlib ssl; if unsupported, validate structurally only)
        try:
            ctx = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
            # load_cert_chain will validate key/cert match
            # It needs file paths; use temp files.
            import tempfile
            with tempfile.TemporaryDirectory() as td:
                cert_path = os.path.join(td, "cert.pem")
                key_path = os.path.join(td, "key.pem")
                with open(cert_path, "w", encoding="utf-8") as f:
                    f.write(cert_pem)
                    if ca_pem:
                        f.write("\n")
                        f.write(ca_pem)
                with open(key_path, "w", encoding="utf-8") as f:
                    f.write(pk)
                ctx.load_cert_chain(certfile=cert_path, keyfile=key_path)
        except ssl.SSLError:
            status = "failed"
            return _err("VALIDATION_ERROR", "private_key_pem does not match certificate_pem.", field="certificate.private_key_pem")
        except Exception:
            # If environment can't validate, do not hard-fail; keep structural checks only
            pass

        store = _load("storage_dns_managed.json")
        bucket = None
        for r in store:
            if r.get("id") == bucket_id and r.get("resource_type") == "object_bucket" and r.get("deleted_at") is None:
                bucket = r
                break
        if not bucket:
            status = "failed"
            return _err("NOT_FOUND", "Bucket not found.", bucket_id=bucket_id)

        ops = _load("operations.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

        # Enforce only one running operation per resource
        for op in ops:
            if op.get("resource_collection") == "storage_dns_managed" and op.get("resource_id") == bucket_id and op.get("status") == "running":
                status = "failed"
                return _err("CONFLICT", "Another operation is currently running for this resource.", resource_id=bucket_id)

        def _new_id(prefix):
            raw = f"{prefix}_{datetime.datetime.utcnow().timestamp()}_{os.getpid()}_{len(store)}".encode("utf-8")
            return prefix + "_" + base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=").upper()[:20]

        # Find existing cert child if any (non-deleted)
        cert_row = None
        for r in store:
            if r.get("resource_type") == "object_bucket_certificate" and r.get("parent_id") == bucket_id and r.get("deleted_at") is None:
                cert_row = r
                break

        # Create operation (upload_certificate)
        op_id = _new_id("op_01H8")
        op = {
            "id": op_id,
            "resource_collection": "storage_dns_managed",
            "resource_id": bucket_id,
            "operation_type": "upload_certificate",
            "status": "running",
            "request": {
                "bucket_id": bucket_id,
                "certificate": {
                    "certificate_pem_present": True,
                    "private_key_pem_present": True,
                    "ca_chain_pem_present": ca_pem is not None
                }
            },
            "result": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": None
        }
        ops.append(op)

        # Store encrypted material (modeled as encrypted_blob); do not attempt real encryption offline.
        encrypted_blob = base64.b64encode(json.dumps({
            "private_key_pem": pk,
            "certificate_pem": cert_pem,
            "ca_chain_pem": ca_pem
        }, ensure_ascii=False).encode("utf-8")).decode("ascii")

        # Minimal fingerprint (sha256 of leaf cert PEM bytes)
        fingerprint = hashlib.sha256(cert_pem.encode("utf-8")).hexdigest()

        spec_bucket = bucket.get("spec") if isinstance(bucket.get("spec"), dict) else {}
        bucket["spec"] = dict(spec_bucket)

        if cert_row is None:
            cert_id = _new_id("objcrt_01H8")
            cert_row = {
                "id": cert_id,
                "resource_type": "object_bucket_certificate",
                "label": None,
                "region_id": bucket.get("region_id"),
                "status": "active",
                "spec": {
                    "fingerprint": fingerprint
                },
                "attachments": [],
                "parent_id": bucket_id,
                "secrets": {
                    "encrypted_blob": encrypted_blob,
                    "key_id": "local-dev",
                    "rotated_at": now
                },
                "last_operation_id": op_id,
                "created_at": now,
                "updated_at": now,
                "deleted_at": None
            }
            store.append(cert_row)
        else:
            cert_row["secrets"] = {
                "encrypted_blob": encrypted_blob,
                "key_id": "local-dev",
                "rotated_at": now
            }
            cert_row["spec"] = dict(cert_row.get("spec") or {})
            cert_row["spec"]["fingerprint"] = fingerprint
            cert_row["updated_at"] = now
            cert_row["last_operation_id"] = op_id
            # ensure active
            cert_row["status"] = "active" if cert_row.get("status") in ("active", "updating") else cert_row.get("status")

        # Apply reference on bucket
        bucket["spec"]["certificate_ref"] = cert_row["id"]
        bucket["status"] = "updating" if bucket.get("status") in ("active", "updating") else bucket.get("status")
        bucket["updated_at"] = now
        bucket["last_operation_id"] = op_id
        if bucket.get("status") == "updating":
            bucket["status"] = "active"

        # Finish op
        op["status"] = "succeeded"
        op["updated_at"] = now
        op["finished_at"] = now
        op["result"] = {"certificate_id": cert_row["id"], "fingerprint": fingerprint}

        _save("storage_dns_managed.json", store)
        _save("operations.json", ops)

        return {
            "bucket_id": bucket_id,
            "certificate": {
                "certificate_id": cert_row["id"],
                "status": cert_row.get("status"),
                "created_at": cert_row.get("created_at"),
                "updated_at": cert_row.get("updated_at"),
                "fingerprint": cert_row.get("spec", {}).get("fingerprint"),
                "has_private_key": True
            },
            "operation_id": op_id
        }
    finally:
        try:
            logs = _load("request_log.json")
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", logs)
        except Exception:
            pass

def delete_object_storage_bucket_certificate(bucket_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    reqlog_name = "request_logs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error=None, meta=None):
        logs = _load(reqlog_name)
        row = {
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": "delete_object_storage_bucket_certificate",
            "ts": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "credential_id": credential_id,
            "error": error,
            "meta": meta or {}
        }
        logs.append(row)
        _save(reqlog_name, logs)

    # Input validation
    if not isinstance(bucket_id, str):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "bucket_id must be a string"})
        return _err("VALIDATION_ERROR", "bucket_id must be a string")
    if not re.match(r"^objbkt_[0-9A-Z]{18,}$", bucket_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "bucket_id is invalid"})
        return _err("VALIDATION_ERROR", "bucket_id is invalid")

    store = _load("storage_dns_managed.json")
    ops = _load("operations.json")

    # Find bucket
    bucket = None
    for r in store:
        if r.get("id") == bucket_id and r.get("resource_type") == "object_bucket":
            bucket = r
            break
    if not bucket or bucket.get("deleted_at") is not None:
        _log("error", error={"code": "NOT_FOUND", "message": "Bucket not found"})
        return _err("NOT_FOUND", "Bucket not found")

    # Must have a configured certificate
    spec = bucket.get("spec") if isinstance(bucket.get("spec"), dict) else {}
    cert_ref = spec.get("certificate_ref")
    if not cert_ref or not isinstance(cert_ref, str):
        _log("error", error={"code": "NOT_FOUND", "message": "No certificate configured for this bucket"})
        return _err("NOT_FOUND", "No certificate configured for this bucket")

    # Bucket state must allow update
    if bucket.get("status") not in ("active", "updating"):
        _log("error", error={"code": "CONFLICT", "message": "Bucket is not in a state that allows certificate removal"})
        return _err("CONFLICT", "Bucket is not in a state that allows certificate removal", current_status=bucket.get("status"))

    # Find certificate resource
    cert = None
    for r in store:
        if r.get("id") == cert_ref and r.get("resource_type") == "object_bucket_certificate":
            cert = r
            break
    if not cert or cert.get("deleted_at") is not None or cert.get("parent_id") != bucket_id:
        _log("error", error={"code": "NOT_FOUND", "message": "Configured certificate not found"})
        return _err("NOT_FOUND", "Configured certificate not found")

    # Create operation for delete_certificate
    now = _now()
    op_id = f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}"
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": cert.get("id"),
        "operation_type": "delete_certificate",
        "status": "running",
        "request": {"bucket_id": bucket_id, "certificate_id": cert.get("id")},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }

    # Enforce "only one running operation per resource"
    for existing in ops:
        if existing.get("resource_collection") == "storage_dns_managed" and existing.get("resource_id") == cert.get("id") and existing.get("status") == "running":
            _log("error", error={"code": "CONFLICT", "message": "Another operation is already running for this certificate"})
            return _err("CONFLICT", "Another operation is already running for this certificate")

    # Apply mutations: soft-delete certificate resource + clear bucket certificate_ref
    cert_prev_status = cert.get("status")
    if cert_prev_status not in ("active", "updating", "error"):
        _log("error", error={"code": "CONFLICT", "message": "Certificate is not in a state that allows deletion"})
        return _err("CONFLICT", "Certificate is not in a state that allows deletion", current_status=cert_prev_status)

    cert["last_operation_id"] = op_id
    cert["updated_at"] = now
    # lifecycle: active/updating/error -> deleting -> deleted
    cert["status"] = "deleting"
    cert["deleted_at"] = now
    # Immediately mark deleted to model backend completion (still audited via operation)
    cert["status"] = "deleted"
    cert["updated_at"] = now

    spec = dict(spec)
    if spec.get("certificate_ref") == cert.get("id"):
        spec["certificate_ref"] = None
    bucket["spec"] = spec
    bucket["updated_at"] = now
    bucket["last_operation_id"] = op_id
    # keep bucket status as updating briefly then active; enforce transition
    if bucket.get("status") == "active":
        bucket["status"] = "updating"
        bucket["updated_at"] = now
        bucket["status"] = "active"
        bucket["updated_at"] = now

    op["status"] = "succeeded"
    op["updated_at"] = now
    op["finished_at"] = now
    op["result"] = {"bucket_id": bucket_id, "certificate_id": cert.get("id"), "bucket_certificate_ref_cleared": True}
    ops.append(op)

    _save("storage_dns_managed.json", store)
    _save("operations.json", ops)

    resp = {
        "bucket_id": bucket_id,
        "certificate_deleted": True,
        "certificate_id": cert.get("id"),
        "operation_id": op_id
    }
    _log("ok", meta={"operation_id": op_id})
    return resp

