        _log("error", error={"code": "VALIDATION_ERROR", "message": "cursor must be a string"})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    if resource_id is not None:
        if not isinstance(resource_id, str) or not re.match(r"^objkey_[0-9A-Z]{18,}$", resource_id):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "resource_id is invalid"})
            return _err("VALIDATION_ERROR", "resource_id is invalid")

    if label is not None and not isinstance(label, str):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "label must be a string"})
        return _err("VALIDATION_ERROR", "label must be a string")

    valid_status = {"provisioning","active","updating","suspending","suspended","resizing","deleting","deleted","error"}
    if status is not None:
        if not isinstance(status, str) or status not in valid_status:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "status is invalid"})
            return _err("VALIDATION_ERROR", "status is invalid")

    valid_sort_by = {"created_at","updated_at","label","status"}
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in valid_sort_by:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "sort_by is invalid"})
        return _err("VALIDATION_ERROR", "sort_by is invalid")

    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in {"asc","desc"}:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "sort_order is invalid"})
        return _err("VALIDATION_ERROR", "sort_order is invalid")

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "cursor is invalid"})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    store = _load("storage_dns_managed.json")
    rows = []
    for r in store:
        if r.get("resource_type") != "object_key":
            continue
        if r.get("deleted_at") is not None:
            continue
        if resource_id is not None and r.get("id") != resource_id:
            continue
        if label is not None:
            rl = r.get("label")
            if not isinstance(rl, str) or label.lower() not in rl.lower():
                continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    def _keyval(x):
        v = x.get(sort_by)
        if v is None:
            return ""
        return v

    rows.sort(key=_keyval, reverse=(sort_order == "desc"))

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{start+limit}".encode("utf-8")).decode("utf-8")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log("ok", meta={"returned": len(page), "total": total, "has_more": has_more})
    return resp

