def create_object_storage_key(label, bucket_access=None, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    reqlog_name = "request_logs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        logs = _load(reqlog_name)
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": "create_object_storage_key",
            "ts": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "credential_id": None,
            "error": error,
            "meta": meta or {}
        })
        _save(reqlog_name, logs)

    # Validate inputs
    if not isinstance(label, str) or not label.strip():
        _log("error", error={"code": "VALIDATION_ERROR", "message": "label is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string")

    if bucket_access is not None and not isinstance(bucket_access, list):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "bucket_access must be an array"})
        return _err("VALIDATION_ERROR", "bucket_access must be an array")

    perm_ok = {"read_only", "read_write", "none"}
    access_rules = []
    seen_buckets = set()
    if bucket_access is not None:
        for i, item in enumerate(bucket_access):
            if not isinstance(item, dict):
                _log("error", error={"code": "VALIDATION_ERROR", "message": "bucket_access entries must be objects", "index": i})
                return _err("VALIDATION_ERROR", "bucket_access entries must be objects", index=i)
            bid = item.get("bucket_id")
            perm = item.get("permissions")
            if not isinstance(bid, str) or not re.match(r"^objbkt_[0-9A-Z]{18,}$", bid):
                _log("error", error={"code": "VALIDATION_ERROR", "message": "bucket_id is invalid", "index": i})
                return _err("VALIDATION_ERROR", "bucket_id is invalid", index=i)
            if not isinstance(perm, str) or perm not in perm_ok:
                _log("error", error={"code": "VALIDATION_ERROR", "message": "permissions is invalid", "index": i})
                return _err("VALIDATION_ERROR", "permissions is invalid", index=i)
            if bid in seen_buckets:
                _log("error", error={"code": "VALIDATION_ERROR", "message": "duplicate bucket_id in bucket_access", "bucket_id": bid})
                return _err("VALIDATION_ERROR", "duplicate bucket_id in bucket_access", bucket_id=bid)
            seen_buckets.add(bid)
            access_rules.append({"bucket_id": bid, "permissions": perm})

    store = _load("storage_dns_managed.json")
    ops = _load("operations.json")

    # Validate referenced buckets exist & are accessible (present and not deleted)
    buckets_by_id = {r.get("id"): r for r in store if r.get("resource_type") == "object_bucket" and r.get("deleted_at") is None}
    for rule in access_rules:
        if rule["bucket_id"] not in buckets_by_id:
            _log("error", error={"code": "NOT_FOUND", "message": "Referenced bucket not found", "bucket_id": rule["bucket_id"]})
            return _err("NOT_FOUND", "Referenced bucket not found", bucket_id=rule["bucket_id"])

    # Generate id
    def _gen_suffix(n=20):
        alphabet = string.ascii_uppercase + string.digits
        return "".join(random.choice(alphabet) for _ in range(n))

    existing_ids = {r.get("id") for r in store}
    new_id = None
    for _ in range(1000):
        cand = "objkey_" + _gen_suffix(20)
        if cand not in existing_ids:
            new_id = cand
            break
    if not new_id:
        _log("error", error={"code": "CONFLICT", "message": "Unable to allocate a new key id"})
        return _err("CONFLICT", "Unable to allocate a new key id")

    now = _now()

    # Create operation (create)
    op_id = f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}"
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": new_id,  # for create we store the new id
        "operation_type": "create",
        "status": "running",
        "request": {"label": label.strip(), "bucket_access": access_rules},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }

    # Ensure no running op for the would-be resource id (unlikely but consistent)
    for existing in ops:
        if existing.get("resource_collection") == "storage_dns_managed" and existing.get("resource_id") == new_id and existing.get("status") == "running":
            _log("error", error={"code": "CONFLICT", "message": "Another operation is already running for this resource id"})
            return _err("CONFLICT", "Another operation is already running for this resource id")

    # Construct key resource. Secrets allowed for object_key per schema.
    # Store "encrypted" secret material (opaque blob) since this datastore models encrypted-at-rest.
    secret_blob = "enc_" + _gen_suffix(32)
    key_row = {
        "id": new_id,
        "resource_type": "object_key",
        "label": label.strip(),
        "region_id": None,
        "status": "provisioning",
        "spec": {
            "bucket_access": access_rules
        },
        "attachments": [],
        "parent_id": None,
        "secrets": {
            "encrypted_blob": secret_blob,
            "key_id": f"key_{_gen_suffix(16)}",
            "rotated_at": now
        },
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }

    # Lifecycle provisioning -> active (simulate completion)
    key_row["status"] = "active"
    key_row["updated_at"] = now

    op["status"] = "succeeded"
    op["updated_at"] = now
    op["finished_at"] = now
    op["result"] = {"id": new_id, "status": "active"}

    store.append(key_row)
    ops.append(op)

    _save("storage_dns_managed.json", store)
    _save("operations.json", ops)

    _log("ok", meta={"id": new_id, "operation_id": op_id})
    return {"data": key_row, "operation_id": op_id}

def update_object_storage_key(key_id, label=None, bucket_access=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_object_storage_key"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request logging / quota ---
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # Basic rate limit: 120 requests/min across all calls
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs[-2000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str) and ts >= cutoff:
            recent += 1
    if recent >= 120:
        logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    # Daily quota: 5000
    day = now[:10]
    daily = 0
    for r in logs[-20000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str) and ts[:10] == day:
            daily += 1
    if daily >= 5000:
        logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "QUOTA_EXCEEDED", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # --- validation ---
    if not isinstance(key_id, str) or not re.match(r"^objkey_[0-9A-Z]{18,}$", key_id):
        logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "key_id is malformed", field="key_id")

    if label is not None and not isinstance(label, str):
        logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "label must be a string", field="label")

    allowed_perms = {"read_only", "read_write", "none"}
    rules_by_bucket = None
    if bucket_access is not None:
        if not isinstance(bucket_access, list):
            logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "bucket_access must be an array", field="bucket_access")
        rules_by_bucket = {}
        for i, rule in enumerate(bucket_access):
            if not isinstance(rule, dict):
                logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
                _save("request_logs.json", logs)
                return _err("VALIDATION_ERROR", "Each bucket_access entry must be an object", field=f"bucket_access[{i}]")
            if set(rule.keys()) - {"bucket_id", "permissions"}:
                logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
                _save("request_logs.json", logs)
                return _err("VALIDATION_ERROR", "bucket_access entry has additionalProperties", field=f"bucket_access[{i}]")
            bkid = rule.get("bucket_id")
            perm = rule.get("permissions")
            if not isinstance(bkid, str) or not re.match(r"^objbkt_[0-9A-Z]{18,}$", bkid):
                logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
                _save("request_logs.json", logs)
                return _err("VALIDATION_ERROR", "bucket_id is malformed", field=f"bucket_access[{i}].bucket_id")
            if perm not in allowed_perms:
                logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
                _save("request_logs.json", logs)
                return _err("VALIDATION_ERROR", "permissions is invalid", field=f"bucket_access[{i}].permissions", allowed=list(allowed_perms))
            if bkid in rules_by_bucket:
                logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
                _save("request_logs.json", logs)
                return _err("VALIDATION_ERROR", "Duplicate bucket_access rules for the same bucket_id", field="bucket_access", bucket_id=bkid)
            rules_by_bucket[bkid] = perm

    # --- load resources ---
    store = _load("storage_dns_managed.json")
    if not isinstance(store, list):
        store = []

    key = None
    for r in store:
        if r.get("id") == key_id and r.get("resource_type") == "object_key" and r.get("deleted_at") is None:
            key = r
            break
    if not key:
        logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Object Storage key not found", key_id=key_id)

    # validate referenced buckets exist and are active/not deleted
    if rules_by_bucket is not None:
        bucket_ids = list(rules_by_bucket.keys())
        buckets = {}
        for r in store:
            if r.get("resource_type") == "object_bucket" and r.get("deleted_at") is None:
                rid = r.get("id")
                if rid in rules_by_bucket:
                    buckets[rid] = r
        missing = [bid for bid in bucket_ids if bid not in buckets]
        if missing:
            logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
            _save("request_logs.json", logs)
            return _err("NOT_FOUND", "One or more referenced buckets were not found", bucket_ids=missing)

    # --- apply update ---
    changed = False
    if label is not None and label != key.get("label"):
        key["label"] = label
        changed = True

    if rules_by_bucket is not None:
        spec = key.get("spec")
        if not isinstance(spec, dict):
            spec = {}
        spec["bucket_access"] = [{"bucket_id": bid, "permissions": rules_by_bucket[bid]} for bid in sorted(rules_by_bucket.keys())]
        key["spec"] = spec
        changed = True

    if not changed:
        # Idempotent: return current state (still counts as success)
        pass

    key["updated_at"] = now

    _save("storage_dns_managed.json", store)

    # --- compute effective permissions ---
    default_perm = None
    # account-level defaults stored on a settings row; if absent, fall back to read_only
    for r in store:
        if r.get("resource_type") == "object_storage_settings" and r.get("deleted_at") is None:
            sp = r.get("spec") if isinstance(r.get("spec"), dict) else {}
            dp = sp.get("default_permissions")
            if dp in allowed_perms:
                default_perm = dp
            break
    if default_perm is None:
        default_perm = "read_only"

    effective = {}
    if rules_by_bucket is not None:
        for bid, perm in rules_by_bucket.items():
            effective[bid] = perm

    result = {
        "id": key.get("id"),
        "resource_type": key.get("resource_type"),
        "label": key.get("label"),
        "status": key.get("status"),
        "spec": key.get("spec") if isinstance(key.get("spec"), dict) else {},
        "created_at": key.get("created_at"),
        "updated_at": key.get("updated_at"),
        "effective_permissions": {
            "default_permissions": default_perm,
            "per_bucket": effective
        }
    }

    logs.append({"id": f"req_{len(logs)+1}", "timestamp": now, "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time()-t0)*1000), "credential_id": None})
    _save("request_logs.json", logs)
    return result

