            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_object_storage"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None, operation_id=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(bucket_id, str) or not bucket_id:
        e = _err("VALIDATION_ERROR", "bucket_id must be a string", field="bucket_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    store = _load("storage_dns_managed.json")
    if not isinstance(store, list):
        store = []
    bucket = None
    for r in store:
        if isinstance(r, dict) and r.get("id") == bucket_id and r.get("deleted_at") is None:
            bucket = r
            break
    if not bucket or bucket.get("resource_type") != "object_bucket":
        e = _err("NOT_FOUND", "Bucket not found", field="bucket_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if bucket.get("status") in ("deleting", "deleted"):
        e = _err("CONFLICT", "Bucket is already deleting/deleted")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    transitions = {
        "provisioning": ["active", "error"],
        "active": ["updating", "suspending", "resizing", "deleting", "error"],
        "updating": ["active", "error"],
        "suspending": ["suspended", "error"],
        "suspended": ["updating", "deleting", "error"],
        "resizing": ["active", "error"],
        "deleting": ["deleted", "error"],
        "error": ["updating", "deleting"],
        "deleted": [],
    }
    cur = bucket.get("status")
    if "deleting" not in transitions.get(cur, []):
        e = _err("INVALID_TRANSITION", f"Cannot transition bucket from '{cur}' to 'deleting'")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    operations = _load("operations.json")
    if not isinstance(operations, list):
        operations = []

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    op_id = _new_id("op")
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": bucket_id,
        "operation_type": "delete",
        "status": "running",
        "request": {"bucket_id": bucket_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    operations.append(op)

    bucket["status"] = "deleting"
    bucket["updated_at"] = now
    bucket["last_operation_id"] = op_id
    bucket["deleted_at"] = now  # soft-delete begins at cancel time per business rule

    _save("operations.json", operations)
    _save("storage_dns_managed.json", store)

    _log("ok", resource={"collection": "storage_dns_managed", "id": bucket_id}, operation_id=op_id)
    return {"bucket": bucket, "operation": op}

