        rid = f"req_{int(time.time()*1000)}_{os.getpid()}_{abs(hash((now, 'create_domain', status)))%10**8}"
        logs.append({
            "id": rid,
            "ts": now,
            "endpoint": "create_domain",
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "operation_id": operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit_per_minute")
        if rl is None and isinstance(limits.get("limits"), dict):
            rl = limits["limits"].get("rate_limit_per_minute")
        logs = _ensure_logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rl_i, window_seconds=60)
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", limit_err["error"]["code"], limit_err["error"]["message"])
        return limit_err

    if not isinstance(label, str) or not label.strip():
        e = _err("VALIDATION_ERROR", "label is required and must be a non-empty string", field="label")
        _log("error", e["error"]["code"], e["error"]["message"])
