    # region_id pattern permits slug; accept either active catalog region id OR any slug string (do not reject slugs)
    infra = _load("infra_catalog.json")
    if not isinstance(infra, list):
        infra = []
    is_cat = region_id.startswith("cat_")
    if is_cat:
        reg = None
        for r in infra:
            if r.get("id") == region_id and r.get("catalog_type") == "region":
                reg = r
                break
        if not reg or reg.get("status") != "active":
            e = _err("VALIDATION_ERROR", "region_id must reference an active region catalog item", field="region_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    rows = _load("storage_dns_managed.json")
    if not isinstance(rows, list):
        rows = []

    # unique(spec.domain_name) where deleted_at null (we use label as domain_name by default)
    domain_name = label.strip()
    for r in rows:
        if r.get("resource_type") == "domain" and r.get("deleted_at") is None:
            dn = (r.get("spec") or {}).get("domain_name") or r.get("label")
            if dn == domain_name:
                e = _err("CONFLICT", "Domain already exists", field="label", rule="unique(spec.domain_name) WHERE deleted_at IS NULL")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    dom_id = f"dom_{now_dt.strftime('%y%m%d%H%M%S')}{abs(hash((domain_name, time.time_ns())))%10**10:010d}"
    existing_ids = {r.get("id") for r in rows if isinstance(r, dict)}
    while dom_id in existing_ids:
        dom_id = f"dom_{now_dt.strftime('%y%m%d%H%M%S')}{abs(hash((domain_name, time.time_ns(), dom_id)))%10**10:010d}"

    dom_row = {
        "id": dom_id,
        "resource_type": "domain",
        "label": domain_name,
        "region_id": region_id if is_cat else None,
        "status": "provisioning",
        "spec": dict(spec) if isinstance(spec, dict) else {},
        "attachments": [],
        "parent_id": None,
        "secrets": None,
        "last_operation_id": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    # store the domain_name in spec as required by constraint
    if "domain_name" not in dom_row["spec"]:
        dom_row["spec"]["domain_name"] = domain_name
    if tags is not None:
        dom_row["spec"]["tags"] = tags

    rows.append(dom_row)

    # Provision completes quickly
    dom_row["status"] = "active"
    dom_row["updated_at"] = now

    _save("storage_dns_managed.json", rows)
    out = {"domain": dom_row}
    _log("success", resource={"collection": "storage_dns_managed", "id": dom_id})
    return out

def update_domain(domain_id, label=None, tags=None, spec=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- auth / rate limit (ambient) + request log if present
    # This datastore schema doesn't declare an audit/log collection; do not fabricate one.

    if not isinstance(domain_id, str) or not re.match(r"^dom_01H8[0-9A-Z]{15,}$", domain_id):
        return _err("VALIDATION_ERROR", "domain_id is malformed.", field="domain_id")

    if label is None and tags is None and spec is None:
        return _err("VALIDATION_ERROR", "At least one of label, tags, or spec must be provided.")

    if label is not None and not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label must be a string.", field="label")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")
    if spec is not None and not isinstance(spec, dict):
        return _err("VALIDATION_ERROR", "spec must be an object.", field="spec")

    resources = _load("storage_dns_managed.json")
    domain = None
    for r in resources:
        if r.get("id") == domain_id and r.get("resource_type") == "domain":
            domain = r
            break
    if domain is None:
        return _err("NOT_FOUND", "Domain not found.", domain_id=domain_id)

    # Reads typically exclude deleted, but update should not allow modifying deleted resources.
    if domain.get("deleted_at") is not None or domain.get("status") in ("deleting", "deleted"):
        return _err("CONFLICT", "Domain cannot be updated in its current state.", status=domain.get("status"))

    # Uniqueness: domain spec.domain_name unique WHERE deleted_at IS NULL
    # The tool says "duplicate another domain’s label", but schema defines uniqueness on spec.domain_name.
    # Enforce schema constraint: if spec.domain_name is being changed, it must remain unique.
    new_spec = domain.get("spec") if isinstance(domain.get("spec"), dict) else {}
    if spec is not None:
        # merge/replace semantics: treat as provider-specific payload; update merges keys
        merged = dict(new_spec)
        merged.update(spec)
        new_spec = merged

    # Validate uniqueness if domain_name present
    new_domain_name = None
    if isinstance(new_spec, dict):
        new_domain_name = new_spec.get("domain_name")
    if new_domain_name is not None:
        if not isinstance(new_domain_name, str) or not new_domain_name.strip():
            return _err("VALIDATION_ERROR", "spec.domain_name must be a non-empty string when provided.", field="spec.domain_name")
        for r in resources:
            if r.get("resource_type") == "domain" and r.get("deleted_at") is None and r.get("id") != domain_id:
                rs = r.get("spec") or {}
                if isinstance(rs, dict) and rs.get("domain_name") == new_domain_name:
                    return _err("CONFLICT", "A domain with the same name already exists.", field="spec.domain_name")

    changed = {}
    if label is not None:
        domain["label"] = label
        changed["label"] = label
    if tags is not None:
        domain["spec"] = domain.get("spec") if isinstance(domain.get("spec"), dict) else {}
        # tags are not a top-level field in schema for domains; store in spec.tags if present,
        # but keep a stable behavior by also storing in spec["tags"].
        # (No top-level 'tags' exists in storage_dns_managed.)
        domain["spec"]["tags"] = list(tags)
        changed["tags"] = list(tags)
    if spec is not None:
        domain["spec"] = new_spec
        changed["spec"] = spec

    domain["updated_at"] = now

    # Create an operation for update
    ops = _load("operations.json")
    def _new_id(prefix):
        # deterministic-ish monotonic id
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        base = f"{prefix}_{ts}"
        # ensure unique
        existing = {o.get("id") for o in ops}
        if base not in existing:
            return base
        i = 2
        while f"{base}_{i}" in existing:
            i += 1
        return f"{base}_{i}"

    op_id = _new_id("op")
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": domain_id,
        "operation_type": "update",
        "status": "succeeded",
        "request": {
            "domain_id": domain_id,
            "label": label,
            "tags": tags,
            "spec": spec,
        },
        "result": {"changed": changed},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }

    # Enforce "Only one running operation per resource" constraint (satisfied since we mark succeeded)
    domain["last_operation_id"] = op_id

    ops.append(op)
    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    return {
        "domain": domain,
        "operation": op,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def delete_domain(domain_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(domain_id, str) or not re.match(r"^dom_01H8[0-9A-Z]{15,}$", domain_id):
        return _err("VALIDATION_ERROR", "domain_id is malformed.", field="domain_id")

    resources = _load("storage_dns_managed.json")
    domain = None
    for r in resources:
        if r.get("id") == domain_id and r.get("resource_type") == "domain":
            domain = r
            break
    if domain is None:
        return _err("NOT_FOUND", "Domain not found.", domain_id=domain_id)

    # Already deleted/deleting -> conflict
    if domain.get("deleted_at") is not None or domain.get("status") in ("deleting", "deleted"):
        return _err("CONFLICT", "Domain is already deleted or in the process of deleting.", status=domain.get("status"))

    # Transition status to deleting -> deleted via an operation
    # Validate lifecycle transitions for storage_dns_managed
    allowed = {
        "provisioning": ["active", "error"],
        "active": ["updating", "suspending", "resizing", "deleting", "error"],
        "updating": ["active", "error"],
        "suspending": ["suspended", "error"],
        "suspended": ["updating", "deleting", "error"],
        "resizing": ["active", "error"],
        "deleting": ["deleted", "error"],
        "error": ["updating", "deleting"],
        "deleted": [],
    }
    cur = domain.get("status")
    if cur not in allowed or "deleting" not in allowed.get(cur, []):
        return _err("INVALID_TRANSITION", "Domain cannot be deleted from its current state.", from_status=cur, to_status="deleting")

    ops = _load("operations.json")
    def _new_id(prefix):
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        base = f"{prefix}_{ts}"
        existing = {o.get("id") for o in ops}
        if base not in existing:
            return base
        i = 2
        while f"{base}_{i}" in existing:
            i += 1
        return f"{base}_{i}"

    op_id = _new_id("op")
    # mark deleting
    domain["status"] = "deleting"
    domain["updated_at"] = now
    domain["last_operation_id"] = op_id

    # Cascade soft-delete to domain_record children (business rule implicit in parent/child relationship)
    for r in resources:
        if r.get("resource_type") == "domain_record" and r.get("parent_id") == domain_id and r.get("deleted_at") is None:
            # Transition to deleting then deleted if possible
            rcur = r.get("status")
            if rcur in allowed and "deleting" in allowed.get(rcur, []):
                r["status"] = "deleting"
                r["updated_at"] = now
                r["last_operation_id"] = op_id
                r["status"] = "deleted"
                r["deleted_at"] = now
                r["updated_at"] = now
            else:
                # If record is in an undeletable state, block deletion (prevents partial success)
                return _err("CONFLICT", "A domain record prevents domain deletion due to its current state.", record_id=r.get("id"), record_status=rcur)

    # complete delete synchronously: deleting -> deleted
    domain["status"] = "deleted"
    domain["deleted_at"] = now
    domain["updated_at"] = now

    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": domain_id,
        "operation_type": "delete",
        "status": "succeeded",
        "request": {"domain_id": domain_id},
        "result": {"deleted_at": now},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    ops.append(op)

    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    return {
        "domain_id": domain_id,
        "status": "deleted",
        "deleted_at": now,
        "operation": op,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_domain_records(domain_id, page=None, page_size=None, sort_by=None, sort_order=None, status=None, label=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(domain_id, str) or not re.match(r"^dom_01H8[0-9A-Z]{15,}$", domain_id):
        return _err("VALIDATION_ERROR", "domain_id is malformed.", field="domain_id")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 100
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", field="page_size")

    allowed_sort_by = {"created_at", "updated_at", "label", "status"}
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in allowed_sort_by:
        return _err("VALIDATION_ERROR", "sort_by is invalid.", field="sort_by", allowed=sorted(allowed_sort_by))
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.", field="sort_order")

    allowed_status = {"provisioning","active","updating","suspending","suspended","resizing","deleting","deleted","error"}
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "status filter is invalid.", field="status", allowed=sorted(allowed_status))
    if label is not None and not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label filter must be a string.", field="label")

    resources = _load("storage_dns_managed.json")
    domain = None
    for r in resources:
        if r.get("id") == domain_id and r.get("resource_type") == "domain":
            domain = r
            break
    if domain is None:
        return _err("NOT_FOUND", "Domain not found.", domain_id=domain_id)

    # Domain being deleted/deleted still "exists"; listing records should exclude deleted records by default.
    records = []
    for r in resources:
        if r.get("resource_type") == "domain_record" and r.get("parent_id") == domain_id:
            if r.get("deleted_at") is not None:
                continue
            if status is not None and r.get("status") != status:
                continue
            if label is not None:
                rl = r.get("label")
                if not isinstance(rl, str) or label not in rl:
                    continue
            records.append(r)

    def _key(v):
        x = v.get(sort_by)
        if x is None:
            return ""
        return x
    reverse = (sort_order == "desc")
    records.sort(key=_key, reverse=reverse)

    total = len(records)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = records[start:end]
    has_more = end < total

    return {
        "data": page_items,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "latency_ms": int((time.time() - t0) * 1000),
    }

