def create_domain_record(domain_id, type, name, target, ttl_sec=None, priority=None, weight=None, port=None, service=None, protocol=None, tag=None, flags=None, **_extra):
    import json, os, datetime, secrets, time, ipaddress, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_domain_record"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(domain_id, str) or not domain_id:
        e = _err("VALIDATION_ERROR", "domain_id must be a string", field="domain_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(type, str) or not type:
        e = _err("VALIDATION_ERROR", "type must be a string", field="type")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(name, str):
        e = _err("VALIDATION_ERROR", "name must be a string", field="name")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(target, str) or not target:
        e = _err("VALIDATION_ERROR", "target must be a non-empty string", field="target")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if ttl_sec is not None:
        try:
            ttl_i = int(ttl_sec)
        except Exception:
            e = _err("VALIDATION_ERROR", "ttl_sec must be an integer", field="ttl_sec")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if ttl_i < 0:
            e = _err("VALIDATION_ERROR", "ttl_sec must be >= 0", field="ttl_sec")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        ttl_sec = ttl_i
    if port is not None:
        try:
            port_i = int(port)
        except Exception:
            e = _err("VALIDATION_ERROR", "port must be an integer", field="port")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if not (0 <= port_i <= 65535):
            e = _err("VALIDATION_ERROR", "port must be between 0 and 65535", field="port")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        port = port_i
    for fld in ("priority", "weight", "flags"):
        v = locals()[fld]
        if v is not None:
            try:
                locals()[fld] = int(v)
            except Exception:
                e = _err("VALIDATION_ERROR", f"{fld} must be an integer", field=fld)
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    store = _load("storage_dns_managed.json")
    if not isinstance(store, list):
        store = []

    dom = None
    for r in store:
        if isinstance(r, dict) and r.get("id") == domain_id and r.get("deleted_at") is None:
            dom = r
            break
    if not dom or dom.get("resource_type") != "domain":
        e = _err("NOT_FOUND", "Domain not found", field="domain_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    rtype = type.upper().strip()
    # Basic record validations
    def _is_hostname(h):
        if h in ("@", ""):
            return True
        if len(h) > 253:
            return False
        if h.endswith("."):
            h = h[:-1]
        # allow relative labels including wildcard
        lab_re = re.compile(r"^(\*|[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)$")
        return all(lab_re.match(p) for p in h.split("."))

    if not _is_hostname(name):
        e = _err("VALIDATION_ERROR", "name is not a valid relative hostname ('@' allowed)", field="name")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if rtype in ("A", "AAAA"):
        try:
            ip = ipaddress.ip_address(target)
        except Exception:
            e = _err("VALIDATION_ERROR", "target must be an IP address for A/AAAA records", field="target")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if rtype == "A" and ip.version != 4:
            e = _err("VALIDATION_ERROR", "target must be an IPv4 address for A records", field="target")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if rtype == "AAAA" and ip.version != 6:
            e = _err("VALIDATION_ERROR", "target must be an IPv6 address for AAAA records", field="target")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    elif rtype in ("CNAME", "MX", "NS"):
        if not _is_hostname(target):
            e = _err("VALIDATION_ERROR", f"target must be a hostname for {rtype} records", field="target")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if rtype == "MX" and priority is None:
            e = _err("VALIDATION_ERROR", "priority is required for MX records", field="priority")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    elif rtype == "TXT":
        # accept any non-empty string; provider may quote
        pass
    elif rtype == "SRV":
        if priority is None or weight is None or port is None or not isinstance(service, str) or not isinstance(protocol, str):
            e = _err("VALIDATION_ERROR", "SRV requires priority, weight, port, service, and protocol", field="type")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if not service.startswith("_") or not protocol.startswith("_"):
            e = _err("VALIDATION_ERROR", "service and protocol must start with '_'", field="service")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if not _is_hostname(target):
            e = _err("VALIDATION_ERROR", "target must be a hostname for SRV records", field="target")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    elif rtype == "CAA":
        if not isinstance(tag, str) or not tag:
            e = _err("VALIDATION_ERROR", "tag is required for CAA records", field="tag")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if flags is None:
            e = _err("VALIDATION_ERROR", "flags is required for CAA records", field="flags")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    else:
        e = _err("VALIDATION_ERROR", "Unsupported DNS record type", field="type")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # uniqueness: same type+name under same domain
    for r in store:
        if isinstance(r, dict) and r.get("resource_type") == "domain_record" and r.get("deleted_at") is None and r.get("parent_id") == domain_id:
            sp = r.get("spec") or {}
            if sp.get("type") == rtype and sp.get("name") == name:
                e = _err("CONFLICT", "A record with the same type+name already exists in this domain")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    rec_id = _new_id("drec")
    record = {
        "id": rec_id,
        "resource_type": "domain_record",
        "label": None,
        "region_id": None,
        "status": "active",
        "spec": {
            "type": rtype,
            "name": name,
            "target": target,
            "ttl_sec": ttl_sec if ttl_sec is not None else 0,
            "priority": priority,
            "weight": weight,
            "port": port,
            "service": service,
            "protocol": protocol,
            "tag": tag,
            "flags": flags,
        },
        "attachments": [],
        "parent_id": domain_id,
        "secrets": None,
        "last_operation_id": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    store.append(record)
    _save("storage_dns_managed.json", store)

    _log("ok", resource={"collection": "storage_dns_managed", "id": rec_id})
    return {"record": record}

def update_domain_record(record_id, type=None, name=None, target=None, ttl_sec=None, priority=None, weight=None, port=None, service=None, protocol=None, tag=None, flags=None, **_extra):
    import json, os, datetime, time, re, uuid, ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_domain_record"
    status = "failed"
    used_credential = None

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_audit(ok, error_code=None, message=None):
        nonlocal status
        status = "succeeded" if ok else "failed"
        audit = _load("request_log.json")
        audit.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": used_credential,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso_now()
        })
        _save("request_log.json", audit)

    if not isinstance(record_id, str) or not re.match(r"^dnsrec_01H8[0-9A-Z]{15,}$", record_id):
        _append_audit(False, "VALIDATION_ERROR", "record_id is malformed")
        return _err("VALIDATION_ERROR", "record_id is malformed")

    # Must provide at least one updatable field
    provided = {k: v for k, v in {
        "type": type, "name": name, "target": target, "ttl_sec": ttl_sec, "priority": priority,
        "weight": weight, "port": port, "service": service, "protocol": protocol, "tag": tag, "flags": flags
    }.items() if v is not None}
    if len(provided) == 0:
        _append_audit(False, "VALIDATION_ERROR", "No updatable fields provided")
        return _err("VALIDATION_ERROR", "No updatable fields provided")

    if ttl_sec is not None and (not isinstance(ttl_sec, int) or ttl_sec < 0):
        _append_audit(False, "VALIDATION_ERROR", "ttl_sec must be an integer >= 0")
        return _err("VALIDATION_ERROR", "ttl_sec must be an integer >= 0")
    if port is not None and (not isinstance(port, int) or port < 0 or port > 65535):
        _append_audit(False, "VALIDATION_ERROR", "port must be between 0 and 65535")
        return _err("VALIDATION_ERROR", "port must be between 0 and 65535")
    if name is not None and not isinstance(name, str):
        _append_audit(False, "VALIDATION_ERROR", "name must be a string")
        return _err("VALIDATION_ERROR", "name must be a string")
    if target is not None and (not isinstance(target, str) or target == ""):
        _append_audit(False, "VALIDATION_ERROR", "target must be a non-empty string")
        return _err("VALIDATION_ERROR", "target must be a non-empty string")

    resources = _load("storage_dns_managed.json")
    rec = None
    for r in resources:
        if r.get("id") == record_id and r.get("resource_type") == "domain_record":
            rec = r
            break
    if rec is None or rec.get("deleted_at") is not None or rec.get("status") in ("deleting", "deleted"):
        _append_audit(False, "NOT_FOUND", "record_id not found")
        return _err("NOT_FOUND", "record_id does not exist")

    domain_id = rec.get("parent_id")
    domain = None
    for r in resources:
        if r.get("id") == domain_id and r.get("resource_type") == "domain":
            domain = r
            break
    if domain is None or domain.get("deleted_at") is not None or domain.get("status") in ("deleting", "deleted"):
        _append_audit(False, "UNAUTHORIZED", "No access to record's domain")
        return _err("UNAUTHORIZED", "You don’t have access to the record’s domain")

    # Build candidate spec and validate like create
    spec0 = rec.get("spec") or {}
    cand_type = (type.strip().upper() if isinstance(type, str) else (spec0.get("type") or "").upper())
    cand_name = name if name is not None else spec0.get("name", "")
    cand_target = target if target is not None else spec0.get("target", "")
    cand_ttl = ttl_sec if ttl_sec is not None else spec0.get("ttl_sec", 0)

    supported = {"A", "AAAA", "CNAME", "MX", "TXT", "SRV", "NS", "CAA"}
    if cand_type not in supported:
        _append_audit(False, "VALIDATION_ERROR", f"Unsupported record type '{cand_type}'")
        return _err("VALIDATION_ERROR", f"Unsupported record type '{cand_type}'")

    import re as _re
    hostname_re = _re.compile(r"^(?=.{1,253}$)(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*\.?$")
    def _is_hostname(s):
        return isinstance(s, str) and bool(hostname_re.match(s)) and "." in s.strip(".")
    def _valid_rel_name(n):
        if n in ("", "@"):
            return True
        if len(n) > 253:
            return False
        if n.startswith("*."):
            rest = n[2:]
            return all(_re.match(r"^(?!-)[A-Za-z0-9-]{1,63}(?<!-)$", lab) for lab in rest.split(".") if lab)
        return all(_re.match(r"^(?!-)[A-Za-z0-9-]{1,63}(?<!-)$", lab) for lab in n.split(".") if lab)

    if not _valid_rel_name(cand_name):
        _append_audit(False, "VALIDATION_ERROR", "name is not a valid relative hostname (use '@' for apex)")
        return _err("VALIDATION_ERROR", "name is not a valid relative hostname (use '@' for apex)")

    # Type-specific
    if cand_type == "A":
        try:
            ip = ipaddress.ip_address(cand_target)
            if ip.version != 4:
                raise ValueError()
        except Exception:
            _append_audit(False, "VALIDATION_ERROR", "A record target must be a valid IPv4 address")
            return _err("VALIDATION_ERROR", "A record target must be a valid IPv4 address")
        for k in ("priority", "weight", "port", "service", "protocol", "tag", "flags"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "A records do not support priority/weight/port/service/protocol/tag/flags")
                return _err("VALIDATION_ERROR", "A records do not support priority/weight/port/service/protocol/tag/flags")

    elif cand_type == "AAAA":
        try:
            ip = ipaddress.ip_address(cand_target)
            if ip.version != 6:
                raise ValueError()
        except Exception:
            _append_audit(False, "VALIDATION_ERROR", "AAAA record target must be a valid IPv6 address")
            return _err("VALIDATION_ERROR", "AAAA record target must be a valid IPv6 address")
        for k in ("priority", "weight", "port", "service", "protocol", "tag", "flags"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "AAAA records do not support priority/weight/port/service/protocol/tag/flags")
                return _err("VALIDATION_ERROR", "AAAA records do not support priority/weight/port/service/protocol/tag/flags")

    elif cand_type == "CNAME":
        if cand_name in ("", "@"):
            _append_audit(False, "VALIDATION_ERROR", "CNAME record name cannot be apex ('@' or empty)")
            return _err("VALIDATION_ERROR", "CNAME record name cannot be apex ('@' or empty)")
        if not _is_hostname(cand_target):
            _append_audit(False, "VALIDATION_ERROR", "CNAME record target must be a valid hostname")
            return _err("VALIDATION_ERROR", "CNAME record target must be a valid hostname")
        for k in ("priority", "weight", "port", "service", "protocol", "tag", "flags"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "CNAME records do not support priority/weight/port/service/protocol/tag/flags")
                return _err("VALIDATION_ERROR", "CNAME records do not support priority/weight/port/service/protocol/tag/flags")

    elif cand_type == "MX":
        cand_priority = priority if priority is not None else spec0.get("priority")
        if cand_priority is None or not isinstance(cand_priority, int):
            _append_audit(False, "VALIDATION_ERROR", "MX records require integer priority")
            return _err("VALIDATION_ERROR", "MX records require integer priority")
        if not _is_hostname(cand_target):
            _append_audit(False, "VALIDATION_ERROR", "MX record target must be a valid hostname")
            return _err("VALIDATION_ERROR", "MX record target must be a valid hostname")
        for k in ("weight", "port", "service", "protocol", "tag", "flags"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "MX records do not support weight/port/service/protocol/tag/flags")
                return _err("VALIDATION_ERROR", "MX records do not support weight/port/service/protocol/tag/flags")

    elif cand_type == "TXT":
        for k in ("priority", "weight", "port", "service", "protocol", "tag", "flags"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "TXT records do not support priority/weight/port/service/protocol/tag/flags")
                return _err("VALIDATION_ERROR", "TXT records do not support priority/weight/port/service/protocol/tag/flags")

    elif cand_type == "NS":
        if not _is_hostname(cand_target):
            _append_audit(False, "VALIDATION_ERROR", "NS record target must be a valid hostname")
            return _err("VALIDATION_ERROR", "NS record target must be a valid hostname")
        for k in ("priority", "weight", "port", "service", "protocol", "tag", "flags"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "NS records do not support priority/weight/port/service/protocol/tag/flags")
                return _err("VALIDATION_ERROR", "NS records do not support priority/weight/port/service/protocol/tag/flags")

    elif cand_type == "SRV":
        cand_priority = priority if priority is not None else spec0.get("priority")
        cand_weight = weight if weight is not None else spec0.get("weight")
        cand_port = port if port is not None else spec0.get("port")
        cand_service = service if service is not None else spec0.get("service")
        cand_protocol = protocol if protocol is not None else spec0.get("protocol")
        if cand_priority is None or not isinstance(cand_priority, int):
            _append_audit(False, "VALIDATION_ERROR", "SRV records require integer priority")
            return _err("VALIDATION_ERROR", "SRV records require integer priority")
        if cand_weight is None or not isinstance(cand_weight, int) or cand_weight < 0:
            _append_audit(False, "VALIDATION_ERROR", "SRV records require integer weight >= 0")
            return _err("VALIDATION_ERROR", "SRV records require integer weight >= 0")
        if cand_port is None or not isinstance(cand_port, int) or cand_port < 0 or cand_port > 65535:
            _append_audit(False, "VALIDATION_ERROR", "SRV records require port between 0 and 65535")
            return _err("VALIDATION_ERROR", "SRV records require port between 0 and 65535")
        if cand_service is None or not isinstance(cand_service, str) or not cand_service.startswith("_") or len(cand_service) < 2:
            _append_audit(False, "VALIDATION_ERROR", "SRV records require service starting with '_' (e.g., _sip)")
            return _err("VALIDATION_ERROR", "SRV records require service starting with '_' (e.g., _sip)")
        if cand_protocol is None or not isinstance(cand_protocol, str) or cand_protocol not in ("_tcp", "_udp", "_tls"):
            _append_audit(False, "VALIDATION_ERROR", "SRV records require protocol one of _tcp, _udp, _tls")
            return _err("VALIDATION_ERROR", "SRV records require protocol one of _tcp, _udp, _tls")
        if not _is_hostname(cand_target):
            _append_audit(False, "VALIDATION_ERROR", "SRV record target must be a valid hostname")
            return _err("VALIDATION_ERROR", "SRV record target must be a valid hostname")
        for k in ("tag", "flags"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "SRV records do not support tag/flags")
                return _err("VALIDATION_ERROR", "SRV records do not support tag/flags")

    elif cand_type == "CAA":
        cand_tag = tag if tag is not None else spec0.get("tag")
        cand_flags = flags if flags is not None else spec0.get("flags")
        if cand_tag is None or not isinstance(cand_tag, str) or cand_tag.strip() == "":
            _append_audit(False, "VALIDATION_ERROR", "CAA records require tag")
            return _err("VALIDATION_ERROR", "CAA records require tag")
        if cand_flags is None or not isinstance(cand_flags, int) or cand_flags < 0 or cand_flags > 255:
            _append_audit(False, "VALIDATION_ERROR", "CAA records require flags between 0 and 255")
            return _err("VALIDATION_ERROR", "CAA records require flags between 0 and 255")
        for k in ("priority", "weight", "port", "service", "protocol"):
            if k in provided:
                _append_audit(False, "VALIDATION_ERROR", "CAA records do not support priority/weight/port/service/protocol")
                return _err("VALIDATION_ERROR", "CAA records do not support priority/weight/port/service/protocol")

    # Conflict check if changing type or name
    nm_norm = (cand_name if cand_name != "" else "@")
    for r in resources:
        if r.get("resource_type") == "domain_record" and r.get("parent_id") == domain_id and r.get("deleted_at") is None and r.get("id") != record_id:
            s = r.get("spec") or {}
            if (s.get("type") or "").upper() == cand_type and ((s.get("name") if s.get("name") != "" else "@") == nm_norm):
                _append_audit(False, "CONFLICT", "A record with the same type and name already exists")
                return _err("CONFLICT", "A record with the same type and name already exists")

    # Apply updates
    now = _iso_now()
    spec = dict(spec0)
    spec["type"] = cand_type
    spec["name"] = cand_name
    spec["target"] = cand_target
    spec["ttl_sec"] = cand_ttl

    # Clean up type-specific fields, then set if needed
    for k in ("priority", "weight", "port", "service", "protocol", "tag", "flags"):
        if k in spec:
            spec.pop(k, None)

    if cand_type in ("MX", "SRV"):
        spec["priority"] = priority if priority is not None else spec0.get("priority")
    if cand_type == "SRV":
        spec["weight"] = weight if weight is not None else spec0.get("weight")
        spec["port"] = port if port is not None else spec0.get("port")
        spec["service"] = service if service is not None else spec0.get("service")
        spec["protocol"] = protocol if protocol is not None else spec0.get("protocol")
    if cand_type == "CAA":
        spec["tag"] = tag if tag is not None else spec0.get("tag")
        spec["flags"] = flags if flags is not None else spec0.get("flags")

    rec["spec"] = spec
    rec["updated_at"] = now
    domain["updated_at"] = now
    _save("storage_dns_managed.json", resources)

    _append_audit(True)
    return {"record": rec}

def import_domain_zone(domain, remote_nameserver, **_extra):
    import json, os, datetime, time, re, uuid, ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "import_domain_zone"
    status = "failed"
    used_credential = None

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_audit(ok, error_code=None, message=None):
        nonlocal status
        status = "succeeded" if ok else "failed"
        audit = _load("request_log.json")
        audit.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": used_credential,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso_now()
        })
        _save("request_log.json", audit)

    # Validate inputs
    if not isinstance(domain, str) or domain.strip() == "":
        _append_audit(False, "VALIDATION_ERROR", "domain is required")
        return _err("VALIDATION_ERROR", "domain is required")
    if not isinstance(remote_nameserver, str) or remote_nameserver.strip() == "":
        _append_audit(False, "VALIDATION_ERROR", "remote_nameserver is required")
        return _err("VALIDATION_ERROR", "remote_nameserver is required")

    dom = domain.strip().lower().rstrip(".")
    # domain validation (basic)
    dom_re = re.compile(r"^(?=.{1,253}$)(?!-)[a-z0-9-]{1,63}(?<!-)(\.(?!-)[a-z0-9-]{1,63}(?<!-))+?$")
    if not dom_re.match(dom):
        _append_audit(False, "VALIDATION_ERROR", "domain is not a valid domain name")
        return _err("VALIDATION_ERROR", "domain is not a valid domain name")

    ns = remote_nameserver.strip()
    hostname_re = re.compile(r"^(?=.{1,253}$)(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*\.?$")
    ns_is_host = bool(hostname_re.match(ns)) and "." in ns.strip(".")
    ns_is_ip = False
    try:
        ipaddress.ip_address(ns)
        ns_is_ip = True
    except Exception:
        ns_is_ip = False
    if not (ns_is_host or ns_is_ip):
        _append_audit(False, "VALIDATION_ERROR", "remote_nameserver must be a valid hostname or IP")
        return _err("VALIDATION_ERROR", "remote_nameserver must be a valid hostname or IP")

    resources = _load("storage_dns_managed.json")
    ops = _load("operations.json")

    # CONFLICT if domain exists (non-deleted)
    for r in resources:
        if r.get("resource_type") == "domain" and r.get("deleted_at") is None:
            spec = r.get("spec") or {}
            if (spec.get("domain_name") or "").lower().rstrip(".") == dom:
                _append_audit(False, "CONFLICT", "Domain already exists")
                return _err("CONFLICT", "Domain already exists")

    # Simulate "querying nameserver" offline: require pre-seeded zone data in infra_catalog or fail NOT_FOUND.
    # We store importable zones in infra_catalog items with catalog_type='object_storage_cluster' (no better place),
    # under spec.importable_zones[domain]=records. If none, NOT_FOUND.
    catalog = _load("infra_catalog.json")
    zone_data = None
    for item in catalog:
        spec = item.get("spec") or {}
        imp = spec.get("importable_zones")
        if isinstance(imp, dict) and dom in imp:
            z = imp.get(dom)
            # optional per-ns mapping
            if isinstance(z, dict) and "records" in z:
                # if nameserver specified, allow filtering by authoritative list if present
                auth = z.get("authoritative_nameservers")
                if auth is None or (isinstance(auth, list) and any(str(a).lower().rstrip(".") == ns.lower().rstrip(".") for a in auth)):
                    zone_data = z.get("records")
                    break
            elif isinstance(z, list):
                zone_data = z
                break

    if zone_data is None:
        _append_audit(False, "NOT_FOUND", "Remote nameserver cannot provide zone data for domain")
        return _err("NOT_FOUND", "remote nameserver cannot provide zone data for the domain")

    # Validate zone_data records minimal structure
    if not isinstance(zone_data, list):
        _append_audit(False, "VALIDATION_ERROR", "Imported zone data malformed")
        return _err("VALIDATION_ERROR", "Imported zone data malformed")

    now = _iso_now()
    dom_id = "dom_01H8" + uuid.uuid4().hex[:16].upper()
    op_id = "op_" + uuid.uuid4().hex

    domain_row = {
        "id": dom_id,
        "resource_type": "domain",
        "label": dom,
        "region_id": None,
        "status": "active",
        "spec": {
            "domain_name": dom,
            "imported_from": ns,
            "default_ttl_sec": 0
        },
        "attachments": [],
        "parent_id": None,
        "secrets": None,
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }

    created_records = []
    seen = set()
    for rec in zone_data:
        if not isinstance(rec, dict):
            continue
        rtype = str(rec.get("type", "")).upper().strip()
        rname = rec.get("name", "")
        rtarget = rec.get("target", "")
        rttl = rec.get("ttl_sec", 0)
        # minimal validation; skip invalid entries rather than fail the whole import
        if rtype not in {"A", "AAAA", "CNAME", "MX", "TXT", "SRV", "NS", "CAA"}:
            continue
        if not isinstance(rname, str) or not isinstance(rtarget, str) or rtarget == "":
            continue
        if not isinstance(rttl, int) or rttl < 0:
            rttl = 0
        nm_norm = rname if rname != "" else "@"
        key = (rtype, nm_norm)
        if key in seen:
            continue
        seen.add(key)

        rec_id = "dnsrec_01H8" + uuid.uuid4().hex[:16].upper()
        spec = {"domain_id": dom_id, "type": rtype, "name": rname, "target": rtarget, "ttl_sec": rttl}
        # pass through optional SRV/MX/CAA fields if present & basic type checks
        if rtype in ("MX", "SRV") and isinstance(rec.get("priority"), int):
            spec["priority"] = rec.get("priority")
        if rtype == "SRV":
            if isinstance(rec.get("weight"), int):
                spec["weight"] = rec.get("weight")
            if isinstance(rec.get("port"), int) and 0 <= rec.get("port") <= 65535:
                spec["port"] = rec.get("port")
            if isinstance(rec.get("service"), str):
                spec["service"] = rec.get("service")
            if isinstance(rec.get("protocol"), str):
                spec["protocol"] = rec.get("protocol")
        if rtype == "CAA":
            if isinstance(rec.get("tag"), str):
                spec["tag"] = rec.get("tag")
            if isinstance(rec.get("flags"), int):
                spec["flags"] = rec.get("flags")

        row = {
            "id": rec_id,
            "resource_type": "domain_record",
            "label": None,
            "region_id": None,
            "status": "active",
            "spec": spec,
            "attachments": [],
            "parent_id": dom_id,
            "secrets": None,
            "last_operation_id": op_id,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None
        }
        created_records.append(row)

    if len(created_records) == 0:
        _append_audit(False, "NOT_FOUND", "No importable records found from remote nameserver for domain")
        return _err("NOT_FOUND", "remote nameserver cannot provide zone data for the domain")

    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": dom_id,
        "operation_type": "import_zone",
        "status": "succeeded",
        "request": {"domain": dom, "remote_nameserver": ns},
        "result": {"domain_id": dom_id, "imported_record_ids": [r["id"] for r in created_records]},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now
    }
    ops.append(op)

    resources.append(domain_row)
    resources.extend(created_records)
    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    _append_audit(True)
    return {"domain": domain_row, "records": created_records, "operation_id": op_id}

def clone_domain(source_domain_id, new_domain, copy_records=None, **_extra):
    import json, os, datetime, secrets, time, re, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "clone_domain"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, message=None, resource=None):
        logs = _logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{secrets.token_hex(6)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "resource": resource,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _limits():
        lim = _load("service_limits.json")
        return lim if isinstance(lim, dict) else {}

    def _enforce_limits():
        lim = _limits()
        rl = lim.get("rate_limit_per_minute")
        dq = lim.get("quota_per_day")
        if isinstance(lim.get("limits"), dict):
            rl = rl if rl is not None else lim["limits"].get("rate_limit_per_minute")
            dq = dq if dq is not None else lim["limits"].get("quota_per_day")
            dq = dq if dq is not None else lim["limits"].get("daily_quota")
        logs = _logs()
        if rl is not None:
            try:
                rl_i = int(rl)
            except Exception:
                rl_i = None
            if rl_i and rl_i > 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= rl_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if dq is not None:
            try:
                dq_i = int(dq)
            except Exception:
                dq_i = None
            if dq_i and dq_i > 0:
                cutoff = now_dt - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    ts = _parse_ts(r.get("ts") or r.get("timestamp") or r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= dq_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(source_domain_id, str) or not source_domain_id:
        e = _err("VALIDATION_ERROR", "source_domain_id must be a string", field="source_domain_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(new_domain, str) or not new_domain.strip():
        e = _err("VALIDATION_ERROR", "new_domain must be a non-empty string", field="new_domain")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if copy_records is not None and not isinstance(copy_records, bool):
        e = _err("VALIDATION_ERROR", "copy_records must be a boolean", field="copy_records")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if copy_records is None:
        copy_records = False

    # validate domain name
    dom_re = re.compile(r"^(?=.{1,253}$)([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[A-Za-z]{2,63}$")
    if not dom_re.match(new_domain.strip().rstrip(".")):
        e = _err("VALIDATION_ERROR", "new_domain is not a valid domain name", field="new_domain")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    store = _load("storage_dns_managed.json")
    if not isinstance(store, list):
        store = []

    src = None
    for r in store:
        if isinstance(r, dict) and r.get("id") == source_domain_id and r.get("deleted_at") is None:
            src = r
            break
    if not src or src.get("resource_type") != "domain":
        e = _err("NOT_FOUND", "Source domain not found", field="source_domain_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # uniqueness of new domain name among domains (spec.domain_name)
    for r in store:
        if isinstance(r, dict) and r.get("resource_type") == "domain" and r.get("deleted_at") is None:
            sp = r.get("spec") or {}
            if isinstance(sp, dict) and sp.get("domain_name") == new_domain:
                e = _err("CONFLICT", "A domain with this name already exists", field="new_domain")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    new_dom_id = _new_id("dom")
    new_dom = copy.deepcopy(src)
    new_dom["id"] = new_dom_id
    new_dom["resource_type"] = "domain"
    new_dom["status"] = "active"
    new_dom["deleted_at"] = None
    new_dom["created_at"] = now
    new_dom["updated_at"] = now
    new_dom["last_operation_id"] = None
    if not isinstance(new_dom.get("spec"), dict):
        new_dom["spec"] = {}
    new_dom["spec"]["domain_name"] = new_domain
    new_dom["label"] = new_domain

    store.append(new_dom)

    new_records = []
