def get_mysql_credentials(db_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_mysql_credentials"
    status_code = "succeeded"
    err_obj = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(used_credential, status, error=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "credential_id": used_credential,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error is not None:
            row["error"] = error
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            limits = {}
        rate = limits.get("rate_limit_per_minute", 120)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[::-1]:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < one_min_ago:
                break
            recent += 1
        if isinstance(rate, int) and rate >= 0 and recent >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=rate, window_seconds=60)
        return None

    try:
        if not isinstance(db_id, str) or re.match(r"^db_01H8[0-9A-Z]+$", db_id) is None:
            err_obj = _err("VALIDATION_ERROR", "db_id is malformed.", db_id=db_id)
            status_code = "failed"
            return err_obj

        rl = _enforce_rate()
        if rl:
            err_obj = rl
            status_code = "failed"
            return err_obj

        resources = _load("storage_dns_managed.json")
        if not isinstance(resources, list):
            resources = []
        rec = None
        for r in resources:
            if r.get("id") == db_id and r.get("resource_type") == "db_mysql":
                rec = r
                break
        if rec is None:
            err_obj = _err("NOT_FOUND", "MySQL database instance not found.", db_id=db_id)
            status_code = "failed"
            return err_obj

        if rec.get("deleted_at") not in (None, "") or rec.get("status") in ("deleting", "deleted"):
            err_obj = _err("CONFLICT", "Credentials are unavailable for deleted/deleting instances.", status=rec.get("status"))
            status_code = "failed"
            return err_obj

        # Per business rule: credentials unavailable during provisioning, deleting, error
        if rec.get("status") in ("provisioning", "error", "updating", "suspending", "suspended", "resizing"):
            err_obj = _err("CONFLICT", "Credentials are unavailable in the current lifecycle state.", status=rec.get("status"))
            status_code = "failed"
            return err_obj

        secrets = rec.get("secrets")
        if not isinstance(secrets, dict) or not secrets.get("encrypted_blob"):
            err_obj = _err("CONFLICT", "Credentials are unavailable (missing secrets).")
            status_code = "failed"
            return err_obj

        # "Decrypted" secrets: since encryption is not implemented, return deterministic derived fields while including rotated_at.
        # Also include connection fields from spec if present (host/port/ssl).
        spec = rec.get("spec") if isinstance(rec.get("spec"), dict) else {}
        host = spec.get("host") or f"{rec.get('label','mysql')}.{rec.get('region_id','region')}.db.local"
        port = spec.get("port") or 3306
        username = spec.get("username") or "admin"
        password = "dec_" + secrets.get("encrypted_blob")[4:] if isinstance(secrets.get("encrypted_blob"), str) and secrets.get("encrypted_blob").startswith("enc_") else "dec_" + uuid.uuid4().hex

        data = {
            "db_id": db_id,
            "host": host,
            "port": port,
            "username": username,
            "password": password,
            "ssl": spec.get("ssl", True),
            "rotated_at": secrets.get("rotated_at")
        }
        return {"data": data}
    except Exception as e:
        err_obj = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        status_code = "failed"
        return err_obj
    finally:
        _log_call(None, status_code, error=err_obj["error"] if isinstance(err_obj, dict) and "error" in err_obj else None)

