        if isinstance(logs, list):
            logs.append({
                "id": f"req_{secrets.token_hex(8)}",
                "endpoint": "get_mysql_ssl_certificate",
                "credential_used": credential_used,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "request": {"db_id": db_id},
            })
            _save("request_log.json", logs)

    resources = _load("storage_dns_managed.json")
    if not any(r.get("resource_type") == "db_mysql" and r.get("deleted_at") is None for r in resources):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context available to access MySQL certificates")

    db = next((r for r in resources if r.get("id") == db_id), None)
    if not db or db.get("deleted_at") is not None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "MySQL database instance not found", db_id=db_id)
    if db.get("resource_type") != "db_mysql":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Resource is not a MySQL database instance", db_id=db_id)

    status = db.get("status")
    if status in ("provisioning", "deleting", "deleted"):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Certificate material not available in current lifecycle state", status=status)

    # "Decrypted" certificate: if present in spec.ssl, return it; else conflict
    spec = db.get("spec") if isinstance(db.get("spec"), dict) else {}
    ssl = spec.get("ssl") if isinstance(spec.get("ssl"), dict) else None
    if not ssl or not isinstance(ssl.get("ca_certificate"), str):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "SSL certificate material is not available for this instance", db_id=db_id)

    _log("ok")
    return {
        "db_id": db_id,
        "ssl": {
            "ca_certificate": ssl.get("ca_certificate"),
            "issued_at": ssl.get("issued_at"),
            "expires_at": ssl.get("expires_at")
        }
    }

def patch_mysql_instance(db_id, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]+$", db_id):
        return _err("VALIDATION_ERROR", "db_id is missing or malformed", field="db_id")

    def _log(status, credential_used=None, error_code=None):
        logs = _load("request_log.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{secrets.token_hex(8)}",
                "endpoint": "patch_mysql_instance",
                "credential_used": credential_used,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "request": {"db_id": db_id},
            })
            _save("request_log.json", logs)

    resources = _load("storage_dns_managed.json")
    if not any(r.get("resource_type") == "db_mysql" and r.get("deleted_at") is None for r in resources):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context available to manage MySQL databases")

    db = next((r for r in resources if r.get("id") == db_id), None)
    if not db or db.get("deleted_at") is not None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "MySQL database instance not found", db_id=db_id)
    if db.get("resource_type") != "db_mysql":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Resource is not a MySQL database instance", db_id=db_id)

    status = db.get("status")
    if status in ("provisioning", "deleting", "deleted", "suspending", "resizing"):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Instance state does not allow patching", status=status)
    if status == "updating":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Instance is already updating", status=status)

    ops = _load("operations.json")
    if any(o.get("resource_collection") == "storage_dns_managed" and o.get("resource_id") == db_id and o.get("status") == "running" for o in ops):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Another operation is currently running for this resource", db_id=db_id)

    # Lifecycle: active->updating allowed; error->updating allowed; suspended->updating allowed.
    allowed = {
        "provisioning": ["active", "error"],
        "active": ["updating", "suspending", "resizing", "deleting", "error"],
        "updating": ["active", "error"],
        "suspending": ["suspended", "error"],
        "suspended": ["updating", "deleting", "error"],
        "resizing": ["active", "error"],
        "deleting": ["deleted", "error"],
        "error": ["updating", "deleting"],
        "deleted": []
    }
    if "updating" not in allowed.get(status, []):
        _log("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot transition database to updating for patch", from_status=status, to_status="updating")

    op_id = f"op_{secrets.token_hex(10)}"
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": db_id,
        "operation_type": "patch",
        "status": "queued",
        "request": {"db_id": db_id, "resource_type": "db_mysql"},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None
    }
    ops.append(op)

    # Begin execution immediately in this offline backend: queued->running->succeeded
    op["status"] = "running"
    op["updated_at"] = now
    op["started_at"] = now

    prev_status = status
    db["status"] = "updating"
    db["updated_at"] = now
    db["last_operation_id"] = op_id

    spec = db.get("spec") if isinstance(db.get("spec"), dict) else {}
    # Record last patched time and bump a "maintenance_revision" counter if present.
    spec["last_patched_at"] = now
    if isinstance(spec.get("maintenance_revision"), int):
        spec["maintenance_revision"] += 1
    else:
        spec["maintenance_revision"] = 1
    db["spec"] = spec

    # Finish op
    op["status"] = "succeeded"
    op["updated_at"] = now
    op["finished_at"] = now
    op["result"] = {"last_patched_at": now, "maintenance_revision": spec.get("maintenance_revision")}

    # Return to stable state. Lifecycle doesn't allow updating->suspended; so always settle to active.
    db["status"] = "active"
    db["updated_at"] = now

    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)
    _log("ok")

    return {"operation": op}

def suspend_mysql_instance(db_id, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]+$", db_id):
        return _err("VALIDATION_ERROR", "db_id is missing or malformed", field="db_id")

    def _log(status, credential_used=None, error_code=None):
        logs = _load("request_log.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{secrets.token_hex(8)}",
                "endpoint": "suspend_mysql_instance",
                "credential_used": credential_used,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "request": {"db_id": db_id},
            })
            _save("request_log.json", logs)

    resources = _load("storage_dns_managed.json")
    if not any(r.get("resource_type") == "db_mysql" and r.get("deleted_at") is None for r in resources):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context available to manage MySQL databases")

    db = next((r for r in resources if r.get("id") == db_id), None)
    if not db or db.get("deleted_at") is not None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "MySQL database instance not found", db_id=db_id)
    if db.get("resource_type") != "db_mysql":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Resource is not a MySQL database instance", db_id=db_id)

    status = db.get("status")
    if status == "suspended":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Instance is already suspended", status=status)
    if status in ("provisioning", "deleting", "deleted", "updating", "resizing", "error"):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Instance is not in a suspendable state", status=status)

    ops = _load("operations.json")
    if any(o.get("resource_collection") == "storage_dns_managed" and o.get("resource_id") == db_id and o.get("status") == "running" for o in ops):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Another operation is currently running for this resource", db_id=db_id)

    # Lifecycle: active->suspending->suspended
    allowed = {
        "provisioning": ["active", "error"],
        "active": ["updating", "suspending", "resizing", "deleting", "error"],
        "updating": ["active", "error"],
        "suspending": ["suspended", "error"],
        "suspended": ["updating", "deleting", "error"],
        "resizing": ["active", "error"],
        "deleting": ["deleted", "error"],
        "error": ["updating", "deleting"],
        "deleted": []
    }
    if "suspending" not in allowed.get(status, []):
        _log("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot transition database to suspending", from_status=status, to_status="suspending")

    op_id = f"op_{secrets.token_hex(10)}"
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": db_id,
        "operation_type": "suspend",
        "status": "queued",
        "request": {"db_id": db_id, "resource_type": "db_mysql"},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None
    }
    ops.append(op)

    # Execute immediately: queued->running->succeeded
    op["status"] = "running"
    op["updated_at"] = now
    op["started_at"] = now

    db["status"] = "suspending"
    db["updated_at"] = now
    db["last_operation_id"] = op_id

    # Complete: suspending->suspended
    if "suspended" not in allowed.get("suspending", []):
        _log("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot transition database to suspended", from_status="suspending", to_status="suspended")

    db["status"] = "suspended"
    db["updated_at"] = now

    op["status"] = "succeeded"
    op["updated_at"] = now
    op["finished_at"] = now
    op["result"] = {"status": "suspended"}

    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)
    _log("ok")

    return {"operation": op}

def resume_mysql_instance(db_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "resume_mysql_instance",
            "credential": credential_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    # Quota/rate-limits: enforce if collections exist
    def _enforce_limits():
        rl = _load("rate_limits.json")
        usage = _load("usage_counters.json")
        if not isinstance(rl, list): rl = []
        if not isinstance(usage, list): usage = []
        # If no config, do nothing
        if not rl and not usage:
            return None

        # Aggregate recent calls for this endpoint (global, since no explicit credential context in tools)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        window_s = 60
        cutoff = (datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=window_s)).isoformat() + "Z"
        recent = [r for r in logs if isinstance(r, dict) and r.get("endpoint") == "resume_mysql_instance" and r.get("timestamp", "") >= cutoff]

        # Find a matching rule if present
        rule = None
        for r in rl:
            if isinstance(r, dict) and (r.get("endpoint") in (None, "resume_mysql_instance")):
                rule = r
                break
        if rule and isinstance(rule.get("per_minute"), int):
            if len(recent) >= rule["per_minute"]:
                return _err("RATE_LIMIT", "Rate limit exceeded for resume_mysql_instance.", limit=rule["per_minute"], window_seconds=60)

        # Quota: monthly
        month = datetime.datetime.utcnow().strftime("%Y-%m")
        quota = None
        for q in usage:
            if isinstance(q, dict) and q.get("metric") == "requests" and q.get("endpoint") in (None, "resume_mysql_instance") and q.get("period") in (None, month):
                quota = q
                break
        if quota and isinstance(quota.get("limit"), int):
            used = int(quota.get("used", 0) or 0)
            if used >= quota["limit"]:
                return _err("QUOTA_EXCEEDED", "Quota exceeded for resume_mysql_instance.", limit=quota["limit"], used=used, period=quota.get("period") or month)

        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log(429, error_code=lim_err["error"]["code"])
        return lim_err

    # Validate input
    if not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]+$", db_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "db_id is missing or malformed.", field="db_id")

    resources = _load("storage_dns_managed.json")
    if not isinstance(resources, list):
        _log(500, error_code="CONFLICT")
        return _err("CONFLICT", "Datastore is in an unexpected format for storage_dns_managed.")

    db = None
    for r in resources:
        if isinstance(r, dict) and r.get("id") == db_id and r.get("deleted_at") is None:
            db = r
            break

    if not db or db.get("resource_type") != "db_mysql":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "MySQL database instance not found.", db_id=db_id)

    # Must be suspended to resume; terminal/non-resumable: deleted/deleting
    status = db.get("status")
    if status in ("deleted", "deleting"):
        _log(409, error_code="CONFLICT")
        return _err("CONFLICT", "Instance is in a terminal/non-resumable state.", status=status)

    if status != "suspended":
        _log(409, error_code="CONFLICT")
        return _err("CONFLICT", "Instance is not currently suspended.", status=status)

    # Lifecycle transition: suspended -> updating (resume), then active.
    # Enforce "Only one running operation per resource"
    ops = _load("operations.json")
    if not isinstance(ops, list):
        _log(500, error_code="CONFLICT")
        return _err("CONFLICT", "Datastore is in an unexpected format for operations.")
    for o in ops:
        if isinstance(o, dict) and o.get("resource_collection") == "storage_dns_managed" and o.get("resource_id") == db_id and o.get("status") == "running":
            _log(409, error_code="CONFLICT")
            return _err("CONFLICT", "Another operation is already running for this resource.", operation_id=o.get("id"))

    # Create operation
    op_id = f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(ops)+1}"
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": db_id,
        "operation_type": "resume",
        "status": "running",
        "request": {"db_id": db_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op)

    # Mutate db state
    # suspended -> updating is allowed; then complete to active (async simulation completed immediately)
    db["status"] = "updating"
    db["last_operation_id"] = op_id
    db["updated_at"] = now

    # Complete operation and resource state
    finish = now
    op["status"] = "succeeded"
    op["updated_at"] = finish
    op["finished_at"] = finish
    op["result"] = {"db_id": db_id, "status": "active"}

    db["status"] = "active"
    db["updated_at"] = finish

    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    # Advance quota counters if present
    usage = _load("usage_counters.json")
    if isinstance(usage, list):
        month = datetime.datetime.utcnow().strftime("%Y-%m")
        found = False
        for q in usage:
            if isinstance(q, dict) and q.get("metric") == "requests" and q.get("endpoint") == "resume_mysql_instance" and q.get("period") == month:
                q["used"] = int(q.get("used", 0) or 0) + 1
                q["updated_at"] = now
                found = True
                break
        if not found:
            usage.append({"metric": "requests", "endpoint": "resume_mysql_instance", "period": month, "used": 1, "limit": None, "updated_at": now})
        _save("usage_counters.json", usage)

    resp = {"operation": op, "instance": {k: v for k, v in db.items() if k != "secrets"}}
    _log(200)
    return resp

