    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=sorted(allowed_status))
    if label is not None and not isinstance(label, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a string.", field="label")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
