    # Decode cursor (opaque)
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("endpoint") != "list_postgresql_instances":
                raise ValueError("bad cursor")
            start = int(payload.get("start", 0))
            if start < 0:
                raise ValueError("bad start")
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    rows = _load("storage_dns_managed.json")
