        if r.get("resource_type") != "db_postgresql":
            continue
        if r.get("deleted_at") is not None:
            continue
        if region_id is not None and r.get("region_id") != region_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if label is not None and r.get("label") != label:
            continue
        # Do not return secrets on list
        out.append({k: v for k, v in r.items() if k != "secrets"})

    # Sort
    reverse = (sort_order == "desc")
    def _key(x):
        v = x.get(sort_by)
        return "" if v is None else v
    out.sort(key=_key, reverse=reverse)

    total = len(out)
    page = out[start:start+limit]
    next_cursor = None
    if start + limit < total:
        payload = {"v": 1, "endpoint": "list_postgresql_instances", "start": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Advance quota counters if present
    usage = _load("usage_counters.json")
    if isinstance(usage, list):
        month = datetime.datetime.utcnow().strftime("%Y-%m")
        found = False
        for q in usage:
            if isinstance(q, dict) and q.get("metric") == "requests" and q.get("endpoint") == "list_postgresql_instances" and q.get("period") == month:
                q["used"] = int(q.get("used", 0) or 0) + 1
                q["updated_at"] = now
                found = True
                break
        if not found:
            usage.append({"metric": "requests", "endpoint": "list_postgresql_instances", "period": month, "used": 1, "limit": None, "updated_at": now})
        _save("usage_counters.json", usage)

    resp = {"data": page, "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": next_cursor is not None}}
    _log(200)
    return resp

