                q["used"] = int(q.get("used", 0) or 0) + 1
                q["updated_at"] = now
                foundc = True
                break
        if not foundc:
            usage.append({"metric": "requests", "endpoint": "get_postgresql_instance", "period": month, "used": 1, "limit": None, "updated_at": now})
