def create_postgresql_instance(label, region_id, type_id, engine=None, spec=None, tags=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "create_postgresql_instance",
            "credential": credential_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        rl = _load("rate_limits.json")
        usage = _load("usage_counters.json")
        if not isinstance(rl, list): rl = []
        if not isinstance(usage, list): usage = []
        if not rl and not usage:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        window_s = 60
        cutoff = (datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=window_s)).isoformat() + "Z"
        recent = [r for r in logs if isinstance(r, dict) and r.get("endpoint") == "create_postgresql_instance" and r.get("timestamp", "") >= cutoff]
        rule = None
        for r in rl:
            if isinstance(r, dict) and (r.get("endpoint") in (None, "create_postgresql_instance")):
                rule = r
                break
        if rule and isinstance(rule.get("per_minute"), int):
            if len(recent) >= rule["per_minute"]:
                return _err("RATE_LIMIT", "Rate limit exceeded for create_postgresql_instance.", limit=rule["per_minute"], window_seconds=60)
        month = datetime.datetime.utcnow().strftime("%Y-%m")
        quota = None
        for q in usage:
            if isinstance(q, dict) and q.get("metric") == "requests" and q.get("endpoint") in (None, "create_postgresql_instance") and q.get("period") in (None, month):
                quota = q
                break
        if quota and isinstance(quota.get("limit"), int):
            used = int(quota.get("used", 0) or 0)
            if used >= quota["limit"]:
                return _err("QUOTA_EXCEEDED", "Quota exceeded for create_postgresql_instance.", limit=quota["limit"], used=used, period=quota.get("period") or month)
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log(429, error_code=lim_err["error"]["code"])
        return lim_err

    # Validate inputs
    if not isinstance(label, str) or len(label.strip()) < 1:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string.", field="label")
    if not isinstance(region_id, str) or not region_id:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region_id is required and must be a string.", field="region_id")
    if not isinstance(type_id, str) or not type_id:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type_id is required and must be a string.", field="type_id")
    if engine is not None:
        if not isinstance(engine, str) or engine != "db_postgresql":
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "engine must be 'db_postgresql' when provided.", field="engine")
    if spec is None:
        spec = {}
    if not isinstance(spec, dict):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spec must be an object.", field="spec")
    if tags is None:
        tags = []
    if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

    # Validate catalog references: region must be active 'region', type_id must be active 'db_type'
    catalog = _load("infra_catalog.json")
    if not isinstance(catalog, list):
        _log(500, error_code="CONFLICT")
        return _err("CONFLICT", "Datastore is in an unexpected format for infra_catalog.")

    def _cat_active(cat_type, cid):
        for c in catalog:
            if isinstance(c, dict) and c.get("id") == cid and c.get("catalog_type") == cat_type and c.get("status") == "active":
                return c
        return None

    if not _cat_active("region", region_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region_id must reference an active region catalog item.", field="region_id")
    if not _cat_active("db_type", type_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type_id must reference an active db_type catalog item.", field="type_id")

    # Enforce spec constraints for db resources: engine_version not null; spec.type_id references infra_catalog.id
    # Store spec.type_id alongside for consistency even if caller didn't include it.
    spec = dict(spec)
    spec["type_id"] = type_id
    if spec.get("engine_version") is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spec.engine_version is required for PostgreSQL instances.", field="spec.engine_version")

    resources = _load("storage_dns_managed.json")
    if not isinstance(resources, list):
        _log(500, error_code="CONFLICT")
        return _err("CONFLICT", "Datastore is in an unexpected format for storage_dns_managed.")

    # Create id
    # Must match ^db_01H8[0-9A-Z]+$ (roughly ULID-ish). We'll generate a deterministic uppercase base32-ish suffix.
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    ts = int(datetime.datetime.utcnow().timestamp() * 1000)
    suffix = ""
    x = ts
    for _ in range(10):
        suffix = alphabet[x % len(alphabet)] + suffix
        x //= len(alphabet)
    new_id = f"db_01H8{suffix}"
    existing_ids = {r.get("id") for r in resources if isinstance(r, dict)}
    if new_id in existing_ids:
        # fallback
        new_id = f"db_01H8{suffix}{alphabet[(os.getpid() + len(resources)) % len(alphabet)]}"

    # Create operation; ensure no running op constraint irrelevant for create (no existing resource)
    ops = _load("operations.json")
    if not isinstance(ops, list):
        _log(500, error_code="CONFLICT")
        return _err("CONFLICT", "Datastore is in an unexpected format for operations.")
    op_id = f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(ops)+1}"
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": new_id,
        "operation_type": "create",
        "status": "running",
        "request": {
            "label": label,
            "region_id": region_id,
            "engine": "db_postgresql",
            "type_id": type_id,
            "spec": spec,
            "tags": tags
        },
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op)

    row = {
        "id": new_id,
        "resource_type": "db_postgresql",
        "label": label,
        "region_id": region_id,
        "status": "provisioning",
        "spec": spec,
        "attachments": [],
        "parent_id": None,
        "secrets": None,
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }

    resources.append(row)

    # Complete provisioning quickly (async simulated)
    finish = now
    row["status"] = "active"
    row["updated_at"] = finish
    op["status"] = "succeeded"
    op["updated_at"] = finish
    op["finished_at"] = finish
    op["result"] = {"db_id": new_id, "status": "active"}

    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    # Advance quota counters if present
    usage = _load("usage_counters.json")
    if isinstance(usage, list):
        month = datetime.datetime.utcnow().strftime("%Y-%m")
        found = False
        for q in usage:
            if isinstance(q, dict) and q.get("metric") == "requests" and q.get("endpoint") == "create_postgresql_instance" and q.get("period") == month:
                q["used"] = int(q.get("used", 0) or 0) + 1
                q["updated_at"] = now
                found = True
                break
        if not found:
            usage.append({"metric": "requests", "endpoint": "create_postgresql_instance", "period": month, "used": 1, "limit": None, "updated_at": now})
        _save("usage_counters.json", usage)

    _log(201)
    return {"data": {k: v for k, v in row.items() if k != "secrets"}, "operation": op}

def update_postgresql_instance(db_id, label=None, region_id=None, type_id=None, tags=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_op_id(ops):
        # operations don't define pattern; use stable prefix
        while True:
            cand = "op_" + uuid.uuid4().hex[:24]
            if not any(o.get("id") == cand for o in ops):
                return cand

    def _record_call(endpoint, status, credential_id=None, latency_ms=None, extra=None):
        # Best-effort request log if present in datastore; never fail the call because logging isn't configured.
        for fname in ("request_logs.json", "audit_log.json", "usage.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                row = {
                    "id": "req_" + uuid.uuid4().hex[:24],
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": _now(),
                }
                if extra:
                    row.update(extra)
                logs.append(row)
                _save(fname, logs)
                break

    start = time.time()
    endpoint = "update_postgresql_instance"

    try:
        if not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]{15,}$", db_id):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("VALIDATION_ERROR", "db_id is invalid.", field="db_id")

        if label is not None and (not isinstance(label, str) or not label.strip()):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("VALIDATION_ERROR", "label must be a non-empty string.", field="label")

        if region_id is not None and not isinstance(region_id, str):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("VALIDATION_ERROR", "region_id must be a string.", field="region_id")

        if type_id is not None and not isinstance(type_id, str):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("VALIDATION_ERROR", "type_id must be a string.", field="type_id")

        if tags is not None:
            if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
                _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
                return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

        resources = _load("storage_dns_managed.json")
        ops = _load("operations.json")
        catalog = _load("infra_catalog.json")

        db = next((r for r in resources if r.get("id") == db_id), None)
        if not db or db.get("deleted_at") is not None:
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "PostgreSQL instance not found.", db_id=db_id)

        if db.get("resource_type") != "db_postgresql":
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "Resource is not a PostgreSQL instance.", db_id=db_id)

        # Reject if another operation is running for this resource
        if any(o.get("resource_collection") == "storage_dns_managed" and o.get("resource_id") == db_id and o.get("status") == "running" for o in ops):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("CONFLICT", "Another operation is currently running for this instance.", db_id=db_id)

        # Validate region_id refers to active region if provided
        if region_id is not None:
            reg_item = next((c for c in catalog if c.get("id") == region_id), None)
            if not reg_item or reg_item.get("catalog_type") != "region" or reg_item.get("status") != "active":
                _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
                return _err("VALIDATION_ERROR", "region_id must reference an active region catalog item.", field="region_id")

        # Validate type_id refers to active db_type if provided
        if type_id is not None:
            type_item = next((c for c in catalog if c.get("id") == type_id), None)
            if not type_item or type_item.get("catalog_type") != "db_type" or type_item.get("status") != "active":
                _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
                return _err("VALIDATION_ERROR", "type_id must reference an active db_type catalog item.", field="type_id")

        # Determine whether this is a resizing lifecycle action: change of type_id
        spec = db.get("spec") if isinstance(db.get("spec"), dict) else {}
        current_type = spec.get("type_id")
        needs_resize = (type_id is not None and type_id != current_type)

        # Apply immediate mutable changes (label, tags, region_id, and spec fields)
        changed = {}
        if label is not None and label != db.get("label"):
            db["label"] = label
            changed["label"] = label

        if tags is not None:
            # store tags inside spec for DB resources (consistent with "spec includes ... tags")
            spec_tags = tags[:]
            if spec.get("tags") != spec_tags:
                spec["tags"] = spec_tags
                changed["tags"] = spec_tags

        if region_id is not None and region_id != db.get("region_id"):
            db["region_id"] = region_id
            changed["region_id"] = region_id

        if type_id is not None and type_id != current_type:
            spec["type_id"] = type_id
            changed["type_id"] = type_id

        if not isinstance(db.get("spec"), dict):
            db["spec"] = {}
        db["spec"].update(spec)

        now = _now()
        db["updated_at"] = now

        # If no changes, return current instance (idempotent update)
        if not changed:
            _save("storage_dns_managed.json", resources)
            _record_call(endpoint, "success", latency_ms=int((time.time() - start) * 1000))
            return {"data": db, "operation": None}

        operation = None
        if needs_resize:
            # Lifecycle transition: active -> resizing via operation.
            # Enforce that the transition is legal.
            status = db.get("status")
            allowed = {
                "provisioning": ["active", "error"],
                "active": ["updating", "suspending", "resizing", "deleting", "error"],
                "updating": ["active", "error"],
                "suspending": ["suspended", "error"],
                "suspended": ["updating", "deleting", "error"],
                "resizing": ["active", "error"],
                "deleting": ["deleted", "error"],
                "error": ["updating", "deleting"],
                "deleted": [],
            }.get(status, [])
            if "resizing" not in allowed:
                _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
                return _err("INVALID_TRANSITION", f"Cannot resize from status '{status}'.", from_status=status, to_status="resizing")

            op_id = _gen_op_id(ops)
            operation = {
                "id": op_id,
                "resource_collection": "storage_dns_managed",
                "resource_id": db_id,
                "operation_type": "resize",
                "status": "queued",
                "request": {"db_id": db_id, "changes": changed},
                "result": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now,
                "started_at": None,
                "finished_at": None,
            }
            ops.append(operation)
            db["last_operation_id"] = op_id
            # Transition resource to resizing immediately (async op will finish later)
            db["status"] = "resizing"
            db["updated_at"] = now

        else:
            # Non-resize updates: represent as update operation only if it implies lifecycle action.
            # For simple label/tags/region change, keep synchronous but still record update operation for audit.
            op_id = _gen_op_id(ops)
            operation = {
                "id": op_id,
                "resource_collection": "storage_dns_managed",
                "resource_id": db_id,
                "operation_type": "update",
                "status": "succeeded",
                "request": {"db_id": db_id, "changes": changed},
                "result": {"updated_fields": list(changed.keys())},
                "error_message": None,
                "created_at": now,
                "updated_at": now,
                "started_at": now,
                "finished_at": now,
            }
            ops.append(operation)
            db["last_operation_id"] = op_id
            db["updated_at"] = now

        _save("storage_dns_managed.json", resources)
        _save("operations.json", ops)

        _record_call(endpoint, "success", latency_ms=int((time.time() - start) * 1000))
        return {"data": db, "operation": operation}
    except Exception as e:
        _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def delete_postgresql_instance(db_id, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
