        }
        ops.append(operation)

        db["last_operation_id"] = op_id
        db["status"] = "deleting"
        db["updated_at"] = now

        # Soft-delete semantics: mark deleted_at when transitioning to deleted via operation.
        # Since we can't run an async worker, we complete the transition immediately after queuing
        # but preserve the operation trail.
        # Move operation to running->succeeded and resource to deleted with deleted_at.
        operation["status"] = "running"
        operation["started_at"] = now
        operation["updated_at"] = now

        # finish
        done = _now()
        operation["status"] = "succeeded"
        operation["finished_at"] = done
        operation["updated_at"] = done
        operation["result"] = {"deleted_at": done}

        # resource transition deleting -> deleted
        db["status"] = "deleted"
        db["deleted_at"] = done
        db["updated_at"] = done

        _save("operations.json", ops)
        _save("storage_dns_managed.json", resources)

        _record_call(endpoint, "success", latency_ms=int((time.time() - start) * 1000))
        return {"operation": operation, "data": db}
    except Exception as e:
        _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def get_postgresql_credentials(db_id, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_call(endpoint, status, credential_id=None, latency_ms=None, extra=None):
        for fname in ("request_logs.json", "audit_log.json", "usage.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                row = {
                    "id": "req_" + uuid.uuid4().hex[:24],
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": _now(),
                }
                if extra:
                    row.update(extra)
                logs.append(row)
                _save(fname, logs)
                break

    def _decrypt_secrets(secrets_obj):
        # Store is "encrypted-at-rest"; for offline server we interpret encrypted_blob as base64(json) when possible.
        if not isinstance(secrets_obj, dict):
            return None
        blob = secrets_obj.get("encrypted_blob")
        if not isinstance(blob, str) or not blob:
            return None
        # Try base64 decode to JSON
        try:
            raw = base64.b64decode(blob.encode("utf-8"), validate=False)
            try:
                return json.loads(raw.decode("utf-8"))
            except Exception:
                # If it's not JSON, return as opaque
                return {"secret": raw.decode("utf-8", errors="replace")}
        except Exception:
            # If it's not base64, return as opaque
            return {"secret": blob}

    start = time.time()
    endpoint = "get_postgresql_credentials"

    try:
        if not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]{15,}$", db_id):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("VALIDATION_ERROR", "db_id is invalid.", field="db_id")

        resources = _load("storage_dns_managed.json")
        db = next((r for r in resources if r.get("id") == db_id), None)
        if not db or db.get("deleted_at") is not None:
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "PostgreSQL instance not found.", db_id=db_id)

        if db.get("resource_type") != "db_postgresql":
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "Resource is not a PostgreSQL instance.", db_id=db_id)

        # State must allow credential retrieval
        if db.get("status") in ("provisioning", "deleting", "deleted"):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("CONFLICT", "Instance is not in a state where credentials can be retrieved.", status=db.get("status"))

        secrets = db.get("secrets")
        if secrets is None:
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "No credentials are stored for this instance.", db_id=db_id)

        creds = _decrypt_secrets(secrets)
        if creds is None:
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "Credentials could not be decoded.", db_id=db_id)

        _record_call(endpoint, "success", latency_ms=int((time.time() - start) * 1000))
        return {
            "data": {
                "db_id": db_id,
                "credentials": creds,
                "rotated_at": secrets.get("rotated_at"),
            }
        }
    except Exception as e:
        _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def reset_postgresql_credentials(db_id, **_extra):
    import json, os, datetime, re, time, uuid, base64, secrets as pysecrets, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_op_id(ops):
        while True:
            cand = "op_" + uuid.uuid4().hex[:24]
            if not any(o.get("id") == cand for o in ops):
                return cand

    def _record_call(endpoint, status, credential_id=None, latency_ms=None, extra=None):
        for fname in ("request_logs.json", "audit_log.json", "usage.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                row = {
                    "id": "req_" + uuid.uuid4().hex[:24],
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": _now(),
                }
                if extra:
                    row.update(extra)
                logs.append(row)
                _save(fname, logs)
                break

    def _encrypt_payload(payload_obj):
        # Represent "encrypted_blob" as base64(JSON). This is reversible for get_*_credentials.
        raw = json.dumps(payload_obj, ensure_ascii=False).encode("utf-8")
        return base64.b64encode(raw).decode("utf-8")

    def _new_password(n=24):
        alphabet = string.ascii_letters + string.digits
        return "".join(pysecrets.choice(alphabet) for _ in range(n))

    start = time.time()
    endpoint = "reset_postgresql_credentials"

    try:
        if not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]{15,}$", db_id):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("VALIDATION_ERROR", "db_id is invalid.", field="db_id")

        resources = _load("storage_dns_managed.json")
        ops = _load("operations.json")

        db = next((r for r in resources if r.get("id") == db_id), None)
        if not db or db.get("deleted_at") is not None:
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "PostgreSQL instance not found.", db_id=db_id)

        if db.get("resource_type") != "db_postgresql":
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("NOT_FOUND", "Resource is not a PostgreSQL instance.", db_id=db_id)

        # Must be in a state where credential operations are allowed
        if db.get("status") in ("provisioning", "deleting", "deleted"):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("CONFLICT", "Instance is not in a state where credentials can be reset.", status=db.get("status"))

        # Only one running operation per resource
        if any(o.get("resource_collection") == "storage_dns_managed" and o.get("resource_id") == db_id and o.get("status") == "running" for o in ops):
            _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
            return _err("CONFLICT", "Another operation is currently running for this instance.", db_id=db_id)

        now = _now()
        op_id = _gen_op_id(ops)
        operation = {
            "id": op_id,
            "resource_collection": "storage_dns_managed",
            "resource_id": db_id,
            "operation_type": "reset_credentials",
            "status": "queued",
            "request": {"db_id": db_id},
            "result": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": None,
            "finished_at": None,
        }
        ops.append(operation)

        # Generate new credentials; keep/derive some connection fields from spec when present
        spec = db.get("spec") if isinstance(db.get("spec"), dict) else {}
        username = spec.get("username") or "linode"
        host = spec.get("host") or (db.get("label") or db_id) + ".db.local"
        port = spec.get("port") or 5432
        database = spec.get("database") or "defaultdb"

        new_creds = {
            "username": username,
            "password": _new_password(),
            "host": host,
            "port": port,
            "database": database,
        }

        # Write secrets + rotate timestamp
        if db.get("secrets") is None or not isinstance(db.get("secrets"), dict):
            db["secrets"] = {"encrypted_blob": "", "key_id": "local_key", "rotated_at": None}
        db["secrets"]["encrypted_blob"] = _encrypt_payload(new_creds)
        db["secrets"]["key_id"] = db["secrets"].get("key_id") or "local_key"
        db["secrets"]["rotated_at"] = now

        db["last_operation_id"] = op_id
        db["updated_at"] = now

        # Complete operation immediately for offline dynamics
        operation["status"] = "running"
        operation["started_at"] = now
        operation["updated_at"] = now

        done = _now()
        operation["status"] = "succeeded"
        operation["finished_at"] = done
        operation["updated_at"] = done
        operation["result"] = {"rotated_at": now}

        _save("storage_dns_managed.json", resources)
        _save("operations.json", ops)

        _record_call(endpoint, "success", latency_ms=int((time.time() - start) * 1000))
        return {
            "data": {
                "db_id": db_id,
                "credentials": new_creds,
                "rotated_at": now,
            },
            "operation": operation,
        }
    except Exception as e:
        _record_call(endpoint, "error", latency_ms=int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def get_postgresql_ssl_certificate(db_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
