    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, credential_id=None, error_code=None, error_message=None, meta=None, started=None):
        # Best-effort request log (schema may or may not exist for this vendor snapshot)
        try:
            started = started or time.time()
            latency_ms = int((time.time() - started) * 1000)
            ts = _now()
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "credential_id": credential_id,
                "meta": meta or {},
                "created_at": ts,
                "latency_ms": latency_ms,
            }
            logs = _load("request_log.json")
            if isinstance(logs, list):
                logs.append(row)
                _save("request_log.json", logs)
        except Exception:
            return

    started = time.time()
    endpoint = "get_postgresql_ssl_certificate"

    if db_id is None or not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]{15,}$", db_id):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="db_id is missing or malformed.", started=started)
        return _err("VALIDATION_ERROR", "db_id is missing or malformed.", field="db_id")

    resources = _load("storage_dns_managed.json")
    db = None
    for r in resources:
        if r.get("id") == db_id and r.get("resource_type") == "db_postgresql":
            db = r
            break

    if db is None:
        _log(endpoint, "error", error_code="NOT_FOUND", error_message="PostgreSQL instance not found.", started=started)
        return _err("NOT_FOUND", "No PostgreSQL instance exists with that id.", db_id=db_id)

    # Soft-deleted DBs are not accessible for normal reads.
    if db.get("deleted_at") is not None:
        _log(endpoint, "error", error_code="NOT_FOUND", error_message="PostgreSQL instance not found.", started=started)
        return _err("NOT_FOUND", "No PostgreSQL instance exists with that id.", db_id=db_id)

    # Access control: this datastore snapshot carries no explicit account/workspace ownership fields.
    # Per contract, do not refuse well-formed requests without explicit credential unless no combination can serve.
    # Therefore, treat as authorized in this offline store.
    spec = db.get("spec") if isinstance(db.get("spec"), dict) else {}
    secrets = db.get("secrets") if isinstance(db.get("secrets"), dict) else {}

    # "Decrypted" behaviour: secrets are stored as encrypted_blob; offline server cannot decrypt.
    # Return PEM if present in spec or secrets; otherwise return metadata with a null pem.
    pem = None
    if isinstance(spec, dict) and isinstance(spec.get("ssl_certificate_pem"), str):
        pem = spec.get("ssl_certificate_pem")
    elif isinstance(secrets, dict) and isinstance(secrets.get("encrypted_blob"), str):
        # Provide a deterministic placeholder derived from the blob (not decrypting)
        digest = base64.b64encode(secrets["encrypted_blob"].encode("utf-8"))[:48].decode("ascii")
        pem = "-----BEGIN CERTIFICATE-----\n" + digest + "\n-----END CERTIFICATE-----\n"

    body = {
        "db_id": db_id,
        "certificate_pem": pem,
        "metadata": {
            "resource_type": db.get("resource_type"),
            "status": db.get("status"),
            "region_id": db.get("region_id"),
            "engine": "postgresql",
            "engine_version": spec.get("engine_version"),
            "rotated_at": (secrets.get("rotated_at") if isinstance(secrets, dict) else None),
            "updated_at": db.get("updated_at"),
            "created_at": db.get("created_at"),
        },
    }

    _log(endpoint, "ok", meta={"db_id": db_id}, started=started)
    return body

def patch_postgresql_instance(db_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, credential_id=None, error_code=None, error_message=None, meta=None, started=None):
        try:
            started = started or time.time()
            latency_ms = int((time.time() - started) * 1000)
            ts = _now()
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "credential_id": credential_id,
                "meta": meta or {},
                "created_at": ts,
                "latency_ms": latency_ms,
            }
            logs = _load("request_log.json")
            if isinstance(logs, list):
                logs.append(row)
                _save("request_log.json", logs)
        except Exception:
            return

    def _gen_id(prefix, rows):
        # rows is list of dicts with 'id'
        existing = set()
        for r in rows:
            rid = r.get("id")
            if isinstance(rid, str):
                existing.add(rid)
        for i in range(1, 1000000):
            cand = f"{prefix}_{int(time.time()*1000)}_{i}"
            if cand not in existing:
                return cand
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    started = time.time()
    endpoint = "patch_postgresql_instance"

    if db_id is None or not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]{15,}$", db_id):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="db_id is missing or malformed.", started=started)
        return _err("VALIDATION_ERROR", "db_id is missing or malformed.", field="db_id")

    resources = _load("storage_dns_managed.json")
    idx = None
    db = None
    for i, r in enumerate(resources):
        if r.get("id") == db_id and r.get("resource_type") == "db_postgresql":
            idx = i
            db = r
            break

    if db is None or db.get("deleted_at") is not None:
        _log(endpoint, "error", error_code="NOT_FOUND", error_message="PostgreSQL instance not found.", started=started)
        return _err("NOT_FOUND", "The database instance does not exist.", db_id=db_id)

    # Disallow patch when not patchable.
    status = db.get("status")
    # Lifecycle for storage_dns_managed: provisioning/active/updating/suspending/suspended/resizing/deleting/deleted/error
    # Patch is modeled as 'patch' operation + transition active -> updating.
    if status in ("provisioning", "updating", "deleting", "deleted", "resizing", "suspending"):
        _log(endpoint, "error", error_code="CONFLICT", error_message="Instance cannot be patched from current state.", meta={"status": status}, started=started)
        return _err("CONFLICT", "Instance cannot be patched from its current state.", db_id=db_id, status=status)
    if status == "suspended":
        _log(endpoint, "error", error_code="CONFLICT", error_message="Suspended instance cannot be patched.", meta={"status": status}, started=started)
        return _err("CONFLICT", "Instance cannot be patched while suspended.", db_id=db_id, status=status)

    # Enforce only-one-running-operation per resource
    ops = _load("operations.json")
    for op in ops:
        if op.get("resource_collection") == "storage_dns_managed" and op.get("resource_id") == db_id and op.get("status") == "running":
            _log(endpoint, "error", error_code="CONFLICT", error_message="Another operation is already running for this resource.", started=started)
            return _err("CONFLICT", "Another operation is already running for this resource.", db_id=db_id, operation_id=op.get("id"))

    now = _now()
    op_id = _gen_id("op", ops)

    # Create operation (queued -> immediately running -> succeeded, while leaving resource in 'updating' then 'active')
    # To preserve "observable dynamics", we record full lifecycle in operation timestamps and set last_operation_id.
    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": db_id,
        "operation_type": "patch",
        "status": "running",
        "request": {"db_id": db_id, "resource_type": "db_postgresql"},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    ops.append(op)

    # Resource transition active/suspended? already handled; allow from active or error
    if status not in ("active", "error"):
        _log(endpoint, "error", error_code="INVALID_TRANSITION", error_message="Illegal lifecycle transition for patch.", meta={"status": status}, started=started)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition for patch.", db_id=db_id, status=status)

    # Transition to updating
    db["status"] = "updating"
    db["last_operation_id"] = op_id
    db["updated_at"] = now
    resources[idx] = db

    # Persist intermediate state and operation running
    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    # Complete operation and bring DB back to active
    now2 = _now()
    # update resource
    resources = _load("storage_dns_managed.json")
    for i, r in enumerate(resources):
        if r.get("id") == db_id and r.get("resource_type") == "db_postgresql":
            r["status"] = "active"
            r["updated_at"] = now2
            r["last_operation_id"] = op_id
            resources[i] = r
            break
    _save("storage_dns_managed.json", resources)

    ops = _load("operations.json")
    for i, o in enumerate(ops):
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["result"] = {"db_id": db_id, "status_after": "active"}
            o["updated_at"] = now2
            o["finished_at"] = now2
            ops[i] = o
            break
    _save("operations.json", ops)

    _log(endpoint, "ok", meta={"db_id": db_id, "operation_id": op_id}, started=started)
    return op

