    def _gen_id(prefix, rows):
        existing = set()
        for r in rows:
            rid = r.get("id")
            if isinstance(rid, str):
                existing.add(rid)
        for i in range(1, 1000000):
            cand = f"{prefix}_{int(time.time()*1000)}_{i}"
            if cand not in existing:
                return cand
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    started = time.time()
    endpoint = "suspend_postgresql_instance"

    if db_id is None or not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]{15,}$", db_id):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="db_id is missing or malformed.", started=started)
        return _err("VALIDATION_ERROR", "db_id is missing or malformed.", field="db_id")

    resources = _load("storage_dns_managed.json")
    idx = None
    db = None
    for i, r in enumerate(resources):
        if r.get("id") == db_id and r.get("resource_type") == "db_postgresql":
            idx = i
            db = r
            break

    if db is None or db.get("deleted_at") is not None:
        _log(endpoint, "error", error_code="NOT_FOUND", error_message="PostgreSQL instance not found.", started=started)
        return _err("NOT_FOUND", "The instance does not exist.", db_id=db_id)

    status = db.get("status")
    # Must be able to transition active -> suspending -> suspended
    if status != "active":
        _log(endpoint, "error", error_code="CONFLICT", error_message="Instance cannot be suspended from current state.", meta={"status": status}, started=started)
        return _err("CONFLICT", "Instance cannot be suspended from its current state.", db_id=db_id, status=status)

    ops = _load("operations.json")
    for op in ops:
        if op.get("resource_collection") == "storage_dns_managed" and op.get("resource_id") == db_id and op.get("status") == "running":
            _log(endpoint, "error", error_code="CONFLICT", error_message="Another operation is already running for this resource.", started=started)
            return _err("CONFLICT", "Another operation is already running for this resource.", db_id=db_id, operation_id=op.get("id"))

    now = _now()
    op_id = _gen_id("op", ops)

    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": db_id,
        "operation_type": "suspend",
        "status": "running",
        "request": {"db_id": db_id, "resource_type": "db_postgresql"},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    ops.append(op)

    # Transition to suspending
    db["status"] = "suspending"
    db["last_operation_id"] = op_id
    db["updated_at"] = now
    resources[idx] = db

    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    # Complete: suspended
    now2 = _now()
    resources = _load("storage_dns_managed.json")
    for i, r in enumerate(resources):
        if r.get("id") == db_id and r.get("resource_type") == "db_postgresql":
            # Validate transition suspending -> suspended
            if r.get("status") != "suspending":
                _log(endpoint, "error", error_code="INVALID_TRANSITION", error_message="Illegal lifecycle transition to suspended.", meta={"status": r.get("status")}, started=started)
                return _err("INVALID_TRANSITION", "Illegal lifecycle transition to suspended.", db_id=db_id, status=r.get("status"))
            r["status"] = "suspended"
            r["updated_at"] = now2
            r["last_operation_id"] = op_id
            resources[i] = r
            break
    _save("storage_dns_managed.json", resources)

    ops = _load("operations.json")
    for i, o in enumerate(ops):
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["result"] = {"db_id": db_id, "status_after": "suspended"}
            o["updated_at"] = now2
            o["finished_at"] = now2
            ops[i] = o
            break
    _save("operations.json", ops)

    _log(endpoint, "ok", meta={"db_id": db_id, "operation_id": op_id}, started=started)
    return op

def resume_postgresql_instance(db_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, credential_id=None, error_code=None, error_message=None, meta=None, started=None):
        try:
            started = started or time.time()
            latency_ms = int((time.time() - started) * 1000)
            ts = _now()
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "credential_id": credential_id,
                "meta": meta or {},
                "created_at": ts,
                "latency_ms": latency_ms,
            }
            logs = _load("request_log.json")
            if isinstance(logs, list):
                logs.append(row)
                _save("request_log.json", logs)
        except Exception:
            return

    def _gen_id(prefix, rows):
        existing = set()
        for r in rows:
            rid = r.get("id")
            if isinstance(rid, str):
                existing.add(rid)
        for i in range(1, 1000000):
            cand = f"{prefix}_{int(time.time()*1000)}_{i}"
            if cand not in existing:
                return cand
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    started = time.time()
    endpoint = "resume_postgresql_instance"

    if db_id is None or not isinstance(db_id, str) or not re.match(r"^db_01H8[0-9A-Z]{15,}$", db_id):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="db_id is missing or malformed.", started=started)
        return _err("VALIDATION_ERROR", "db_id is missing or malformed.", field="db_id")

    resources = _load("storage_dns_managed.json")
    idx = None
    db = None
    for i, r in enumerate(resources):
        if r.get("id") == db_id and r.get("resource_type") == "db_postgresql":
            idx = i
            db = r
            break

    if db is None or db.get("deleted_at") is not None:
        _log(endpoint, "error", error_code="NOT_FOUND", error_message="PostgreSQL instance not found.", started=started)
        return _err("NOT_FOUND", "The instance does not exist.", db_id=db_id)

    status = db.get("status")
    if status != "suspended":
        _log(endpoint, "error", error_code="CONFLICT", error_message="Instance is not suspended.", meta={"status": status}, started=started)
        return _err("CONFLICT", "Instance is not currently suspended or cannot be resumed.", db_id=db_id, status=status)

    ops = _load("operations.json")
    for op in ops:
        if op.get("resource_collection") == "storage_dns_managed" and op.get("resource_id") == db_id and op.get("status") == "running":
            _log(endpoint, "error", error_code="CONFLICT", error_message="Another operation is already running for this resource.", started=started)
            return _err("CONFLICT", "Another operation is already running for this resource.", db_id=db_id, operation_id=op.get("id"))

    now = _now()
    op_id = _gen_id("op", ops)

    op = {
        "id": op_id,
        "resource_collection": "storage_dns_managed",
        "resource_id": db_id,
        "operation_type": "resume",
        "status": "running",
        "request": {"db_id": db_id, "resource_type": "db_postgresql"},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    ops.append(op)

    # Transition suspended -> updating (per lifecycle: suspended -> updating)
    db["status"] = "updating"
    db["last_operation_id"] = op_id
    db["updated_at"] = now
    resources[idx] = db

    _save("operations.json", ops)
    _save("storage_dns_managed.json", resources)

    # Complete: active
    now2 = _now()
    resources = _load("storage_dns_managed.json")
    for i, r in enumerate(resources):
        if r.get("id") == db_id and r.get("resource_type") == "db_postgresql":
            if r.get("status") != "updating":
                _log(endpoint, "error", error_code="INVALID_TRANSITION", error_message="Illegal lifecycle transition to active.", meta={"status": r.get("status")}, started=started)
                return _err("INVALID_TRANSITION", "Illegal lifecycle transition to active.", db_id=db_id, status=r.get("status"))
            r["status"] = "active"
            r["updated_at"] = now2
            r["last_operation_id"] = op_id
            resources[i] = r
            break
    _save("storage_dns_managed.json", resources)

    ops = _load("operations.json")
    for i, o in enumerate(ops):
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["result"] = {"db_id": db_id, "status_after": "active"}
            o["updated_at"] = now2
            o["finished_at"] = now2
            ops[i] = o
            break
    _save("operations.json", ops)

    _log(endpoint, "ok", meta={"db_id": db_id, "operation_id": op_id}, started=started)
    return op

def list_kubernetes_clusters(cursor=None, limit=None, region_id=None, status=None, label=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None):
        latency_ms = int((time.time() - t0) * 1000)
        ops = _load("operations.json")
        ops.append({
            "id": "op_log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "resource_collection": "kubernetes",
            "resource_id": "list_clusters",
            "operation_type": "update",
            "status": "succeeded" if status_code < 400 else "failed",
            "request": {
                "tool": "list_kubernetes_clusters",
                "cursor": cursor,
                "limit": limit,
                "region_id": region_id,
                "status": status,
                "label": label,
                "sort": sort,
                "order": order
            },
            "result": {
                "http_status": status_code,
                "latency_ms": latency_ms,
                "credential_used": credential_used
            },
            "error_message": None if status_code < 400 else "request_failed",
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("operations.json", ops)

    # Validation
    allowed_status = ["provisioning", "running", "updating", "recycling", "deleting", "deleted", "error", "suspended"]
    allowed_sort = ["created_at", "updated_at", "label", "status", "region_id"]
    allowed_order = ["asc", "desc"]

    if cursor is not None and not isinstance(cursor, str):
        _log(400)
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if limit is not None:
        if not isinstance(limit, int):
            _log(400)
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit <= 0 or limit > 500:
            _log(400)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
    if region_id is not None and not isinstance(region_id, str):
        _log(400)
        return _err("VALIDATION_ERROR", "region_id must be a string")
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400)
            return _err("VALIDATION_ERROR", "status must be one of the allowed values", allowed=allowed_status)
    if label is not None and not isinstance(label, str):
        _log(400)
        return _err("VALIDATION_ERROR", "label must be a string")
    if sort is not None:
        if not isinstance(sort, str) or sort not in allowed_sort:
            _log(400)
            return _err("VALIDATION_ERROR", "sort must be one of the allowed values", allowed=allowed_sort)
    if order is not None:
        if not isinstance(order, str) or order not in allowed_order:
            _log(400)
            return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'")
    if sort is None:
        sort = "created_at"
    if order is None:
        order = "asc"

    # Parse cursor as integer offset (simple stable server-side pagination)
    offset = 0
    if cursor:
        if not re.fullmatch(r"[0-9]+", cursor):
            _log(400)
            return _err("VALIDATION_ERROR", "cursor is malformed")
        offset = int(cursor)

    k8s = _load("kubernetes.json")
    # Read tools exclude soft-deleted rows
    rows = [r for r in k8s if isinstance(r, dict) and r.get("entity_type") == "cluster" and r.get("deleted_at") in (None, "", False)]

    if region_id is not None:
        rows = [r for r in rows if r.get("region_id") == region_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if label is not None:
        rows = [r for r in rows if r.get("label") == label]

    def _key(v):
        x = v.get(sort)
        # normalize None for sorting
        if x is None:
            return ""
        return x

    reverse = (order == "desc")
    rows_sorted = sorted(rows, key=_key, reverse=reverse)

    total = len(rows_sorted)
    if offset < 0 or offset > total:
        _log(400)
        return _err("VALIDATION_ERROR", "cursor out of range")

    page_size = limit if limit is not None else 100
    page = rows_sorted[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    _log(200)
    return {
        "data": page,
        "meta": {
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "limit": page_size,
            "cursor": str(offset)
        }
    }

