def create_kubernetes_cluster(label, region_id, k8s_version, node_pools, tags=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _make_id(prefix):
        # produce lke_01H8 + base32-ish uppercase chars
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _log(status_code, resource_id="create_cluster"):
        latency_ms = int((time.time() - t0) * 1000)
        ops = _load("operations.json")
        ops.append({
            "id": "op_log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "resource_collection": "kubernetes",
            "resource_id": resource_id,
            "operation_type": "create",
            "status": "succeeded" if status_code < 400 else "failed",
            "request": {
                "tool": "create_kubernetes_cluster",
                "label": label,
                "region_id": region_id,
                "k8s_version": k8s_version,
                "tags": tags,
                "node_pools": node_pools
            },
            "result": {"http_status": status_code, "latency_ms": latency_ms},
            "error_message": None if status_code < 400 else "request_failed",
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("operations.json", ops)

    # Validate inputs
    if not isinstance(label, str) or not label.strip():
        _log(400)
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string")
    if not isinstance(region_id, str) or not region_id.strip():
        _log(400)
        return _err("VALIDATION_ERROR", "region_id is required and must be a non-empty string")
    if not isinstance(k8s_version, str) or not k8s_version.strip():
        _log(400)
        return _err("VALIDATION_ERROR", "k8s_version is required and must be a non-empty string")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log(400)
            return _err("VALIDATION_ERROR", "tags must be an array of strings")
    if not isinstance(node_pools, list) or len(node_pools) == 0:
        _log(400)
        return _err("VALIDATION_ERROR", "node_pools must be a non-empty array")
    for i, p in enumerate(node_pools):
        if not isinstance(p, dict):
            _log(400)
            return _err("VALIDATION_ERROR", "each node pool must be an object", index=i)
        if "type_id" not in p or "count" not in p:
            _log(400)
            return _err("VALIDATION_ERROR", "each node pool requires type_id and count", index=i)
        if not isinstance(p.get("type_id"), str) or not p["type_id"].strip():
            _log(400)
            return _err("VALIDATION_ERROR", "node pool type_id must be a non-empty string", index=i)
        if not isinstance(p.get("count"), int) or p["count"] < 1 or p["count"] > 500:
            _log(400)
            return _err("VALIDATION_ERROR", "node pool count must be between 1 and 500", index=i)
        if "label" in p and p["label"] is not None and (not isinstance(p["label"], str)):
            _log(400)
            return _err("VALIDATION_ERROR", "node pool label must be a string if provided", index=i)

    catalog = _load("infra_catalog.json")

    def _find_active(catalog_type, item_id=None, slug=None, label=None):
        for c in catalog:
            if not isinstance(c, dict):
                continue
            if c.get("catalog_type") != catalog_type:
                continue
            if c.get("status") != "active":
                continue
            if item_id is not None and c.get("id") != item_id:
                continue
            if slug is not None and isinstance(c.get("spec"), dict) and c["spec"].get("slug") != slug:
                continue
            if label is not None and c.get("label") != label:
                continue
            return c
        return None

    # region must exist and be active
    region_item = _find_active("region", item_id=region_id)
    if region_item is None:
        _log(400)
        return _err("VALIDATION_ERROR", "region_id must reference an active region in infra_catalog", region_id=region_id)

    # k8s_version must exist and be active in catalog (preferred), else allow only if a catalog region advertises it
    k8s_item = _find_active("k8s_version", label=k8s_version)
    if k8s_item is None:
        # fallback: some stores may embed available versions; enforce declared constraint as best-effort
        offered = False
        for c in catalog:
            if isinstance(c, dict) and c.get("catalog_type") == "k8s_version" and c.get("status") == "active":
                if c.get("label") == k8s_version:
                    offered = True
                    break
        if not offered:
            _log(400)
            return _err("VALIDATION_ERROR", "k8s_version is not offered", k8s_version=k8s_version)

    # node pool type_id must reference active infra_catalog (k8s_type preferred; allow linode_type)
    for i, p in enumerate(node_pools):
        type_id = p["type_id"]
        ok = _find_active("k8s_type", item_id=type_id) or _find_active("linode_type", item_id=type_id)
        if ok is None:
            _log(400)
            return _err("VALIDATION_ERROR", "node pool type_id must reference an active k8s_type or linode_type", index=i, type_id=type_id)

    # Create cluster + pools + nodes
    k8s = _load("kubernetes.json")
    cluster_id = _make_id("lke_01H8")
    # Ensure uniqueness in store
    existing_ids = {r.get("id") for r in k8s if isinstance(r, dict)}
    while cluster_id in existing_ids:
        cluster_id = _make_id("lke_01H8")

    op_id = "op_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    # Check only-one-running-op rule for target resource: new cluster has none; ok

    cluster_row = {
        "id": cluster_id,
        "entity_type": "cluster",
        "parent_id": None,
        "label": label,
        "region_id": region_id,
        "k8s_version": k8s_version,
        "type_id": None,
        "count": None,
        "status": "provisioning",
        "api_endpoints": [],
        "access": None,
        "spec": {"tags": tags or []},
        "last_operation_id": op_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }

    new_rows = [cluster_row]
    pool_rows = []
    node_rows = []
    for p in node_pools:
        pool_id = "lke_pool_" + secrets.token_hex(8)
        pool_rows.append({
            "id": pool_id,
            "entity_type": "node_pool",
            "parent_id": cluster_id,
            "label": p.get("label"),
            "region_id": None,
            "k8s_version": None,
            "type_id": p["type_id"],
            "count": p["count"],
            "status": "provisioning",
            "api_endpoints": [],
            "access": None,
            "spec": {"autoscaler": None, "tags": []},
            "last_operation_id": op_id,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None
        })
        for _ in range(int(p["count"])):
            node_id = "lke_node_" + secrets.token_hex(10)
            node_rows.append({
                "id": node_id,
                "entity_type": "node",
                "parent_id": pool_id,
                "label": None,
                "region_id": None,
                "k8s_version": None,
                "type_id": None,
                "count": None,
                "status": "provisioning",
                "api_endpoints": [],
                "access": None,
                "spec": {},
                "last_operation_id": op_id,
                "created_at": now,
                "updated_at": now,
                "deleted_at": None
            })

    # Persist resources
    k8s.extend(new_rows)
    k8s.extend(pool_rows)
    k8s.extend(node_rows)
    _save("kubernetes.json", k8s)

    # Create operation (queued -> running -> succeeded) for provisioning (async reflected in status)
    ops = _load("operations.json")
    # Ensure no other running op for the cluster (none should exist)
    for o in ops:
        if isinstance(o, dict) and o.get("resource_collection") == "kubernetes" and o.get("resource_id") == cluster_id and o.get("status") == "running":
            _log(409, resource_id=cluster_id)
            return _err("CONFLICT", "Another operation is already running for this cluster")

    operation = {
        "id": op_id,
        "resource_collection": "kubernetes",
        "resource_id": cluster_id,
        "operation_type": "create",
        "status": "running",
        "request": {
            "label": label,
            "region_id": region_id,
            "k8s_version": k8s_version,
            "tags": tags or [],
            "node_pools": node_pools
        },
        "result": {"cluster_id": cluster_id},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(operation)

    # For offline deterministic behavior, mark provisioning as succeeded immediately but keep cluster status provisioning
    # to reflect async creation; caller may observe operation completion and cluster provisioning.
    operation["status"] = "succeeded"
    operation["updated_at"] = now
    operation["finished_at"] = now
    _save("operations.json", ops)

    _log(201, resource_id=cluster_id)
    return {"data": cluster_row, "operation": operation}

def update_kubernetes_cluster(cluster_id, label=None, k8s_version=None, tags=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_code):
        latency_ms = int((time.time() - t0) * 1000)
        ops = _load("operations.json")
        ops.append({
            "id": "op_log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "resource_collection": "kubernetes",
            "resource_id": cluster_id if isinstance(cluster_id, str) else "invalid",
            "operation_type": "update",
            "status": "succeeded" if status_code < 400 else "failed",
            "request": {"tool": "update_kubernetes_cluster", "cluster_id": cluster_id, "label": label, "k8s_version": k8s_version, "tags": tags},
            "result": {"http_status": status_code, "latency_ms": latency_ms},
            "error_message": None if status_code < 400 else "request_failed",
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("operations.json", ops)

    if cluster_id is None or not isinstance(cluster_id, str):
        _log(400)
        return _err("VALIDATION_ERROR", "cluster_id is required and must be a string")
    if not re.fullmatch(r"^lke_01H8[0-9A-Z]{15,}$", cluster_id):
        _log(400)
        return _err("VALIDATION_ERROR", "cluster_id does not match required format", pattern="^lke_01H8[0-9A-Z]{15,}$")

    if label is None and k8s_version is None and tags is None:
        _log(400)
        return _err("VALIDATION_ERROR", "At least one of label, k8s_version, or tags must be provided")

    if label is not None and (not isinstance(label, str) or not label.strip()):
        _log(400)
        return _err("VALIDATION_ERROR", "label must be a non-empty string when provided")
    if k8s_version is not None and (not isinstance(k8s_version, str) or not k8s_version.strip()):
        _log(400)
        return _err("VALIDATION_ERROR", "k8s_version must be a non-empty string when provided")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log(400)
            return _err("VALIDATION_ERROR", "tags must be an array of strings")

    k8s = _load("kubernetes.json")
    idx = None
    for i, r in enumerate(k8s):
        if isinstance(r, dict) and r.get("entity_type") == "cluster" and r.get("id") == cluster_id:
            idx = i
            break
    if idx is None:
        _log(404)
        return _err("NOT_FOUND", "Kubernetes cluster not found", cluster_id=cluster_id)

    cluster = k8s[idx]

    # Conflict / state restrictions: cannot modify if deleted or deleting, and avoid changes during provisioning/updating/recycling
    if cluster.get("deleted_at") not in (None, "", False) or cluster.get("status") == "deleted":
        _log(409)
        return _err("CONFLICT", "Cluster has been deleted and cannot be modified")
    if cluster.get("status") in ("deleting", "provisioning", "updating", "recycling"):
        _log(409)
        return _err("CONFLICT", "Cluster cannot be modified from its current state", status=cluster.get("status"))

    # Validate target k8s_version if provided (must be offered/active)
    op = None
    if k8s_version is not None and k8s_version != cluster.get("k8s_version"):
        catalog = _load("infra_catalog.json")
        offered = False
        for c in catalog:
            if isinstance(c, dict) and c.get("catalog_type") == "k8s_version" and c.get("status") == "active" and c.get("label") == k8s_version:
                offered = True
                break
        if not offered:
            _log(400)
            return _err("VALIDATION_ERROR", "k8s_version is not offered", k8s_version=k8s_version)

        # Create an upgrade operation and move status via lifecycle running->updating
        # Enforce "only one running operation per resource"
        ops = _load("operations.json")
        for o in ops:
            if isinstance(o, dict) and o.get("resource_collection") == "kubernetes" and o.get("resource_id") == cluster_id and o.get("status") == "running":
                _log(409)
                return _err("CONFLICT", "Another operation is already running for this cluster")

        op_id = "op_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        cluster["last_operation_id"] = op_id
        # Transition running/suspended -> updating is allowed by lifecycle; otherwise conflict above
        cluster["status"] = "updating"
        cluster["k8s_version"] = k8s_version

        op = {
            "id": op_id,
            "resource_collection": "kubernetes",
            "resource_id": cluster_id,
            "operation_type": "upgrade",
            "status": "running",
            "request": {"cluster_id": cluster_id, "target_k8s_version": k8s_version},
            "result": {"cluster_id": cluster_id, "k8s_version": k8s_version},
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": None
        }
        ops.append(op)
        # For offline behavior, finish operation immediately; cluster remains updating to reflect async
        op["status"] = "succeeded"
        op["updated_at"] = now
        op["finished_at"] = now
        _save("operations.json", ops)

    # Apply label/tags changes
    changed = False
    if label is not None and label != cluster.get("label"):
        cluster["label"] = label
        changed = True
    if tags is not None:
        if not isinstance(cluster.get("spec"), dict) or cluster.get("spec") is None:
            cluster["spec"] = {}
        if tags != cluster["spec"].get("tags"):
            cluster["spec"]["tags"] = tags
            changed = True

    if not changed and op is None:
        # Idempotent update with no changes: still "success with effect"? treat as success returning current resource.
        # But no mutation occurred; keep semantics: return current cluster without error.
        _log(200)
        return {"data": cluster, "operation": None}

    cluster["updated_at"] = now
    k8s[idx] = cluster
    _save("kubernetes.json", k8s)

    _log(200)
    return {"data": cluster, "operation": op}

def list_kubernetes_node_pools(cluster_id, cursor=None, limit=None, status=None, label=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_kubernetes_node_pools"
    cred_used = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "credential": cred_used,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    # Rate limit
    logs = _load("request_logs.json")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs[-2000:]:
        ts = r.get("ts")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
    if recent >= 120:
        e = _err("RATE_LIMIT", "Rate limit exceeded")
        _log("error", e["error"])
        return e

    # Validate
    if not isinstance(cluster_id, str) or not re.match(r"^lke_01H8[0-9A-Z]{15,}$", cluster_id):
        e = _err("VALIDATION_ERROR", "cluster_id is malformed")
        _log("error", e["error"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string")
        _log("error", e["error"])
        return e
    if limit is not None:
        if not isinstance(limit, int) or limit <= 0 or limit > 500:
            e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
            _log("error", e["error"])
            return e
    if status is not None:
        allowed = {"provisioning","running","updating","recycling","deleting","deleted","error","suspended"}
        if not isinstance(status, str) or status not in allowed:
            e = _err("VALIDATION_ERROR", "invalid status filter")
            _log("error", e["error"])
            return e
    if label is not None and not isinstance(label, str):
        e = _err("VALIDATION_ERROR", "label must be a string")
        _log("error", e["error"])
        return e
    if sort is not None:
        allowed_sort = {"created_at","updated_at","label","status","count","type_id"}
        if not isinstance(sort, str) or sort not in allowed_sort:
            e = _err("VALIDATION_ERROR", "invalid sort field")
            _log("error", e["error"])
            return e
    if order is not None:
        if not isinstance(order, str) or order not in ("asc","desc"):
            e = _err("VALIDATION_ERROR", "invalid order")
            _log("error", e["error"])
            return e

    kube = _load("kubernetes.json")

    cluster = None
    for row in kube:
        if row.get("id") == cluster_id and row.get("entity_type") == "cluster":
            cluster = row
            break
    if not cluster or cluster.get("deleted_at") is not None:
        e = _err("NOT_FOUND", "Cluster not found")
        _log("error", e["error"])
        return e

    pools = []
    for row in kube:
        if row.get("entity_type") != "node_pool":
            continue
        if row.get("parent_id") != cluster_id:
            continue
        if row.get("deleted_at") is not None:
            continue
        if status is not None and row.get("status") != status:
            continue
        if label is not None and row.get("label") != label:
            continue
        pools.append(row)

    # Sorting
    sfield = sort or "created_at"
    rev = (order or "asc") == "desc"

    def _key(r):
        v = r.get(sfield)
        if v is None:
            return ""
        return v

    pools.sort(key=_key, reverse=rev)

    # Cursor is an integer offset encoded as string
    start = 0
    if cursor:
        if not cursor.isdigit():
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log("error", e["error"])
            return e
        start = int(cursor)
        if start < 0:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log("error", e["error"])
            return e

    lim = limit or 100
    page = pools[start:start + lim]
    next_cursor = None
    has_more = start + lim < len(pools)
    if has_more:
        next_cursor = str(start + lim)

    resp = {
        "data": page,
        "meta": {
            "total": len(pools),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "limit": lim,
            "cursor": str(start)
        }
    }
    _log("ok")
    return resp

