def update_kubernetes_node_pool(cluster_id, node_pool_id, label=None, type_id=None, count=None, spec=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers for ops/logging/auth/quota ----
    def _gen_id(prefix):
        # 17+ chars uppercase base32-ish
        import random, string
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _record_request(endpoint, status, credential_id=None, meta=None, error=None):
        # Best-effort request logging if collection exists.
        for fname in ("request_log.json", "requests.json", "usage.json", "audit_log.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rid = "req_" + uuid.uuid4().hex
                row = {
                    "id": rid,
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                }
                if meta is not None:
                    row["meta"] = meta
                if error is not None:
                    row["error"] = error
                rows.append(row)
                _save(fname, rows)
                return

    def _check_limits(endpoint):
        # Enforce if a limits/quota store exists; otherwise allow.
        # Supported (best-effort) schemas:
        # - rate_limits.json: [{"id","window_seconds","max_requests","scope","endpoints":[...]}]
        # - quotas.json: [{"id","period":"day|month","max_requests","scope","endpoints":[...]}]
        # - api_keys.json: may have {"rate_limit_per_minute":...,"quota_per_day":...}
        # Without explicit credentials in tool params, apply global limits if present.
        # Returns None if ok else error object.
        win_file = os.path.join(_DB, "rate_limits.json")
        q_file = os.path.join(_DB, "quotas.json")
        log_file = None
        for fname in ("request_log.json", "requests.json", "usage.json", "audit_log.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                log_file = fname
                break
        if not log_file:
            return None

        logs = _load(log_file)
        now_dt = datetime.datetime.utcnow()

        if os.path.exists(win_file):
            limits = _load("rate_limits.json")
            if isinstance(limits, list):
                for lim in limits:
                    try:
                        endpoints = lim.get("endpoints")
                        if endpoints and endpoint not in endpoints:
                            continue
                        window = int(lim.get("window_seconds", 60))
                        mx = int(lim.get("max_requests", 0))
                        if mx <= 0:
                            continue
                        cutoff = now_dt - datetime.timedelta(seconds=window)
                        cnt = 0
                        for r in logs[::-1]:
                            ts = r.get("timestamp") or r.get("created_at")
                            if not ts:
                                continue
                            try:
                                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                            except Exception:
                                continue
                            if rdt < cutoff:
                                break
                            if r.get("endpoint") == endpoint:
                                cnt += 1
                        if cnt >= mx:
                            return _err("RATE_LIMIT", "Rate limit exceeded", limit=mx, window_seconds=window)
                    except Exception:
                        continue

        if os.path.exists(q_file):
            quotas = _load("quotas.json")
            if isinstance(quotas, list):
                for q in quotas:
                    try:
                        endpoints = q.get("endpoints")
                        if endpoints and endpoint not in endpoints:
                            continue
                        period = q.get("period", "day")
                        mx = int(q.get("max_requests", 0))
                        if mx <= 0:
                            continue
                        if period == "month":
                            cutoff = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
                        else:
                            cutoff = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
                        cnt = 0
                        for r in logs:
                            if r.get("endpoint") != endpoint:
                                continue
                            ts = r.get("timestamp") or r.get("created_at")
                            if not ts:
                                continue
                            try:
                                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                            except Exception:
                                continue
                            if rdt >= cutoff:
                                cnt += 1
                        if cnt >= mx:
                            return _err("QUOTA_EXCEEDED", "Quota exceeded", limit=mx, period=period)
                    except Exception:
                        continue
        return None

    endpoint = "update_kubernetes_node_pool"
    lim_err = _check_limits(endpoint)
    if lim_err:
        _record_request(endpoint, "error", error=lim_err["error"])
        return lim_err

    # ---- validate inputs ----
    if not isinstance(cluster_id, str) or not re.match(r"^lke_[0-9A-Z]{17,}$", cluster_id):
        e = _err("VALIDATION_ERROR", "Malformed cluster_id")
