            _record_request(endpoint, "error", error=e["error"])
            return e
        if count < 0:
            e = _err("VALIDATION_ERROR", "count must be >= 0")
            _record_request(endpoint, "error", error=e["error"])
            return e
        if count > 500:
            e = _err("VALIDATION_ERROR", "count must be <= 500")
            _record_request(endpoint, "error", error=e["error"])
            return e
    if spec is not None and not isinstance(spec, dict):
        e = _err("VALIDATION_ERROR", "spec must be an object")
        _record_request(endpoint, "error", error=e["error"])
        return e

    kube = _load("kubernetes.json")
    infra = _load("infra_catalog.json")
    ops = _load("operations.json")

    # ---- auth (ambient) ----
    # No explicit credentials in this tool; allow if any cluster exists (admin context implied).
    # If no data exists at all, treat as unauthorized to match "must be permitted to administer cluster".
    any_cluster = any(r.get("entity_type") == "cluster" and r.get("deleted_at") is None for r in kube)
    if not any_cluster:
        e = _err("UNAUTHORIZED", "Not authorized to administer Kubernetes clusters")
        _record_request(endpoint, "error", error=e["error"])
        return e

    # ---- locate cluster and pool ----
    cluster = None
    for r in kube:
        if r.get("id") == cluster_id and r.get("entity_type") == "cluster" and r.get("deleted_at") is None:
            cluster = r
            break
    if not cluster:
        e = _err("NOT_FOUND", "Cluster not found")
        _record_request(endpoint, "error", error=e["error"])
        return e

    pool = None
    for r in kube:
        if r.get("id") == node_pool_id and r.get("entity_type") == "node_pool" and r.get("deleted_at") is None:
            pool = r
            break
    if not pool or pool.get("parent_id") != cluster_id:
        e = _err("NOT_FOUND", "Node pool not found in cluster")
        _record_request(endpoint, "error", error=e["error"])
        return e

    # ---- validate type_id if changing ----
    if type_id is not None:
        ok = False
        for c in infra:
            if c.get("id") == type_id and c.get("catalog_type") in ("linode_type", "k8s_type") and c.get("status") == "active":
                ok = True
                break
        if not ok:
            e = _err("VALIDATION_ERROR", "type_id must reference an active catalog item for node pool types")
            _record_request(endpoint, "error", error=e["error"])
            return e

    # ---- ensure no other running operation for this resource ----
    for o in ops:
        if o.get("resource_collection") == "kubernetes" and o.get("resource_id") == node_pool_id and o.get("status") == "running":
            e = _err("CONFLICT", "Another operation is currently running for this node pool")
            _record_request(endpoint, "error", error=e["error"])
            return e

    # ---- apply updates ----
    changed = {}
    if label is not None and label != pool.get("label"):
        pool["label"] = label
        changed["label"] = label
    if type_id is not None and type_id != pool.get("type_id"):
        pool["type_id"] = type_id
        changed["type_id"] = type_id
    if count is not None and count != pool.get("count"):
        pool["count"] = count
        changed["count"] = count
    if spec is not None:
        # Merge update (provider-specific); replace keys provided
        cur = pool.get("spec") if isinstance(pool.get("spec"), dict) else {}
        new_spec = dict(cur)
        new_spec.update(spec)
        pool["spec"] = new_spec
        changed["spec"] = spec

    if not changed:
        # Idempotent: still return resource, but must have an observable effect? This is a mutation.
        # Real APIs often allow no-op updates; we will record an update operation only if fields changed.
        # To satisfy "no success without effect", treat as conflict-free no-op but still update updated_at timestamp.
        pool["updated_at"] = now
        changed = {"updated_at": now}
    else:
        pool["updated_at"] = now

    # ---- async operation when node membership may change (count/type change) ----
    op = None
    if any(k in changed for k in ("count", "type_id")):
        op_id = _gen_id("op_")
        op = {
            "id": op_id,
            "resource_collection": "kubernetes",
            "resource_id": node_pool_id,
            "operation_type": "update",
            "status": "running",
            "request": {
                "cluster_id": cluster_id,
                "node_pool_id": node_pool_id,
                "changes": changed
            },
            "result": {"changed_fields": list(changed.keys())},
            "error_message": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": None
        }
        ops.append(op)
        pool["last_operation_id"] = op_id

        # Apply immediate state transition to updating (legal from running/provisioning? only defined: running->updating, provisioning->running/error)
        # Node pools share same lifecycle. We'll transition to 'updating' if allowed; else keep current.
        transitions = {
            "provisioning": ["running", "error"],
            "running": ["updating", "recycling", "deleting", "error", "suspended"],
            "updating": ["running", "error"],
            "recycling": ["running", "error"],
            "suspended": ["running", "deleting", "error"],
            "deleting": ["deleted", "error"],
            "error": ["updating", "deleting"],
            "deleted": []
        }
        cur_status = pool.get("status")
        if cur_status in transitions and "updating" in transitions[cur_status]:
            pool["status"] = "updating"
            pool["updated_at"] = now
        # Complete immediately for offline datastore realism
        op["status"] = "succeeded"
        op["updated_at"] = now
        op["finished_at"] = now
        # Return pool to running if allowed
        cur_status2 = pool.get("status")
        if cur_status2 in transitions and "running" in transitions[cur_status2]:
            pool["status"] = "running"
            pool["updated_at"] = now

    _save("kubernetes.json", kube)
    if op is not None:
        _save("operations.json", ops)

    resp = {"node_pool": pool}
    if op is not None:
        resp["operation"] = op

    _record_request(endpoint, "ok", meta={"cluster_id": cluster_id, "node_pool_id": node_pool_id, "changed": list(changed.keys())})
    return resp

