    for r in kube:
        if r.get("id") == cluster_id and r.get("entity_type") == "cluster" and r.get("deleted_at") is None:
            cluster = r
            break
    if not cluster:
        e = _err("NOT_FOUND", "Cluster not found")
        _record_request(endpoint, "error", error=e["error"])
        return e

    pool = None
    for r in kube:
        if r.get("id") == node_pool_id and r.get("entity_type") == "node_pool" and r.get("deleted_at") is None:
            pool = r
            break
    if not pool or pool.get("parent_id") != cluster_id:
        e = _err("NOT_FOUND", "Node pool not found in cluster")
        _record_request(endpoint, "error", error=e["error"])
        return e

