    op["updated_at"] = now
    op["finished_at"] = now

    _save("kubernetes.json", kube)
    _save("operations.json", ops)

    resp = {"operation": op}
    _record_request(endpoint, "ok", meta={"cluster_id": cluster_id, "node_pool_id": node_pool_id})
