        "request": {"cluster_id": cluster_id, "node_pool_id": node_pool_id, "node_ids": list(node_ids)},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    }
    ops.append(op)
    pool["last_operation_id"] = op_id
    pool["status"] = "recycling"
    pool["updated_at"] = now

    # mark nodes as recycling (then running)
    for nid in node_ids:
        n = nodes_by_id[nid]
        n["last_operation_id"] = op_id
        # node lifecycle shares same enum; prefer recycling if allowed else updating
        ns = n.get("status")
        if ns in transitions and "recycling" in transitions[ns]:
            n["status"] = "recycling"
        elif ns in transitions and "updating" in transitions[ns]:
            n["status"] = "updating"
        else:
            n["status"] = "recycling"
        n["updated_at"] = now
        # simulate replacement completion
        if "running" in transitions.get(n["status"], []):
            n["status"] = "running"
            n["updated_at"] = now

    # complete operation and restore pool
    op["status"] = "succeeded"
    op["result"] = {"recycled_node_ids": list(node_ids)}
    op["updated_at"] = now
    op["finished_at"] = now
    if "running" in transitions.get(pool["status"], []):
        pool["status"] = "running"
        pool["updated_at"] = now

    _save("kubernetes.json", kube)
    _save("operations.json", ops)

    resp = {"operation": op, "node_pool": pool, "nodes": [nodes_by_id[nid] for nid in node_ids]}
    _record_request(endpoint, "ok", meta={"cluster_id": cluster_id, "node_pool_id": node_pool_id, "node_count": len(node_ids)})
    return resp

def list_kubernetes_versions(status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_request(endpoint, status_s, meta=None, error=None):
        for fname in ("request_log.json", "requests.json", "usage.json", "audit_log.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                rows = _load(fname)
                row = {
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": endpoint,
                    "status": status_s,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                }
                if meta is not None:
                    row["meta"] = meta
                if error is not None:
                    row["error"] = error
                rows.append(row)
                _save(fname, rows)
                return

    def _check_limits(endpoint):
        log_file = None
        for fname in ("request_log.json", "requests.json", "usage.json", "audit_log.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                log_file = fname
                break
        if not log_file:
            return None
        logs = _load(log_file)
        now_dt = datetime.datetime.utcnow()

        if os.path.exists(os.path.join(_DB, "rate_limits.json")):
            limits = _load("rate_limits.json")
            if isinstance(limits, list):
                for lim in limits:
                    endpoints = lim.get("endpoints")
                    if endpoints and endpoint not in endpoints:
                        continue
                    try:
                        window = int(lim.get("window_seconds", 60))
                        mx = int(lim.get("max_requests", 0))
                    except Exception:
                        continue
                    if mx <= 0:
                        continue
                    cutoff = now_dt - datetime.timedelta(seconds=window)
                    cnt = 0
                    for r in logs[::-1]:
                        ts = r.get("timestamp") or r.get("created_at")
                        if not ts:
                            continue
                        try:
                            rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if rdt < cutoff:
                            break
                        if r.get("endpoint") == endpoint:
                            cnt += 1
                    if cnt >= mx:
                        return _err("RATE_LIMIT", "Rate limit exceeded", limit=mx, window_seconds=window)

        if os.path.exists(os.path.join(_DB, "quotas.json")):
            quotas = _load("quotas.json")
            if isinstance(quotas, list):
                for q in quotas:
                    endpoints = q.get("endpoints")
                    if endpoints and endpoint not in endpoints:
                        continue
                    period = q.get("period", "day")
                    try:
                        mx = int(q.get("max_requests", 0))
                    except Exception:
                        continue
                    if mx <= 0:
                        continue
                    cutoff = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0) if period == "month" else now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
                    cnt = 0
                    for r in logs:
                        if r.get("endpoint") != endpoint:
                            continue
                        ts = r.get("timestamp") or r.get("created_at")
                        if not ts:
                            continue
                        try:
                            rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if rdt >= cutoff:
                            cnt += 1
                    if cnt >= mx:
                        return _err("QUOTA_EXCEEDED", "Quota exceeded", limit=mx, period=period)
        return None

    endpoint = "list_kubernetes_versions"
    lim_err = _check_limits(endpoint)
    if lim_err:
        _record_request(endpoint, "error", error=lim_err["error"])
        return lim_err

    # validate
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated", "unavailable"):
            e = _err("VALIDATION_ERROR", "Invalid status filter")
            _record_request(endpoint, "error", error=e["error"])
            return e
    if limit is not None:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer")
            _record_request(endpoint, "error", error=e["error"])
            return e
        if limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 200")
            _record_request(endpoint, "error", error=e["error"])
            return e
    else:
        limit = 100

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string")
        _record_request(endpoint, "error", error=e["error"])
        return e
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "label"):
            e = _err("VALIDATION_ERROR", "Invalid sort_by")
            _record_request(endpoint, "error", error=e["error"])
            return e
    else:
        sort_by = "label"
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            e = _err("VALIDATION_ERROR", "Invalid sort_order")
            _record_request(endpoint, "error", error=e["error"])
            return e
    else:
        sort_order = "asc"

    catalog = _load("infra_catalog.json")

    # auth ambient: permit if catalog exists (if none, treat as unauthorized as per tool description)
    if not isinstance(catalog, list) or len(catalog) == 0:
        e = _err("UNAUTHORIZED", "Not permitted to read Kubernetes catalog data")
        _record_request(endpoint, "error", error=e["error"])
        return e

    rows = [r for r in catalog if r.get("catalog_type") == "k8s_version"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # sort
    reverse = (sort_order == "desc")
    def _key(r):
        v = r.get(sort_by)
        return (v is None, v)
    try:
        rows.sort(key=_key, reverse=reverse)
    except Exception:
        # fallback stable sort by id
        rows.sort(key=lambda r: (r.get("id") is None, r.get("id")), reverse=reverse)

    # pagination cursor as integer offset encoded as "off_<n>"
    offset = 0
    if cursor:
        if cursor.startswith("off_"):
            try:
                offset = int(cursor[4:])
                if offset < 0:
                    raise ValueError()
            except Exception:
                e = _err("VALIDATION_ERROR", "Invalid cursor")
                _record_request(endpoint, "error", error=e["error"])
                return e
        else:
            e = _err("VALIDATION_ERROR", "Invalid cursor")
            _record_request(endpoint, "error", error=e["error"])
            return e

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = ("off_" + str(next_off)) if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _record_request(endpoint, "ok", meta={"returned": len(page), "total": total})
    return resp

def get_kubernetes_kubeconfig(cluster_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "get_kubernetes_kubeconfig"
    status_code = "succeeded"
    out = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, error_code=None, message=None, resource_id=None):
        # No request-log collection defined in schema; do nothing.
        return

    try:
        if not isinstance(cluster_id, str):
            out = _err("VALIDATION_ERROR", "cluster_id must be a string.")
            status_code = "failed"
            return out
        if not re.match(r"^lke_[0-9A-Z]{17,}$", cluster_id):
            out = _err("VALIDATION_ERROR", "cluster_id is malformed.")
            status_code = "failed"
            return out

        kube = _load("kubernetes.json")
        cluster = next((r for r in kube if r.get("id") == cluster_id and r.get("entity_type") == "cluster"), None)
        if not cluster or cluster.get("deleted_at") is not None:
            out = _err("NOT_FOUND", "Kubernetes cluster not found.")
            status_code = "failed"
            return out

        st = cluster.get("status")
        # Must be in a state where credentials can be issued.
        if st in ("provisioning", "deleting", "deleted", "error", "suspended", "updating", "recycling"):
            out = _err("CONFLICT", f"Kubeconfig is not available while cluster is in state '{st}'.")
            status_code = "failed"
            return out

        access = cluster.get("access") or {}
        enc = access.get("encrypted_kubeconfig")
        if not enc:
            # Treat missing secret as unauthorized/unavailable credential.
            out = _err("UNAUTHORIZED", "You do not have access to this cluster's kubeconfig.")
            status_code = "failed"
            return out

        # "Decrypt" per schema rule: secrets are stored encrypted-at-rest. Offline store holds the blob;
        # return a decoded form when it looks like base64, else return as-is.
        kubeconfig = None
        if isinstance(enc, str):
            try:
                kubeconfig = base64.b64decode(enc.encode("utf-8"), validate=True).decode("utf-8", "replace")
            except Exception:
                kubeconfig = enc
        else:
            out = _err("UNAUTHORIZED", "You do not have access to this cluster's kubeconfig.")
            status_code = "failed"
            return out

        out = {
            "cluster_id": cluster_id,
            "kubeconfig": kubeconfig,
            "rotated_at": access.get("rotated_at"),
        }
        return out
    finally:
        try:
            _log_call(status_code, out.get("error", {}).get("code") if isinstance(out, dict) else None,
                      out.get("error", {}).get("message") if isinstance(out, dict) else None,
                      resource_id=cluster_id)
        except Exception:
            pass

def delete_kubernetes_node(cluster_id, node_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(cluster_id, str) or not re.match(r"^lke_01H8[0-9A-Z]{15,}$", cluster_id):
        return _err("VALIDATION_ERROR", "cluster_id is malformed.")
    if not isinstance(node_id, str) or not re.match(r"^lken_01H8[0-9A-Z]{15,}$", node_id):
        return _err("VALIDATION_ERROR", "node_id is malformed.")

    # Load
    kube = _load("kubernetes.json")
    ops = _load("operations.json")

    def _log(status, endpoint, op_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "operation_id": op_id,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        # Basic rate limit: 120 requests/min per endpoint (ambient auth)
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in logs:
            try:
                if r.get("endpoint") == endpoint and isinstance(r.get("ts"), str) and r["ts"] >= cutoff:
                    recent += 1
            except Exception:
                continue
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    endpoint = "delete_kubernetes_node"
    limited = _enforce_limits(endpoint)
    if limited:
        _log("error", endpoint, extra={"error_code": limited["error"]["code"]})
        return limited

    # Resolve cluster
    cluster = next((e for e in kube if e.get("id") == cluster_id and e.get("entity_type") == "cluster" and e.get("deleted_at") is None), None)
    if not cluster:
        _log("error", endpoint, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Cluster not found.")

    # Resolve node and ownership: node -> node_pool -> cluster
    node = next((e for e in kube if e.get("id") == node_id and e.get("entity_type") == "node" and e.get("deleted_at") is None), None)
    if not node:
        _log("error", endpoint, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Node not found.")

    pool = next((e for e in kube if e.get("id") == node.get("parent_id") and e.get("entity_type") == "node_pool" and e.get("deleted_at") is None), None)
    if not pool or pool.get("parent_id") != cluster_id:
        _log("error", endpoint, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Node not found in the specified cluster.")

    # State conflict checks
    # Do not allow delete if already deleting/deleted
    if node.get("status") in ("deleting", "deleted"):
        _log("error", endpoint, extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Node cannot be deleted in its current state.", current_status=node.get("status"))

    # Kubernetes lifecycle transitions: allow to 'deleting' from running/updating/recycling/suspended/error/provisioning
    allowed_from = set(["provisioning", "running", "updating", "recycling", "error", "suspended"])
    if node.get("status") not in allowed_from:
        _log("error", endpoint, extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Node cannot be deleted in its current state.", current_status=node.get("status"))

    # Only one running operation per resource
    for o in ops:
        if o.get("resource_collection") == "kubernetes" and o.get("resource_id") == node_id and o.get("status") == "running":
            _log("error", endpoint, extra={"error_code": "CONFLICT"})
            return _err("CONFLICT", "Another operation is already running for this node.")

    # Create operation (async)
    op_id = "op_" + uuid.uuid4().hex
    op = {
        "id": op_id,
        "resource_collection": "kubernetes",
        "resource_id": node_id,
        "operation_type": "delete",
        "status": "running",
        "request": {"cluster_id": cluster_id, "node_id": node_id},
        "result": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    ops.append(op)

    # Mutate node
    node["status"] = "deleting"
    node["last_operation_id"] = op_id
    node["updated_at"] = now

    _save("operations.json", ops)
    _save("kubernetes.json", kube)

    _log("ok", endpoint, op_id=op_id)
    return {"operation": op}

