def delete_kubernetes_service_token(cluster_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(cluster_id, str) or not re.match(r"^lke_01H8[0-9A-Z]{15,}$", cluster_id):
        return _err("VALIDATION_ERROR", "cluster_id is malformed.")

    kube = _load("kubernetes.json")
    ops = _load("operations.json")

    def _log(status, endpoint, op_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "operation_id": op_id,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in logs:
            try:
                if r.get("endpoint") == endpoint and isinstance(r.get("ts"), str) and r["ts"] >= cutoff:
                    recent += 1
            except Exception:
                continue
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    endpoint = "delete_kubernetes_service_token"
    limited = _enforce_limits(endpoint)
    if limited:
        _log("error", endpoint, extra={"error_code": limited["error"]["code"]})
        return limited

    cluster = next((e for e in kube if e.get("id") == cluster_id and e.get("entity_type") == "cluster" and e.get("deleted_at") is None), None)
    if not cluster:
        _log("error", endpoint, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Cluster not found.")

    # Conflict: cluster state must allow token revocation
    if cluster.get("status") not in ("running", "updating", "recycling", "suspended"):
        _log("error", endpoint, extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Cluster is not in a state that allows service token revocation.", current_status=cluster.get("status"))

    access = cluster.get("access")
    if not isinstance(access, dict):
        access = {}
        cluster["access"] = access

    if not access.get("encrypted_service_token"):
        _log("error", endpoint, extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "No service token exists to delete.")

    # Only one running op per cluster (resource_id=cluster_id) for this collection
    for o in ops:
        if o.get("resource_collection") == "kubernetes" and o.get("resource_id") == cluster_id and o.get("status") == "running":
            _log("error", endpoint, extra={"error_code": "CONFLICT"})
            return _err("CONFLICT", "Another operation is already running for this cluster.")

    # Record operation
    op_id = "op_" + uuid.uuid4().hex
    op = {
        "id": op_id,
        "resource_collection": "kubernetes",
        "resource_id": cluster_id,
        "operation_type": "delete",
        "status": "succeeded",
        "request": {"cluster_id": cluster_id, "action": "delete_service_token"},
        "result": {"cleared_fields": ["access.encrypted_service_token"]},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": now,
    }
    ops.append(op)

    # Mutate cluster: clear token, bump rotated_at for audit of access material change
    access["encrypted_service_token"] = None
    access["rotated_at"] = now
    cluster["last_operation_id"] = op_id
    cluster["updated_at"] = now

    _save("operations.json", ops)
    _save("kubernetes.json", kube)

    _log("ok", endpoint, op_id=op_id)
    return {"revoked": True, "operation": op}

def get_kubernetes_version(k8s_version_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0547000" if __import__("os").path.isdir("./environment_mix/0547000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_kubernetes_version"

    def _log(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Rate limiting / quota (best-effort, only if a quota config exists)
    def _enforce_limits(credential_id=None):
        limits = _load("usage_limits.json")
        if not limits:
            return None
        cfg = limits[0] if isinstance(limits, list) and limits else limits
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        # rate limit per minute
        rpm = None
        if isinstance(cfg, dict):
            rpm = cfg.get("requests_per_minute") or cfg.get("rpm")
        if isinstance(rpm, int) and rpm > 0:
            cutoff = (now - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for r in logs:
                if r.get("endpoint") and r.get("created_at") and r.get("created_at") >= cutoff:
                    if credential_id is None or r.get("credential_id") == credential_id:
                        recent += 1
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        # quota per day
        qpd = None
        if isinstance(cfg, dict):
            qpd = cfg.get("requests_per_day") or cfg.get("qpd")
        if isinstance(qpd, int) and qpd > 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat() + "Z"
            today = 0
            for r in logs:
                if r.get("endpoint") and r.get("created_at") and r.get("created_at") >= day_start:
                    if credential_id is None or r.get("credential_id") == credential_id:
                        today += 1
            if today >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    # Ambient auth: choose any account/workspace context that allows catalog reads.
    # If there is a permissions collection, enforce it; otherwise allow.
    def _authorize_catalog_view():
        perms = _load("permissions.json")
        if not perms:
            return True, None
        # Find any permission row that grants catalog read
        for p in perms:
            if p.get("can_view_catalog") is True or p.get("scope") in ("catalog:read", "read:catalog"):
                return True, p.get("credential_id") or p.get("id")
        return False, None

    try:
        if not isinstance(k8s_version_id, str) or not k8s_version_id.strip():
            e = _err("VALIDATION_ERROR", "k8s_version_id must be a non-empty string.")
            _log(400, None, e["error"]["code"])
            return e

        pat = re.compile(r"^(cat_01H8[0-9A-Z]{15,}|[0-9]+\.[0-9]+(\.[0-9]+)?(-[A-Za-z0-9.-]+)?)$")
        if not pat.match(k8s_version_id):
            e = _err("VALIDATION_ERROR", "k8s_version_id must be a catalog ID or a semantic version string.", pattern=pat.pattern)
            _log(400, None, e["error"]["code"])
            return e

        ok, cred = _authorize_catalog_view()
        if not ok:
            e = _err("UNAUTHORIZED", "Not permitted to view catalog entries.")
            _log(403, None, e["error"]["code"])
            return e

        lim = _enforce_limits(cred)
        if lim:
            _log(429, cred, lim["error"]["code"])
            return lim

        catalog = _load("infra_catalog.json")
        # Match by id OR by version string. For version string, accept either spec.version or spec.slug.
        match = None
        for item in catalog:
            if item.get("catalog_type") != "k8s_version":
                continue
            if item.get("id") == k8s_version_id:
                match = item
                break
            spec = item.get("spec") or {}
            if isinstance(spec, dict):
                if spec.get("version") == k8s_version_id or spec.get("slug") == k8s_version_id:
                    match = item
                    break
            if item.get("label") == k8s_version_id:
                match = item
                break

        if not match:
            e = _err("NOT_FOUND", "No Kubernetes version matches the provided identifier.")
            _log(404, cred, e["error"]["code"])
            return e

        resp = {"data": match}
        _log(200, cred, None)
        return resp
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _log(500, None, e["error"]["code"])
        return e

def list_kubernetes_types(page=None, page_size=None, status=None, **_extra):
