        lim = _enforce_limits(cred)
        if lim:
            _log(429, cred, lim["error"]["code"])
            return lim

        catalog = _load("infra_catalog.json")
        rows = []
        for item in catalog:
            if item.get("catalog_type") != "k8s_type":
                continue
            if status is not None and item.get("status") != status:
                continue
            rows.append(item)

        # Deterministic sort: active first? Real APIs often sort by label; do that.
        def _sort_key(x):
            return (str(x.get("label") or ""), str(x.get("id") or ""))
        rows.sort(key=_sort_key)

        total = len(rows)
        start = (page - 1) * page_size
        end = start + page_size
        data = rows[start:end] if start < total else []
        pages = (total + page_size - 1) // page_size if page_size else 0

        resp = {
            "data": data,
            "meta": {
                "page": page,
                "page_size": page_size,
                "pages": pages,
                "total": total,
                "has_more": end < total
            }
        }
        _log(200, cred, None)
        return resp
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _log(500, None, e["error"]["code"])
        return e
